 widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_easypost\\" help=\\"Compute shipping costs and ship with Easypost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_easypost\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_sendcloud\\" help=\\"Compute shipping costs and ship with Sendcloud\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_sendcloud\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_shiprocket\\" help=\\"Compute shipping costs and ship with Shiprocket\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_shiprocket\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_starshipit\\" help=\\"Compute shipping costs and ship with Starshipit\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_starshipit\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_envia\\" help=\\"Compute shipping costs and ship with Envia.com\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_envia\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Invoicing\\" name=\\"invoicing_setting_container\\">\\n                        <setting id=\\"sales_settings_invoicing_policy\\" title=\\"This default value is applied to any new product created. This can be changed in the product detail form.\\" documentation=\\"/applications/sales/sales/invoicing/invoicing_policy.html\\" help=\\"Quantities to invoice from sales orders\\">\\n                            <field name=\\"default_invoice_policy\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                        </setting>\\n                        <setting id=\\"automatic_invoicing\\" help=\\"Generate the invoice automatically when the online payment is confirmed\\" invisible=\\"default_invoice_policy != 'order' or not portal_confirmation_pay\\">\\n                            <field name=\\"automatic_invoice\\"/>\\n                            <div invisible=\\"not automatic_invoice\\" groups=\\"base.group_no_one\\">\\n                                <label for=\\"invoice_mail_template_id\\" class=\\"o_light_label me-2\\"/>\\n                                <field name=\\"invoice_mail_template_id\\" class=\\"oe_inline\\" options=\\"{'no_create': True}\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"setting_commission\\" help=\\"Manage Sales &amp; teams targets and commissions\\">\\n                            <field name=\\"module_sale_commission\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Connectors\\" id=\\"connectors_setting_container\\">\\n                        <setting id=\\"amazon_connector\\" documentation=\\"/applications/sales/sales/amazon_connector/setup.html\\" help=\\"Import Amazon orders and sync deliveries\\">\\n                            <field name=\\"module_sale_amazon\\" widget=\\"upgrade_boolean\\"/>\\n                            <div class=\\"content-group\\" name=\\"amazon_connector\\" invisible=\\"not module_sale_amazon\\"/>\\n                        </setting>\\n                        <setting id=\\"gelato\\" documentation=\\"/applications/sales/sales/gelato.html\\" help=\\"Place orders through Gelato's print-on-demand service\\">\\n                            <field name=\\"module_sale_gelato\\"/>\\n                            <div class=\\"content-group\\" name=\\"gelato_credentials\\" invisible=\\"not module_sale_gelato\\"/>\\n                        </setting>\\n                        <setting id=\\"shopee_connector\\" help=\\"Import Shopee orders and sync deliveries\\">\\n                            <field name=\\"module_sale_shopee\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                </app>\\n            </xpath>", "es_ES": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                <app notApp=\\"1\\" string=\\"Ventas\\" data-string=\\"Sales\\" name=\\"sale_management\\" groups=\\"sales_team.group_sale_manager\\">\\n                    <block title=\\"Catálogo de productos\\" name=\\"catalog_setting_container\\">\\n                        <setting id=\\"variant_options\\" help=\\"Vende variantes de un producto utilizando atributos (tamaño, color, etc.)\\" documentation=\\"/applications/sales/sales/products_prices/products/variants.html\\">\\n                            <field name=\\"group_product_variant\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_product_variant\\">\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"179\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Atributos\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting string=\\"Entrada de cuadrícula de variante\\" help=\\"Añada varias variantes a un pedido desde una cuadrícula\\" id=\\"product_matrix\\">\\n                            <field name=\\"module_sale_product_matrix\\"/>\\n                        </setting>\\n                        <setting id=\\"uom_settings\\" help=\\"Venda y compre productos en diferentes unidades de medida o embalajes\\">\\n                            <field name=\\"group_uom\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_uom\\">\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"100\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Unidades y embalajes\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"email_template\\" title=\\"Enviar un correo electrónico es útil si necesita compartir información específica o contenido acerca de un producto (instrucciones, reglas, enlaces, medios, etc.). Cree y configure la plantilla de correo electrónico desde el formulario de detalles del producto (en la pestaña de Contabilidad).\\" string=\\"Enviar contenido por correo electrónico\\" help=\\"Enviar un correo electrónico específico para el producto una vez que se valide la factura\\">\\n                            <field name=\\"module_product_email_template\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Precio\\" id=\\"pricing_setting_container\\">\\n                      <setting id=\\"discount_sale_order_lines\\" title=\\"Aplique descuentos manuales en las líneas de pedido de venta o visualice descuentos calculados a partir de listas de precios (opción a activar en la configuración de la lista de precios).\\" help=\\"Ofrece descuentos en las líneas de los pedidos de venta\\">\\n                            <field name=\\"group_discount_per_so_line\\"/>\\n                       </setting>\\n                        <setting id=\\"coupon_settings\\" title=\\"Impulsa tus ventas con distintos tipos de programas: cupones, promociones, tarjetas regalo y fidelización. Se pueden definir condiciones específicas (productos, clientes, importe mínimo de compra, período). Las recompensas pueden ser descuentos (% o importe) o productos gratuitos.\\" string=\\"Promociones, programas de fidelización y tarjetas regalo\\" help=\\"Gestiona promociones, cupones, tarjetas de fidelidad, tarjetas regalo y monederos electrónicos\\">\\n                            <field name=\\"module_loyalty\\"/>\\n                        </setting>\\n                        <setting id=\\"pricelist_configuration\\" documentation=\\"/applications/sales/sales/products_prices/prices/pricing.html\\" help=\\"Define varios precios por producto, descuentos automáticos, etc.\\">\\n                            <field name=\\"group_product_pricelist\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_product_pricelist\\">\\n                                <div class=\\"mt16\\">\\n                                    <button name=\\"182\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Listas de precios\\" groups=\\"product.group_product_pricelist\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"auth_signup_documents\\" title=\\"Para enviar invitaciones en modo B2B, abra un contacto o seleccione varios en la vista de lista y haga clic en la opción 'Gestión de acceso al portal' del menú desplegable *Acción*.\\" help=\\"Deje que sus clientes inicien sesión para ver sus documentos\\">\\n                            <field name=\\"auth_signup_uninvited\\" class=\\"o_light_label\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\" required=\\"True\\"/>\\n                        </setting>\\n                        <setting id=\\"show_margins\\" help=\\"Mostrar márgenes en pedidos\\" title=\\"El margen se calcula como la suma de los precios de venta del producto menos el coste establecido en su forma detallada.\\">\\n                            <field name=\\"module_sale_margin\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Presupuestos y pedidos\\" name=\\"quotation_order_setting_container\\">\\n                        <setting id=\\"online_signature\\" company_dependent=\\"1\\" documentation=\\"/applications/sales/sales/send_quotations/get_signature_to_validate.html\\" help=\\"Solicite a los clientes que firmen presupuestos para validar pedidos. El valor por defecto puede cambiarse por pedido o plantilla.\\">\\n                            <field name=\\"portal_confirmation_sign\\"/>\\n                        </setting>\\n                        <setting id=\\"online_payment\\" company_dependent=\\"1\\" documentation=\\"/applications/sales/sales/send_quotations/get_paid_to_validate.html\\" help=\\"Solicite un pago para confirmar pedidos, ya sea total (100 %) o parcial. El valor por defecto puede cambiarse por pedido o plantilla.\\">\\n                            <field name=\\"portal_confirmation_pay\\"/>\\n                            <div invisible=\\"not portal_confirmation_pay\\" class=\\"oe_row fw-bold\\">\\n                                Pagos\\n                                <field name=\\"prepayment_percent\\" widget=\\"percentage\\" class=\\"oe_inline\\"/>\\n                            </div>\\n                            <div class=\\"row mt8\\" invisible=\\"not portal_confirmation_pay or active_provider_id\\">\\n                                <div invisible=\\"not onboarding_payment_module\\" class=\\"oe_inline\\">\\n                                    <button type=\\"object\\" name=\\"action_sale_start_payment_onboarding\\" class=\\"btn-primary\\">\\n                                        Activar\\n                                        <field name=\\"onboarding_payment_module\\" nolabel=\\"1\\" class=\\"oe_inline\\"/>\\n                                    </button>\\n                                </div>\\n                                <div title=\\"Stripe Connect no está disponible en su país, use otro proveedor de pago.\\" invisible=\\"onboarding_payment_module\\" class=\\"oe_inline\\">\\n                                    <button string=\\"Activar Stripe\\" class=\\"btn btn-primary\\" disabled=\\"\\"/>\\n                                </div>\\n                                <button string=\\"Ver alternativas\\" type=\\"action\\" name=\\"324\\" icon=\\"oi-arrow-right\\" class=\\"btn btn-link oe_inline\\"/>\\n                            </div>\\n                            <div class=\\"mt8\\" invisible=\\"not portal_confirmation_pay or not active_provider_id\\">\\n                                <button type=\\"object\\" name=\\"action_view_active_provider\\" class=\\"btn btn-primary col-auto\\">\\n                                    Configurar\\n                                    <field name=\\"active_provider_id\\" class=\\"oe_inline\\" nolabel=\\"1\\" options=\\"{'no_open': True}\\"/>\\n                                </button>\\n                                <button string=\\"Ver otros proveedores\\" type=\\"action\\" name=\\"324\\" icon=\\"oi-arrow-right\\" class=\\"btn btn-link col-auto\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"quotation_validity_days\\">\\n                            <div title=\\"Dias entre la propuesta de presupuesto y el vencimiento, 0 días significa que el vencimiento automático está deshabilitado\\">\\n                                <label for=\\"quotation_validity_days\\"/>\\n                                <field name=\\"quotation_validity_days\\" class=\\"text-center\\" style=\\"width: 3rem;\\"/>\\n                                <div class=\\"d-inline-block\\">días</div>\