\">\\n                            <field name=\\"module_delivery\\"/>\\n                        </setting>\\n                        <setting id=\\"ups\\">\\n                            <div class=\\"o_form_label\\">Conector de UPS</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentación\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Calcule los gastos de envío y envíe con UPS<br/>\\n                                    <strong>(vaya a Inicio&gt;Aplicaciones para instalar el módulo)</strong>\\n                                </div>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_dhl\\">\\n                            <div class=\\"o_form_label\\">Conector de DHL</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentación\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Calcule los gastos de envío y envíe con DHL<br/>\\n                                    <strong>(vaya a Inicio&gt;Aplicaciones para instalar el módulo)</strong>\\n                                </div>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_fedex\\">\\n                            <div class=\\"o_form_label\\">Conector de FedEx</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentación\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Calcule los gastos de envío y envíe con FedEx<br/>\\n                                    <strong>(vaya a Inicio&gt;Aplicaciones para instalar el módulo)</strong>\\n                                </div>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_usps\\">\\n                            <div class=\\"o_form_label\\">Conector de USPS</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentación\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Calcule los gastos de envío y envíe con USPS<br/>\\n                                    <strong>(vaya a Inicio&gt;Aplicaciones para instalar el módulo)</strong>\\n                                </div>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_bpost\\" help=\\"Calcule los gastos de envío y envíe con bpost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_bpost\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_easypost\\" help=\\"Calcule los gastos de envío y envíe con Easypost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_easypost\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_sendcloud\\" help=\\"Calcule los gastos de envío y envíe con Sendcloud\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                     