\\">\\n                            <field name=\\"module_base_import\\"/>\\n                        </setting>\\n                        <setting id=\\"feedback_motivate_setting\\" help=\\"Añada comentarios divertidos y motive a sus empleados\\" groups=\\"base.group_no_one\\">\\n                            <field name=\\"show_effect\\"/>\\n                        </setting>\\n                    </block>\\n\\n                    <block title=\\"Aplicación web progresiva\\" id=\\"pwa_settings\\" groups=\\"base.group_no_one\\">\\n                        <setting help=\\"Este nombre se utilizará para la aplicación cuando se instale Odoo a través del navegador.\\">\\n                            <field name=\\"web_app_name\\" placeholder=\\"Odoo\\"/>\\n                        </setting>\\n                    </block>\\n\\n                        <block title=\\"Integraciones\\" name=\\"integration\\">\\n                            <setting string=\\"Plugin de correo\\" documentation=\\"/applications/productivity/mail_plugins.html\\" help=\\"Integre con los complementos de los clientes de correo\\" id=\\"mail_pluggin_setting\\">\\n                                <field name=\\"module_mail_plugin\\"/>\\n                            </setting>\\n                            <setting string=\\"Autenticación OAuth\\" help=\\"Use cuentas externas (Google, Facebook, etc.) para iniciar sesión\\" id=\\"module_auth_oauth\\">\\n                                <field name=\\"module_auth_oauth\\"/>\\n                                <div class=\\"content-group mt16\\" invisible=\\"not module_auth_oauth\\" id=\\"msg_module_auth_oauth\\">\\n                                    <div class=\\"mt16 text-warning\\"><strong>Guarda</strong> esta página y vuelve aquí para configurar la funcionalidad.</div>\\n                                </div>\\n                            </setting>\\n                            <setting string=\\"Autentificación LDAP\\" help=\\"Use credenciales LDAP para ini