tring=\\"Mis actividades\\" name=\\"filter_activities_my\\" domain=\\"[('activity_user_id', '=', uid)]\\"/>\\n                <separator invisible=\\"1\\"/>\\n                <filter name=\\"my_sale_orders_filter\\" string=\\"Mis pedidos\\" domain=\\"[('user_id', '=', uid)]\\"/>\\n                <filter invisible=\\"1\\" string=\\"Actividades atrasadas\\" name=\\"activities_overdue\\" domain=\\"[('my_activity_date_deadline', '&lt;', 'today')]\\" help=\\"Mostrar todos los registros cuya próxima fecha de actividad haya pasado\\"/>\\n                <filter invisible=\\"1\\" string=\\"Actividades de hoy\\" name=\\"activities_today\\" domain=\\"[('my_activity_date_deadline', '=', 'today')]\\"/>\\n                <filter invisible=\\"1\\" string=\\"Actividades futuras\\" name=\\"activities_upcoming_all\\" domain=\\"[('my_activity_date_deadline', '&gt;', 'today')]\\"/>\\n                <group>\\n                    <filter name=\\"salesperson\\" string=\\"Comercial\\" context=\\"{'group_by': 'user_id'}\\"/>\\n                    <filter name=\\"customer\\" string=\\"Cliente\\" context=\\"{'group_by': 'partner_id'}\\"/>\\n                    <filter name=\\"order_month\\" string=\\"Fecha del pedido\\" context=\\"{'group_by': 'date_order'}\\"/>\\n                    <filter name=\\"preferred_payment_method_line_groupby\\" string=\\"Método de pago\\" context=\\"{'group_by': 'preferred_payment_method_line_id'}\\"/>\\n                </group>\\n            </search>"}	<?xml version="1.0"?>\n<search string="Search Sales Order">\n                <field name="name" string="Order" filter_domain="['|', '|', ('name', 'ilike', self), ('client_order_ref', 'ilike', self), ('partner_id', 'child_of', self)]"/>\n                <field name="partner_id" operator="child_of"/>\n                <field name="user_id"/>\n                <field name="team_id" string="Sales Team"/>\n                <field name="order_line" string="Product" filter_domain="[('order_line.product_id', 'ilike', self)]"/>\n                <field name="activity_user_id" string="Activities of"/>\n                <field name="activity_type_id" string="Activity type"/>\n                <!-- We only allow to search on the following sale order line fields (product, name) because the other fields, such as price, quantity, ...\n                    will not be searched as often, and if they need to be searched it's usually in the context of products\n                    and then they can be searched from the page listing the sale order lines related to a product (from the product itself).\n                -->\n                <filter invisible="1" string="My Activities" name="filter_activities_my" domain="[('activity_user_id', '=', uid)]"/>\n                <separator invisible="1"/>\n                <filter name="my_sale_orders_filter" string="My Orders" domain="[('user_id', '=', uid)]"/>\n                <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[('my_activity_date_deadline', '&lt;', 'today')]" help="Show all records whose next activity date is past"/>\n                <filter invisible="1" string="Today Activities" name="activities_today" domain="[('my_activity_date_deadline', '=', 'today')]"/>\n                <filter invisible="1" string="Future Activities" name="activities_upcoming_all" domain="[('my_activity_date_deadline', '&gt;', 'today')]"/>\n                <group>\n                    <filter name="salesperson" string="Salesperson" context="{'group_by': 'user_id'}"/>\n                    <filter name="customer" string="Customer" context="{'group_by': 'partner_id'}"/>\n                    <filter name="order_month" string="Order Date" context="{'group_by': 'date_order'}"/>\n                    <filter name="preferred_payment_method_line_groupby" string="Payment Method" context="{'group_by': 'preferred_payment_method_line_id'}"/>\n                </group>\n            </search>\n        	f	t	2026-11-24 18:55:01.583901	2026-11-24 18:55:01.