d', 'assigned']\\" class=\\"text-muted\\" t-field=\\"picking.scheduled_date\\" t-options=\\"{'date_only': True}\\"/>\\n                            </div>\\n                        </div>\\n                    </t>\\n                </div>\\n            </div>\\n            <t t-set=\\"returns\\" t-value=\\"delivery_orders.return_ids.sorted('create_date', reverse=True)\\"/>\\n            <div t-if=\\"returns\\" class=\\"col-12 col-lg-6 mb-4\\">\\n                <h4 class=\\"mb-1\\">Devoluciones</h4>\\n                <hr class=\\"mt-1 mb-2\\"/>\\n                <t t-foreach=\\"returns\\" t-as=\\"picking\\">\\n                    <t t-set=\\"delivery_report_url\\" t-value=\\"'/my/picking/pdf/%s?%s' % (picking.id, keep_query())\\"/>\\n                    <div name=\\"return\\">\\n                        <div name=\\"return_details\\" class=\\"d-flex justify-content-between align-items-center\\">\\n                            <a t-att-href=\\"delivery_report_url\\">\\n                                <span t-esc=\\"picking.name\\"/>\\n                            </a>\\n                            <span t-if=\\"picking.state == 'done'\\" class=\\"small badge rounded-pill text-bg-success orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-truck\\"/> Recibido\\n                            </span>\\n                            <span t-elif=\\"picking.state == 'cancel'\\" class=\\"small badge rounded-pill text-bg-danger orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-times\\"/> Cancelado\\n                            </span>\\n                            <span t-elif=\\"picking.state in ['draft', 'waiting', 'confirmed', 'assigned']\\" class=\\"small badge rounded-pill text-bg-info orders_label_text_align\\">\\n                                <i class=\\"fa fa-fw fa-clock-o\\"/> Pendiente de llegada\\n                            </span>\\n                        </div>\\n                        <div class=\\"small d-lg-inline-block\\">\\n                            Fecha:\\n                            <span class=\\"text-muted\\" t-field=\\"picking.date_done\\" t-options=\\"{'date_only': True}\\"/>\\n                            <span t-if=\\"picking.state in ['draft', 'waiting', 'confirmed', 'assigned']\\" class=\\"text-muted\\" t-field=\\"picking.scheduled_date\\" t-options=\\"{'date_only': True}\\"/>\\n                        </div>\\n                    </div>\\n                </t>\\n            </div>\\n        </div>\\n    </data>"}	<?xml version="1.0"?>\n<data name="Orders Shipping Followup" inherit_id="sale.sale_order_portal_content">\n        <tbody id="sale_info_table" position="inside">\n            <tr t-if="sale_order.incoterm">\n                <th class="pb-0">Incoterm:</th>\n                <td class="w-100 pb-0 text-wrap">\n                    <p t-if="sale_order.incoterm_location">\n                        <span t-field="sale_order.incoterm.code"/> <br/>\n                        <span t-field="sale_order.incoterm_location"/>\n                    </p>\n                    <p t-else="" t-field="sale_order.incoterm.code" class="m-0"/>\n                </td>\n            </tr>\n        </tbody>\n\n        <div id="sale_invoices" position="after">\n            <t t-set="delivery_orders" t-value="sale_order.picking_ids.filtered(lambda picking: picking.picking_type_id.code == 'outgoing')"/>\n            <t t-set="latest_delivery_orders" t-value="delivery_orders.sorted('create_date', reverse=True)[:3]"/>\n            <div t-if="delivery_orders" class="col-12 col-lg-6 mb-4">\n                <h5 class="mb-1">Last Delivery Orders</h5>\n                <hr class="mt-1 mb-2"/>\n                <div class="d-flex flex-column gap-2">\n                    <t t-foreach="latest_delivery_orders" t-as="picking">\n                        <t t-set="delivery_report_url" t-value="'/my/picking/pdf/%s?%s' % (picking.id, keep_query())"/>\n                        <div name="delivery_order" class="d-flex flex-column">\n                            <div name="delivery_details" class="d-flex align-items-center justify-content-between">\n                                <a t-att-href="delivery_report_url">\n                                    <span t-esc="picking.name"/>\n                                </a>\n                                <div t-if="picking.state == 'done'">\n                                    <span class="small badge rounded-pill text-bg-success orders_label_text_align">\n                                        <i class="fa fa-fw fa-truck"/> Shipped\n                                    </span>\n                                    <a class="badge rounded-pill text-bg-secondary orders_label_text_align" target="_blank" t-att-href="'/my/picking/return/pdf/%s?%s' % (picking.id, keep_query())">\n                                        RETURN\n                                    </a>\n                                </div>\n                                <span t-elif="picking.state == 'cancel'" class="small badge rounded-pill text-bg-danger orders_label_text_align">\n                                    <i class="fa fa-fw fa-times"/>Cancelled\n                                </span>\n                                <span t-elif="picking.state in ['draft', 'waiting', 'confirmed', 'assigned']" class="small badge rounded-pill text-bg-info orders_label_text_align">\n                                    <i class="fa fa-fw fa-clock-o"/>Preparation\n                                </span>\n                            </div>\n                            <div class="small d-lg-inline-block" t-if="picking.date_done or picking.scheduled_date">\n                                Date:\n                                <span class="text-muted" t-field="picking.date_done" t-options="{'date_only': True}"/>\n                                <span t-if="picking.state in ['draft', 'waiting', 'confirmed', 'assigned']" class="text-muted" t-field="picking.scheduled_date" t-options="{'date_only': True}"/>\n                            </div>\n                        </div>\n                    </t>\n                </div>\n            </div>\n            <t t-set="returns" t-value="delivery_orders.return_ids.sorted('create_date', reverse=True)"/>\n            <div t-if="returns" class="col-12 col-lg-6 mb-4">\n                <h4 class="mb-1">Returns</h4>\n                <hr class="mt-1 mb-2"/>\n                <t t-foreach="returns" t-as="picking">\n                    <t t-set="delivery_report_url" t-value="'/my/picking/pdf/%s?%s' % (picking.id, keep_query())"/>\n                    <div name="return">\n                        <div name="return_details" class="d-flex justify-content-between align-items-center">\n                            <a t-att-href="delivery_report_url">\n                                <span t-esc="picking.name"/>\n                            </a>\n                            <span t-if="picking.state == 'done'" class="small badge rounded-pill text-bg-success orders_label_text_align">\n                                <i class="fa fa-fw fa-truck"/> Received\n                            </span>\n                            <span t-elif="picking.state == 'cancel'" class="small badge rounded-pill text-bg-danger orders_label_text_align">\n                                <i class="fa fa-fw fa-times"/> Cancelled\n                            </span>\n                            <span t-elif="picking.state in ['draft', 'waiting', 'confirmed', 'assigned']" class="small badge rounded-pill text-bg-info orders_label_text_align">\n                                <i class="fa fa-fw fa-clock-o"/> Awaiting arrival\n                            </span>\n                        </div>\n                        <div class="small d-lg-inline-block">\n                            Date:\n                            <span class="text-muted" t-field="picking.date_done" t-options="{'date_only': True}"/>\n              