oduct.product - visitor can access product average rating -->\\n                                        <t t-set=\\"rating_avg\\" t-value=\\"record.sudo().rating_avg\\"/>\\n                                        <t t-set=\\"rating_count\\" t-value=\\"record.rating_count\\"/>\\n                                    </t>\\n                                </div>\\n                            </div>\\n                        </div>\\n                        <div class=\\"o_wsale_product_sub justify-content-between gap-2\\">\\n                            <!-- Price(s) -->\\n                            <div class=\\"product_price\\" aria-label=\\"Price information\\">\\n                                <t t-call=\\"website_sale.price_dynamic_filter_template_product_product\\"/>\\n                            </div>\\n                            <!-- Actions -->\\n                            <div class=\\"o_wsale_product_btn\\">\\n                                <div class=\\"o_wsale_product_action_row\\">\\n                                    <t t-if=\\"product._website_show_quick_add()\\">\\n                                        <button type=\\"button\\" class=\\"o_wsale_product_btn_primary btn js_add_cart\\" title=\\"Add to Cart\\" t-att-data-product-id=\\"product.id if product.is_product_variant else product.product_variant_id.id\\" t-att-data-product-selected=\\"product.is_product_variant\\" t-att-data-product-template-id=\\"product.id if not product.is_product_variant else product.product_tmpl_id.id\\" t-att-data-product-type=\\"product.type\\" t-att-data-show-quantity=\\"is_view_active('website_sale.product_quantity')\\">\\n                                            <!-- Avoid whitespaces undesired gaps -->\\n                                            <i class=\\"fa fa-shopping-cart fa-fw\\" role=\\"presentation\\"/><span class=\\"o_label small ms-1\\">Add to Cart</span>\\n                                        </button>\\n                                    </t>\