lapse" data-bs-target="#o_wsale_offcanvas_orderby" aria-expanded="false" aria-controls="o_wsale_offcanvas_orderby">\n                                <b>Sort By</b>\n                        </button>\n                    </h2>\n                    <div id="o_wsale_offcanvas_orderby" class="accordion-collapse collapse" aria-labelledby="o_wsale_offcanvas_orderby_header">\n                        <div class="accordion-body pt-0">\n                            <div class="list-group list-group-flush">\n                                <a t-foreach="website_sale_sortable" t-as="sortby" role="menuitem" rel="noindex,nofollow" t-att-href="keep(order=sortby[0])" class="list-group-item border-0 ps-0 pb-0">\n                                    <div class="form-check d-inline-block">\n                                        <input type="radio" t-attf-onclick="location.href='#{keep(order=sortby[0])}';" class="form-check-input o_not_editable" name="wsale_sortby_radios_offcanvas" t-att-checked="isSortingBy and isSortingBy == sortby[1]">\n                                            <label class="form-check-label fw-normal" t-out="sortby[1]"/>\n                                        </input>\n                                    </div>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <t t-set="show_attribute_filters" t-value="opt_wsale_attributes or opt_wsale_attributes_top"/>\n                <div t-if="opt_wsale_categories" class="accordion-item d-lg-none">\n                    <h2 id="o_wsale_offcanvas_categories_header" class="accordion-header mb-0">\n                        <button t-attf-class="o_wsale_offcanvas_title accordion-button rounded-0 {{'collapsed' if show_attribute_filters else ''}}" type="button" data-bs-toggle="collapse" data-bs-target="#o_wsale_offcanvas_categories" t-att-aria-expanded="'false' if show_attribute_filters else 'true'" aria-controls="o_wsale_offcanvas_categories">\n                                <b>Categories</b>\n                        </button>\n                    </h2>\n                    <div id="o_wsale_offcanvas_categories" t-attf-class="accordion-collapse collapse {{'show' if not show_attribute_filters else ''}}" aria-labelledby="o_wsale_offcanvas_categories_header">\n                        <div class="accordion-body pt-0">\n                            <t t-call="website_sale.products_categories_list">\n                                <t t-set="isOffcanvas" t-value="true"/>\n                                <t t-set="_titleClasses" t-valuef="d-none"/>\n                                <t t-set="_radioGroup" t-valuef="_offcanvas"/>\n                            </t>\n                        </div>\n                    </div>\n                </div>\n                <t t-if="show_attribute_filters" t-call="website_sale.product_attribute_filters_form">\n                    <t t-set="isMobile" t-value="True"/>\n                </t>\n                <t t-if="opt_wsale_filter_price and show_attribute_filters" t-call="website_sale.filter_products_price">\n                    <t t-set="_classes" t-valuef="o_wsale_offcanvas_title accordion accordion-flush px-4"/>\n                    <t t-set="_classes_title" t-valuef="ms-n1 pt-3 pb-2"/>\n                    <t t-set="isOffcanvas" t-value="True"/>\n                </t>\n            </div>\n            <div class="offcanvas-body d-flex justify-content-between flex-grow-0 flex-shrink-0 border-top overflow-hidden">\n                <a t-attf-class="btn btn-{{navClass}} d-flex py-1 mb-2 {{(not attrib_values and not isFilteringByPrice and not tags) and 'disabled' }}" t-att-aria-disabled="(not attrib_values and not isFilteringByPrice and not tags) and 'true' or 'false'" t-att-href="keep(attribute_values=0, tags=0, min_price=0, max_price=0)" title="Clear Filters">\n                    Clear Filters\n                </a>\n            </div>\n     