2427	16	\N	1	1	Product Attribute Filters Form	\N	website_sale.product_attribute_filters_form	qweb	website_sale/views/templates.xml	primary	{"en_US": "<t name=\\"Product Attribute Filters Form\\" t-name=\\"website_sale.product_attribute_filters_form\\">\\n        <form t-attf-class=\\"js_attributes {{('accordion accordion-flush d-flex flex-column ' + ('border-bottom' if attributes else '')) if isMobile else 'position-relative mb-2'}}\\" method=\\"get\\" t-att-action=\\"keep(attribute_values=0, tags=0)\\">\\n            <t t-set=\\"visible_attributes\\" t-value=\\"len([a for a in attributes if a.value_ids and len(a.value_ids) &gt; 1])\\"/>\\n\\n            <t t-foreach=\\"attributes\\" t-as=\\"a\\">\\n                <t t-set=\\"_status\\" t-value=\\"'inactive'\\"/>\\n                <t t-foreach=\\"a.value_ids\\" t-as=\\"v\\" t-if=\\"v.id in attrib_set\\" t-set=\\"_status\\" t-value=\\"'active'\\"/>\\n                <t t-set=\\"_expand_attributes\\" t-value=\\"_status == 'active' or visible_attributes &lt; 4\\"/>\\n                <div t-if=\\"a.value_ids and len(a.value_ids) &gt; 1\\" t-attf-class=\\"accordion-item {{('border-top-0 ' + ('order-1' if _status == 'active' else 'order-2')) if isMobile else 'nav-item mb-1 rounded-0'}}\\">\\n                    <h2 t-if=\\"isMobile\\" class=\\"accordion-header mb-0\\" t-attf-id=\\"o_wsale_offcanvas_attribute_{{a.id}}_header\\">\\n                        <button t-attf-class=\\"o_wsale_offcanvas_title accordion-button rounded-0 {{'' if _expand_attributes else 'collapsed'}}\\" type=\\"button\\" t-att-data-status=\\"_status\\" data-bs-toggle=\\"collapse\\" t-attf-data-bs-target=\\"#o_wsale_offcanvas_attribute_{{a.id}}\\" t-att-aria-expanded=\\"_expand_attributes\\" t-attf-aria-controls=\\"o_wsale_offcanvas_attribute_{{a.id}}\\">\\n                            <b t-out=\\"a.name\\"/>\\n                        </button>\\n                    </h2>\\n                    <h6 t-else=\\"\\" class=\\"mb-3\\">\\n                    