, 'no_open': True}\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Currencies\\" name=\\"main_currency_setting_container\\">\\n                            <setting id=\\"main_currency\\" string=\\"Main Currency\\" company_dependent=\\"1\\" help=\\"Main currency of your company\\" documentation=\\"/applications/finance/accounting/others/multi_currency.html\\">\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label for=\\"currency_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create_edit': True, 'no_open': True}\\" context=\\"{'active_test': False}\\"/>\\n                                        <field name=\\"group_multi_currency\\" invisible=\\"1\\"/>\\n                                    </div>\\n                                    <div class=\\"mt8\\">\\n                                        <button type=\\"action\\" name=\\"66\\" string=\\"Currencies\\" class=\\"btn-link\\" icon=\\"oi-arrow-right\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"update_exchange_rates\\" invisible=\\"not group_multi_currency\\" help=\\"Update exchange rates automatically\\" documentation=\\"/applications/finance/accounting/others/multi_currency.html\\">\\n                                <field name=\\"module_currency_rate_live\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Customer Invoices\\" id=\\"invoicing_settings\\">\\n                            <setting id=\\"send_invoices_followups\\" help=\\"Send invoices and payment follow-ups by post\\" documentation=\\"/applica