bit\\" class=\\"oe_inline\\" widget=\\"upgrade_boolean\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not module_account_sepa_direct_debit\\">\\n                                    <div class=\\"text-warning mt16 mb4\\">\\n                                        Save this page and come back here to set up the feature.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"qr_code_invoices\\" title=\\"Add a QR-code to your invoices so that your customers can pay instantly with their mobile banking application.\\" string=\\"QR Codes\\" company_dependent=\\"1\\" help=\\"Add a payment QR-code to your invoices\\" documentation=\\"/applications/finance/accounting/receivables/customer_invoices/epc_qr_code.html\\">\\n                                <field name=\\"qr_code\\" class=\\"oe_inline\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Vendor Bills\\" id=\\"account_vendor_bills\\">\\n                            <setting id=\\"autopost_bills\\" help=\\"Propose to validate bills automatically when AI accuracy is right 3 times in a row for a vendor.\\">\\n                                <field name=\\"autopost_bills\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Vendor Payments\\" id=\\"print_vendor_checks_setting_container\\">\\n                            <setting id=\\"print_checks\\" groups=\\"account.group_account_user\\" string=\\"Checks\\" company_dependent=\\"1\\" help=\\"Print checks to pay your vendors\\" documentation=\\"/applications/finance/accounting/payables/pay/check.html\\">\\n                                <field name=\\"module_account_check_printing\\"/>\\n                            </setting>\\n                            <setting id=\\"sepa_payments\\"