product_page_image_ratio" t-att-data-view-track="view_track and '1' or '0'">\n                    <div class="o_wsale_content_contained container d-flex flex-wrap align-items-center py-3">\n                        <div class="d-flex align-items-center flex-grow-1">\n                            <ol class="o_wsale_breadcrumb breadcrumb m-0 p-0">\n                                <li class="breadcrumb-item d-none d-lg-inline-block">\n                                    <a t-att-href="keep(shop_path)">\n                                        <t t-call="website_sale.all_products_link_name"/>\n                                    </a>\n                                </li>\n                                <t t-foreach="category.parents_and_self" t-as="cat">\n                                    <li class="breadcrumb-item d-none d-lg-inline-block">\n                                        <a class="py-2 py-lg-0" t-att-href="keep('%s/category/%s' % (shop_path, slug(cat)))">\n                                            <i class="oi oi-chevron-left d-lg-none me-1" role="img"/>\n                                            <t t-out="cat.name"/>\n                                        </a>\n                                    </li>\n                                </t>\n                                <li class="breadcrumb-item d-none d-lg-inline-block active">\n                                    <span t-field="product.name"/>\n                                </li>\n                                <li class="breadcrumb-item d-lg-none">\n                                    <a t-att-href="category and keep('%s/category/%s' % (shop_path, slug(cat))) or keep(shop_path)">\n                                        <i class="oi oi-chevron-left me-2" role="img"/>\n                                        <t t-if="category.name" t-out="category.name"/>\n                                        <t t-else="" t-call="website_sale.all_products_link_name"/>\n                                    </a>\n                                </li>\n                            </ol>\n                            <div class="d-flex d-md-none gap-2 ms-auto">\n                                <t t-call="website_sale.pricelist_list"/>\n                                <a t-attf-class="o_wsale_product_search_mobile_btn o_not_editable btn btn-{{navClass}} d-none" data-bs-target="#o_wsale_product_search_modal" data-bs-toggle="modal" role="button" title="Search Products" href="#">\n                                    <i class="oi oi-search" role="presentation"/>\n                                </a>\n                            </div>\n                        </div>\n                        <div class="o_wsale_product_top_bar_desktop d-none d-md-inline-flex flex-wrap gap-2 w-auto mb-lg-auto">\n                            <t t-call="website_sale.pricelist_list"/>\n                        </div>\n                    </div>\n                    <div t-attf-class="row align-items-lg-start {{website.product_page_cols_order == 'inverse' and 'flex-lg-row-reverse' or ''}}" id="product_detail_main" data-name="Product Page" t-att-data-image_layout="website.product_page_image_layout">\n                        <div t-attf-class="o_wsale_product_images col o_wsale_sticky_object" t-att-data-image-amount="len(product_variant._get_images() if product_variant else product._get_images())">\n                            <t t-call="website_sale.shop_product_images"/>\n                        </div>\n                        <div id="product_details" t-attf-class="position-relative position-lg-sticky o_wsale_sticky_object col">\n                            <div id="o_wsale_product_details_content" t-attf-class="js_product js_main_product o_wsale_content_contained container">\n\n                                <!-- Product title (purchase not available)-->\n                                <t t-set="is_add_to_cart_possible" t-value="product._is_add_to_cart_possible()"/>\n                                <t t-if="not is_add_to_cart_possible" t-call="website_sale.product_title"/>\n\n                                <form t-if="is_add_to_cart_possible">\n                                    <!-- Product title (purchase available)-->\n                                    <t t-call="website_sale.product_title"/>\n\n                                    <div t-if="not is_view_active('website_sale.cta_wrapper_boxed')" class="o_wsale_product_details_content_section o_wsale_product_details_content_section_price mb-4">\n                                        <t t-call="website_sale.product_price"/>\n                                        <small t-if="'base_unit_price' in combination_info" class="ms-1 text-muted o_base_unit_price_wrapper d-none">\n                                            <t t-call="website_sale.base_unit_price">\n                                                <t t-set="base_unit_price" t-value="combination_info['base_unit_price']"/>\n                                            </t>\n                                        </small>\n                                    </div>\n\n                                    <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n\n                                    <t name="variant_info">\n                                        <input type="hidden" class="o_not_editable product_id" name="product_id" t-att-value="product_variant.id"/>\n                                        <input type="hidden" class="o_not_editable product_template_id" name="product_template_id" t-att-value="product.id"/>\n                                        <input t-if="product.public_categ_ids.ids" type="hidden" class="product_category_id" name="product_category_id" t-att-value="product.public_categ_ids.ids[0]"/>\n                                        <input type="hidden" name="product_type" t-att-value="product.type"/>\n                                        <div t-attf-class="o_wsale_product_details_content_section o_w