            </div>\\n                        </div>\\n                    </div>\\n                    <!-- Mobile Order Summary | Bottom of page and Offcanvas -->\\n                    <t t-if=\\"not show_shorter_cart_summary and show_mobile_cart_summary\\">\\n                        <div class=\\"o_mobile_summary d-lg-none sticky-bottom mt-auto bg-body\\">\\n                            <button class=\\"btn btn-light d-flex justify-content-between align-items-center gap-2 w-100 mb-2\\" data-bs-toggle=\\"offcanvas\\" href=\\"#o_cart_summary_offcanvas\\" aria-controls=\\"o_cart_summary_offcanvas\\">\\n                                Pedido\\n                                <span id=\\"amount_total_summary\\" class=\\"monetary_field ms-auto\\" t-field=\\"website_sale_order.amount_total\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: website_sale_order.currency_id}\\"/>\\n                                <span class=\\"o_cart_item_count badge ms-1 top-0 bg-primary\\" t-out=\\"str(website_sale_order.cart_quantity)\\"/>\\n                                <i class=\\"fa fa-angle-right ms-2\\" role=\\"img\\"/>\\n                            </button>\\n                            <t t-if=\\"show_navigation_button\\" t-call=\\"website_sale.navigation_buttons\\"/>\\n                        </div>\\n                        <div id=\\"o_cart_summary_offcanvas\\" class=\\"offcanvas offcanvas-end\\" tabindex=\\"-1\\" aria-labelledby=\\"o_cart_summary_offcanvas\\">\\n                            <div class=\\"offcanvas-body\\">\\n                                <t t-call=\\"website_sale.cart_summary_content\\"/>\\n                            </div>\\n                            <div class=\\"offcanvas-footer p-3\\">\\n                                <a href=\\"/shop/cart\\" class=\\"btn btn-link w-100\\">\\n                                    ¿Cupón, tarjeta de regalo, código de promoción?\\n                                </a>\\n             