etting id="pricelists_setting" help="Apply specific prices or currency per country, customer, products, etc." documentation="/applications/sales/sales/products_prices/prices/pricing.html">\n                    <field name="group_product_pricelist"/>\n                    <button string="Pricelists" type="action" name="182" groups="product.group_product_pricelist" invisible="not group_product_pricelist" class="btn-link" icon="oi-arrow-right"/>\n                </setting>\n                <setting id="hide_add_to_cart_setting" help="If product price equals 0, replace 'Add to Cart' by 'Contact us'.">\n                    <field name="website_sale_prevent_zero_price_sale"/>\n                    <div class="content-group" invisible="not website_sale_prevent_zero_price_sale">\n                        <div class="row mt16">\n                            <label string="Button URL" for="website_sale_contact_us_button_url" class="o_light_label col-lg-3"/>\n                            <field name="website_sale_contact_us_button_url"/>\n                        </div>\n                    </div>\n                </setting>\n                <setting string="Order Confirmation" id="order_confirmation_setting">\n                    <div class="content-group">\n                        <div class="row mt16">\n                            <label string="Email" for="confirmation_email_template_id" class="o_light_label col-lg-3"/>\n                            <field name="confirmation_email_template_id"/>\n                        </div>\n                    </div>\n                </setting>\n                <setting string="Follow up abandoned carts" id="abandoned_carts_setting" help="Automate abandoned checkout emails" documentation="/applications/websites/ecommerce/ecommerce_management/order_handling.html#abandoned-cart">\n                    <field name="send_abandoned_cart_email"/>\n                    <div invisible="not send_abandoned_cart_email" class="content-group">\n            