2569	16	\N	1	1	Badge Extra Price	\N	website_sale.badge_extra_price	qweb	website_sale/views/variant_templates.xml	primary	{"en_US": "<t name=\\"Badge Extra Price\\" t-name=\\"website_sale.badge_extra_price\\">\\n        <t t-set=\\"price_extra\\" t-value=\\"ptav._get_extra_price(combination_info)\\"/>\\n        <span t-if=\\"price_extra\\" t-attf-class=\\"{{'badge text-bg-primary' if attribute.display_type != 'pills' else 'small text-muted'}}\\">\\n            <!--\\n                price_extra is displayed as catalog price instead of\\n                price after pricelist because it is impossible to\\n                compute. Indeed, the pricelist rule might depend on the\\n                selected variant, so the price_extra will be different\\n                depending on the selected combination. The price of an\\n                attribute is therefore variable and it's not very\\n                accurate to display it.\\n            -->\\n        <t t-if=\\"attribute.display_type in ['pills', 'select']\\">(</t><span class=\\"sign_badge_price_extra\\"><t t-out=\\"price_extra &gt; 0 and '+' or '-'\\"/></span>\\n        <span t-out=\\"abs(price_extra)\\" class=\\"variant_price_extra\\" style=\\"white-space: nowrap;\\" t-options=\\"{                 &quot;widget&quot;: &quot;monetary&quot;,                 &quot;display_currency&quot;: website.currency_id             }\\"/><t t-if=\\"attribute.display_type in ['pills', 'select']\\">)</t>\\n        </span>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Badge Extra Price" t-name="website_sale.badge_extra_price">\n        <t t-set="price_extra" t-value="ptav._get_extra_price(combination_info)"/>\n        <span t-if="price_extra" t-attf-class="{{'badge text-bg-primary' if attribute.display_type != 'pills' else 'small text-muted'}}">\n            <!--\n                price_extra is displayed as catalog price instead of\n                price after pricelist because it is impossible to\n                compute. Indeed, the pricelist rule might depend on the\n                selected variant, so the price_extra will be different\n                depending on the selected combination. The price of an\n                attribute is therefore variable and it's not very\n                accurate to display it.\n            -->\n        <t t-if="attribute.display_type in ['pills', 'select']">(</t><span class="sign_badge_price_extra"><t t-out="price_extra &gt; 0 and '+' or '-'"/></span>\n        <span t-out="abs(price_extra)" class="variant_price_extra" style="white-space: nowrap;" t-options="{                 &quot;widget&quot;: &quot;monetary&quot;,                 &quot;display_currency&quot;: website.currency_id             }"/><t t-if="attribute.display_type in ['pills', 'select']">)</t>\n        </span>\n    </t>\n    	f	t	2026-11-24 18:55:43.321726	2026-11-24 18:55:43.321726	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
