4 class=\\"mb-0\\">Resumen del pedido</h4>\\n                    <div class=\\"ms-3 border-start ps-2\\"><t t-call=\\"website_sale.quick_reorder_button\\"/></div>\\n                </div>\\n                <div t-if=\\"abandoned_proceed or access_token\\" class=\\"alert alert-info mt8 mb8\\" role=\\"alert\\"> <!-- abandoned cart choices -->\\n                    <t t-if=\\"abandoned_proceed\\">\\n                        <p>Se ha completado su cesta anterior.</p>\\n                        <p t-if=\\"website_sale_order\\">Continúe con su cesta actual.</p>\\n                    </t>\\n                    <t t-if=\\"access_token\\">\\n                        <p>Este es su cesta actual.</p>\\n                        <p>\\n                            <strong>\\n                                <a class=\\"o_translate_inline\\" t-attf-href=\\"/shop/cart/?id={{id}}&amp;access_token={{access_token}}&amp;revive_method=squash\\">Haga clic aquí</a>\\n                            </strong> si desea recuperar su carro anterior. Su carro actual será sustituido por el anterior.\\n                        </p>\\n                        <p>\\n                            <strong>\\n                                <a class=\\"o_translate_inline\\" t-attf-href=\\"/shop/cart/?id={{id}}&amp;access_token={{access_token}}&amp;revive_method=merge\\">Haga clic aquí</a>\\n                            </strong> si desea combinar su carro anterior con el actual.\\n                        </p>\\n                    </t>\\n                </div>\\n                <t t-call=\\"website_sale.cart_lines\\"/>\\n                <div class=\\"clearfix\\"/>\\n                <div class=\\"oe_structure\\" id=\\"oe_structure_website_sale_cart_1\\"/>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Shopping Cart" t-name="website_sale.cart">\n        <t t-call="website_sale.checkout_layout">\n            <t t-set="show_shorter_cart_summary" t-value="True"/>\n            <t t-set="show_footer" t-value="True"/>\n            <t t-set="oe_structure">\n                <!-- This is the drag-and-drop area for website building blocs at the end of each\n                     checkout page. This is append at the of the page in `checkout_layout`. The\n                     templates created in the database to store blocs are hooked using XPath on the\n                     `oe_struture` element ID. Therefore, we can't use dynamic IDs (like with\n                     t-att-id) and each template needs to define a div element. -->\n                <div class="oe_structure" id="oe_structure_website_sale_cart_2"/>\n            </t>\n            <div id="shop_cart" class="col">\n                <div class="d-flex align-items-center mb-3">\n                    <h4 class="mb-0">Order summary</h4>\n                    <div class="ms-3 border-start ps-2"><t t-call="website_sale.quick_reorder_button"/></div>\n                </div>\n                <div t-if="abandoned_proceed or access_token" class="alert alert-info mt8 mb8" role="alert"> <!-- abandoned cart choices -->\n                    <t t-if="abandoned_proceed">\n                        <p>Your previous cart has already been completed.</p>\n                        <p t-if="website_sale_order">Please proceed your current cart.</p>\n                    </t>\n                    <t t-if="access_token">\n                        <p>This is your current cart.</p>\n                        <p>\n                            <strong>\n                                <a class="o_translate_inline" t-attf-href="/shop/cart/?id={{id}}&amp;access_token={{access_token}}&amp;revive_method=squash">Click here</a>\n                            </strong> if you want to restore your previous cart. Your current cart will be replaced with your previous cart.\n                        </p>\n                        <p>\n                            <strong>\n                                <a class="o_translate_inline" t-attf-href="/shop/cart/?id={{id}}&amp;access_token={{access_token}}&amp;revive_method=merge">Click here</a>\n                            </strong> if you want to merge your previous cart into current cart.\n                        </p>\n                    </t>\n                </div>\n                <t t-call="website_sale.cart_lines"/>\n                <div class="clearfix"/>\n                <div class="oe_structure" id="oe_structure_website_sale_cart_1"/>\n            </div>\n        </t>\n    </t>\n\n    	f	t	2026-11-24 18:55:43.321726	2026-11-24 18:55:43.321726	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
