2476	16	\N	1	1	Shopping Cart Lines	\N	website_sale.cart_lines	qweb	website_sale/views/templates.xml	primary	{"en_US": "<t name=\\"Shopping Cart Lines\\" t-name=\\"website_sale.cart_lines\\">\\n        <div t-if=\\"not website_sale_order or not website_sale_order.website_order_line\\" class=\\"js_cart_lines w-100\\">\\n            <div class=\\"mt-5 mb-3\\"><t t-call=\\"website_sale.empty_cart_svg\\"/></div>\\n            <h5 class=\\"mb-3\\" style=\\"text-align: center;\\">\\n                Your cart is empty!\\n            </h5>\\n            <p style=\\"text-align: center;\\">\\n                <a href=\\"/shop\\" class=\\"btn btn-primary\\">\\n                    Shop\\n                </a>\\n            </p>\\n        </div>\\n        <t t-if=\\"website_sale_order\\">\\n            <div t-if=\\"website_sale_order._get_shop_warning(clear=False)\\" class=\\"alert alert-warning js_cart_lines\\" role=\\"alert\\">\\n                <strong>Warning!</strong>\\n                <div t-out=\\"website_sale_order._get_shop_warning()\\" class=\\"text-prewrap\\"/>\\n            </div>\\n        </t>\\n        <div id=\\"cart_products\\" t-if=\\"website_sale_order and website_sale_order.website_order_line\\" class=\\"js_cart_lines d-flex flex-column mb32\\">\\n            <t t-foreach=\\"website_sale_order.website_order_line\\" t-as=\\"line\\">\\n                <t t-set=\\"is_combo\\" t-value=\\"line.product_type == 'combo'\\"/>\\n                <div class=\\"o_cart_product d-flex gap-3 pb-4\\" t-attf-data-product-id=\\"#{line.product_id and line.product_id.id}\\">\\n                    <div class=\\"o_cart_product_image\\">\\n                        <!--\\n                            Unsellable lines can have unpublished products, but portal users have no\\n                            access to unpublished product images. To ensure product images are\\n                            always shown for unsellable lines, we use the raw image data as src\\n                            (which doesn't require access, unlike the image URL).\\n                        -->\\n                        <t t-call=\\"website_sale.cart_line_product_link\\">\\n                            <img t-if=\\"not line._is_sellable() and line.product_id.image_128\\" t-att-src=\\"image_data_uri(line.product_id.image_128)\\" class=\\"img border rounded\\" t-att-alt=\\"line.name_short\\"/>\\n                            <div t-else=\\"\\" t-field=\\"line.product_id.image_128\\" t-options=\\"{                                     'widget': 'image',                                     'qweb_img_responsive': False,                                     'class': 'border rounded',                                 }\\"/>\\n                        </t>\\n                    </div>\\n                    <div class=\\"d-flex flex-column flex-grow-1 gap-3 min-w-0\\">\\n                        <div class=\\"d-flex gap-3\\">\\n                            <div class=\\"flex-grow-1 text-wrap w-100\\">\\n                                <div class=\\"d-flex justify-content-between\\">\\n                                    <div class=\\"d-md-flex flex-md-wrap column-gap-md-1 align-items-md-center\\">\\n                                        <t t-call=\\"website_sale.cart_line_product_link\\">\\n                                            <h6 t-out=\\"line._get_line_header()\\" class=\\"text-wrap mb-1\\"/>\\n                                        </t>\\n                                        <t t-set=\\"combination_name\\" t-value=\\"line._get_combination_name()\\"/>\\n                                        <span t-if=\\"combination_name\\" class=\\"d-none d-md-inline h6 text-muted mb-1\\">-</span>\\n                                        <div t-if=\\"combination_name or line.product_template_id._has_multiple_uoms()\\" class=\\"d-inline-flex flex-wrap column-gap-2 row-gap-1 align-items-center my-1 my-md-0 w-100 w-md-auto\\">\\n                                            <span t-if=\\"combination_name\\" class=\\"h6 text-muted mb-1\\" t-out=\\"combination_name\\"/>\\n                                            <span t-if=\\"line.product_template_id._has_multiple_uoms()\\" class=\\"badge bg-light mb-1\\" t-out=\\"line.product_uom_id.name\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <div t-attf-class=\\"{{'d-block d-md-none' if not is_combo else ''}}\\"><t t-call=\\"website_sale.cart_lines_price\\"/></div>\\n                                </div>\\n                                <t t-call=\\"website_sale.cart_line_description_following_lines\\"/>\\n                                <ul t-if=\\"is_combo\\" class=\\"list-group\\">\\n                                    <t t-foreach=\\"line.linked_line_ids.filtered('combo_item_id')\\" t-as=\\"combo_item_line\\">\\n                                        <t t-call=\\"website_sale.cart_combo_item_line\\"/>\\n                                    </t>\\n                                </ul>\\n                                <div name=\\"o_wsale_cart_line_button_container\\" t-attf-class=\\"d-none d-md-flex align-items-center gap-2 mt-2 {{'justify-content-between' if is_combo else ''}}\\">\\n                                    <a href=\\"#\\" class=\\"js_delete_product small\\" aria-label=\\"Remove from cart\\" title=\\"Remove from cart\\">\\n                                        Remove\\n                                    </a>\\n                                    <div t-if=\\"is_combo\\" class=\\"d-none d-md-block ms-auto\\"><t t-call=\\"website_sale.cart_lines_quantity\\"/></div>\\n                                </div>\\n                            </div>\\n                            <div t-if=\\"not is_combo\\" class=\\"d-none d-md-block\\">\\n                                <t t-call=\\"website_sale.cart_lines_price\\"/>\\n                                <div class=\\"d-none d-md-block mt-2\\"><t t-call=\\"web