variant.all_product_tag_ids\\"/>\\n            </t>\\n            <p t-if=\\"(not is_add_to_cart_possible) and (not product.active)\\" class=\\"alert alert-warning\\">\\n                This product is no longer available.\\n            </p>\\n            <p t-elif=\\"not is_add_to_cart_possible\\" class=\\"alert alert-warning\\">\\n                This product has no valid combination.\\n            </p>\\n        </div>\\n    </t>", "es_ES": "<t t-name=\\"website_sale.product_title\\">\\n        <div t-attf-class=\\"o_wsale_product_details_content_section o_wsale_product_details_content_section_title {{'mb-3' if not product.description_ecommerce else ''}}\\">\\n            <!-- FIXME VCR variable seems unused -->\\n            <t t-set=\\"base_url\\" t-value=\\"website.get_base_url()\\"/>\\n            <h1 t-attf-class=\\"h3 {{'mb-3' if not product.description_ecommerce and not is_view_active('website_sale.product_comment') else ''}}\\" t-field=\\"product.name\\">\\n                Nombre del producto\\n            </h1>\\n            <t t-if=\\"is_view_active('website_sale.product_comment')\\">\\n                <a href=\\"#o_product_page_reviews\\" class=\\"o_product_page_reviews_link d-block mb-2 text-decoration-none\\">\\n                    <t t-call=\\"portal_rating.rating_widget_stars_static\\">\\n                        <!-- sudo: product.product - visitor can access product average rating -->\\n                        <t t-set=\\"rating_avg\\" t-value=\\"product.sudo().rating_avg\\"/>\\n                        <t t-set=\\"trans_text_plural\\">%s reseñas</t>\\n                        <t t-set=\\"trans_text_singular\\">%s reseña</t>\\n                        <t t-set=\\"rating_count\\" t-value=\\"(trans_text_plural if product.rating_count &gt; 1 else trans_text_singular) % product.rating_count\\"/>\\n                    </t>\\n                </a>\\n            </t>\\n            <div t-field=\\"product.description_ecommerce\\" t-attf-class=\\"oe_structure 