="rating_count" t-value="(trans_text_plural if product.rating_count &gt; 1 else trans_text_singular) % product.rating_count"/>\n                    </t>\n                </a>\n            </t>\n            <div t-field="product.description_ecommerce" t-attf-class="oe_structure mb-3 text-muted" placeholder="A detailed, formatted description to promote your product on this page. Use '/' to discover more features."/>\n            <t t-if="is_view_active('website_sale.product_tags')" t-call="website_sale.product_tags">\n                <t t-set="all_product_tags" t-value="product_variant.all_product_tag_ids"/>\n            </t>\n            <p t-if="(not is_add_to_cart_possible) and (not product.active)" class="alert alert-warning">\n                This product is no longer available.\n            </p>\n            <p t-elif="not is_add_to_cart_possible" class="alert alert-warning">\n                This product has no valid combination.\n            </p>\n        </div>\n    </t>\n\n    	f	t	2026-11-24 18:55:43.321726	2026-11-24 18:55:43.321726	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
