\\n                </li>\\n                <li t-else=\\"\\" t-attf-class=\\"breadcrumb-item {{cat_index &lt; cat_size - 2 and 'd-none d-lg-inline'}}\\">\\n                    <a t-att-href=\\"keep('%s/category/%s' % (shop_path, slug(cat)))\\" t-field=\\"cat.name\\"/>\\n                </li>\\n            </t>\\n        </ol>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Products Breadcrumb" t-name="website_sale.products_breadcrumb">\n        <ol t-if="category" t-attf-class="breadcrumb #{_classes}">\n            <li class="breadcrumb-item">\n                <a t-att-class="'d-none d-lg-inline' if len(category.parents_and_self) &gt; 1 else ''" t-att-href="keep(shop_path)">\n                    Products\n                </a>\n                <span t-if="len(category.parents_and_self) &gt; 1" class="d-lg-none">...</span>\n            </li>\n            <t t-foreach="category.parents_and_self" t-as="cat">\n                <li t-if="cat == category" class="breadcrumb-item">\n                    <span class="d-inline-block" t-field="cat.name"/>\n                </li>\n                <li t-else="" t-attf-class="breadcrumb-item {{cat_index &lt; cat_size - 2 and 'd-none d-lg-inline'}}">\n                    <a t-att-href="keep('%s/category/%s' % (shop_path, slug(cat)))" t-field="cat.name"/>\n                </li>\n            </t>\n        </ol>\n    </t>\n\n    	f	t	2026-11-24 18:55:43.321726	2026-11-24 18:55:43.321726	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
1141	16	586	1	1	Purchase Order	\N	purchase.portal_my_purchase_order	qweb	purchase/views/portal_templates.xml	primary	{"en_US": "<data name=\\"Purchase Order\\" inherit_id=\\"portal.portal_sidebar\\" primary=\\"True\\">\\n      <xpath expr=\\"//div[hasclass('o_portal_sidebar')]\\" position=\\"inside\\">\\n          <t t-set=\\"o_portal_fullwidth_alert\\" groups=\\"purchase.group_purchase_manager\\">\\n              <t t-call=\\"portal.portal_back_in_edit_mode\\">\\n                  <t t-set=\\"backend_url\\" t-value=\\"'/odoo/action-purchase.purchase_rfq/%s' % (order.id)\\"/>\\n              </t>\\n          </t>\\n\\n          <div class=\\"row o_portal_purchase_sidebar\\">\\n              <!-- Sidebar -->\\n              <t t-call=\\"portal.portal_record_sidebar\\">\\n                  <t t-set=\\"classes\\" t-value=\\"'col-lg-4 col-xxl-3 d-print-none'\\"/>\\n\\n                  <t t-set=\\"title\\">\\n                      <h2 t-field=\\"order.amount_total\\" data-id=\\"total_amount\\" class=\\"mb-0 text-break\\"/>\\n                  </t>\\n                  <t t-set=\\"entries\\">\\n                      <div class=\\"d-flex flex-column gap-4 mt-3\\">\\n                          <a class=\\"btn btn-secondary o_print_btn o_portal_invoice_print\\" t-att-href=\\"order.get_portal_url(report_type='pdf')\\" id=\\"print_invoice_report\\" title=\\"View Details\\" role=\\"button\\" target=\\"_blank\\"><i class=\\"fa fa-print me-1\\"/>Download / Print</a>\\n                          <div class=\\"navspy flex-grow-1 ps-0\\" t-ignore=\\"true\\" role=\\"complementary\\">\\n                              <ul class=\\"nav flex-column bs-sidenav\\"/>\\n                          </div>\\n                          <div t-if=\\"order.user_id\\">\\n                              <h6 class=\\"small text-muted\\">Buyer</h6>\\n                                <t t-call=\\"portal.portal_my_contact\\">\\n                                    <t t-set=\\"_contactAvatar\\" t-value=\\"image_data_uri(order.user_id.avatar_128)\\"/>\\n                                    <t t-set=\\"_contactName\\" t-value=\\"order.user_id.name\\"/>\\n                                    <t t-set=\\"_contactLink\\" t-value=\\"True\\"/>\\n                                    <div t-field=\\"order.user_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;phone&quot;], &quot;no_marker&quot;: False}\\"/>\\n                                </t>\\n                          </div>\\n\\n                          <div t-if=\\"order._get_edi_builders()\\">\\n                            <button id=\\"portal_connect_software_modal_btn\\" type=\\"button\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#portal_connect_software_modal\\">\\n                                Connect with your software!\\n                            </button>\\n                          </div>\\n                      </div>\\n                  </t>\\n              </t>\\n\\n              <div class=\\"modal fade\\" id=\\"portal_connect_software_modal\\" tabindex=\\"-1\\" role=\\"dialog\\" aria-hidden=\\"true\\">\\n                <div class=\\"modal-dialog modal-lg\\" role=\\"document\\">\\n                    <div class=\\"modal-content\\">\\n                        <div class=\\"modal-body\\">\\n                            <div>\\n                                <h5>Want to import this document in Odoo?</h5>\\n                                <p>Drag and drop the request for quotation PDF file into your list of quotations in Odoo. Enjoy the automation!</p>\\n                            </div>\\n                            <div>\\n                                <h5>Not using Odoo?</h5>\\n                                <div class=\\"input-group mb-3 w-50\\">\\n                                    <t t-set=\\"base_address\\" t-value=\\"order.env['ir.config_parameter'].sudo().get_param('web.base.url')\\"/>\\n                                    <t t-set=\\"doc_url\\" t-value=\\"base_address + '/my/purchase/' + str(order.id) + '/download_edi?' + str(keep_query())\\"/>\\n                                    <input type=\\"text\\" class=\\"form-control\\" aria-describedby=\\"copy-button\\" readonly=\\"readonly\\" t-att-value=\\"doc_url\\"/>\\n                                    <button class=\\"btn btn-outline-secondary\\" type=\\"button\\" id=\\"copy-button\\" t-attf-onclick=\\"navigator.clipboard.writeText('#{doc_url}')\\">Copy</button>\\n                                </div>\\n                                <p>Use the above REST URL to get structured data of the purchase order in UBL format.\\n                                    <a href=\\"https://www.odoo.com/documentation/\\">Read the documentation </a>to learn all the ways to connect your software with <a href=\\"https://www.odoo.com\\">Odoo</a>.\\n                                </p>\\n                            </div>\\n                            <div>\\n                                <h5>You don't use a good CRM software?</h5>\\n                                <p><a href=\\"https://www.odoo.com/app/sales\\">Start on Odoo</a>, it's 100% free! You'll save time creating beautiful quotations and track sales.</p>\\n                            </div>\\n                        </div>\\n                        <div class=\\"modal-footer justify-content-between\\">\\n                            <button type=\\"button\\" class=\\"btn btn-secondary\\" data-bs-dismiss=\\"modal\\">Close</button>\\n                        </div>\\n                    </div>\\n                </div>\\n              </div>\\n\\n              <!-- Page content -->\\n              <div id=\\"quote_content\\" class=\\"o_portal_content col-12 col-lg-8 col-xxl-9\\">\\n                  <!-- main content -->\\n                  <div id=\\"portal_purchase_content\\">\\n                      <div><t t-call=\\"purchase.purchase_order_portal_content\\"/></div>\\n                  </div>\\n\\n                  <!-- chatter -->\\n                  <hr/>\\n                  <div id=\\"purchase_order_communication\\">\\n                      <h3>Communication history</h3>\\n                      <t t-call=\\"portal.message_thread\\"/>\\n                  </div>\\n              </div><!-- // #quote_content -->\\n          </div>\\n      </xpath>\\n  <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">purchase.portal_my_purchase_order</attribute></xpath></data>", "es_ES": "<data name=\\"Purchase Order\\" inherit_id=\\"portal.portal_sidebar\\" primary=\\"True\\">\\n      <xpath expr=\\"//div[hasclass('o_portal_sidebar')]\\" position=\\"inside\\">\\n          <t t-set=\\"o_portal_fullwidth_alert\\" groups=\\"purchase.group_purchase_manager\\">\\n              <t t-call=\\"portal.portal_back_in_edit_mode\\">\\n                  <t t-set=\\"backend_url\\" t-value=\\"'/odoo/action-purchase.purchase_rfq/%s' % (order.id)\\"/>\\n              </t>\\n          </t>\\n\\n          <div class=\\"row o_portal_purchase_sidebar\\">\\n              <!-- Sidebar -->\\n              <t t-call=\\"portal.portal_record_sidebar\\">\\n                  <t t-set=\\"classes\\" t-value=\\"'col-lg-4 col-xxl-3 d-print-none'\\"/>\\n\\n                  <t t-set=\\"title\\">\\n                      <h2 t-field=\\"order.amount_total\\" data-id=\\"total_amount\\" class=\\"mb-0 text-break\\"/>\\n                  </t>\\n                  <t t-set=\\"entries\\">\\n                      <div class=\\"d-flex flex-column gap-4 mt-3\\">\\n                          <a class=\\"btn btn-secondary o_print_btn o_portal_invoice_print\\" t-att-href=\\"order.get_portal_url(report_type='pdf')\\" id=\\"print_invoice_report\\" title=\\"Ver detalles\\" role=\\"button\\" target=\\"_blank\\"><i class=\\"fa fa-print me-1\\"/>Descargar/imprimir</a>\\n                          <div class=\\"navspy flex-grow-1 ps-0\\" t-ignore=\\"true\\" role=\\"complementary\\">\\n                              <ul class=\\"nav flex-column bs-sidenav\\"/>\\n                          </div>\\n                          <div t-if=\\"order.user_id\\">\\n                              <h6 class=\\"small text-muted\\">Comprador</h6>\\n                                <t t-call=\\"portal.portal_my_contact\\">\\n                                    <t t-set=\\"_contactAvatar\\" t-value=\\"image_data_uri(order.user_id.avatar_128)\\"/>\\n                                    <t t-set=\\"_contactName\\" t-value=\\"order.user_id.name\\"/>\\n                                    <t t-set=\\"_contactLink\\" t-value=\\"True\\"/>\\n                                    <div t-field=\\"order.user_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;phone&quot;], &quot;no_marker&quot;: False}\\"/>\\n                                </t>\\n                          </div>\\n\\n                          <div t-if=\\"order._get_edi_builders()\\">\\n                            <button id=\\"portal_connect_software_modal_btn\\" type=\\"button\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#portal_connect_software_modal\\">\\n                                Conecte con su software\\n                            </button>\\n                          </div>\\n                      </div>\\n                  </t>\\n              </t>\\n\\n              <div class=\\"modal fade\\" id=\\"portal_connect_software_modal\\" tabindex=\\"-1\\" role=\\"dialog\\" aria-hidden=\\"true\\">\\n                <div class=\\"modal-dialog modal-lg\\" role=\\"document\\">\\n                    <div class=\\"modal-content\\">\\n                        <div class=\\"modal-body\\">\\n                            <div>\\n                                <h5>¿Desea importar este documento a Odoo?</h5>\\n                                <p>Arrastre y suelte el archivo PDF de solicitud de presupuesto en su lista de presupuestos en Odoo y disfrute de la automatización.</p>\\n                            </div>\\n                            <div>\\n                                <h5>¿No utiliza Odoo?</h5>\\n                                <div class=\\"input-group mb-3 w-50\\">\\n                                    <t t-set=\\"base_address\\" t-value=\\"order.env['ir.config_parameter'].sudo().get_param('web.base.url')\\"/>\\n                                    <t t-set=\\"doc_url\\" t-value=\\"base_address + '/my/purchase/' + str(order.id) + '/download_edi?' + str(keep_query())\\"/>\\n                                    <input type=\\"text\\" class=\\"form-control\\" aria-describedby=\\"copy-button\\" readonly=\\"readonly\\" t-att-value=\\"doc_url\\"/>\\n                                    <button class=\\"btn btn-outline-secondary\\" type=\\"button\\" id=\\"copy-button\\" t-attf-onclick=\\"navigator.clipboard.writeText('#{doc_url}')\\">Copiar</button>\\n                                </div>\\n                                <p>Utilice la URL REST anterior para obtener los datos estructurados del pedido de compra en formato UBL.\\n                                    <a href=\\"https://www.odoo.com/documentation/\\">Consulte la documentación </a>para conocer todas las formas de conectar su software con <a href=\\"https://www.odoo.com\\">Odoo</a>.\\n                                </p>\\n                            </div>\\n                            <div>\\n                                <h5>¿No utiliza un buen software de CRM?</h5>\\n                                <p><a href=\\"https://www.odoo.com/app/sales\\">Empezar en Odoo</a>, es totalmente gratuito. Ahorrará tiempo creando bonitos presupuestos y realizando un seguimiento de las ventas.</p>\\n                            </div>\\n                        </div>\\n                        <div class=\\"modal-footer justify-content-between\\">\\n                            <button type=\\"button\\" class=\\"btn btn-secondary\\" data-bs-dismiss=\\"modal\\">Cerrar</button>\\n            