ue=\\"products._prepare_categories_for_display()\\"/>\\n                            <ul class=\\"list-unstyled d-flex mb-0\\">\\n                                <li t-foreach=\\"products\\" t-as=\\"product\\" class=\\"o_wsale_compare_table_column position-relative d-flex flex-column flex-shrink-0\\">\\n                                    <t t-set=\\"combination_info\\" t-value=\\"product._get_combination_info_variant()\\"/>\\n                                    <a t-att-href=\\"product.website_url\\">\\n                                        <img t-att-src=\\"product._get_image_1024_url()\\" class=\\"img img-fluid w-100 h-100 object-fit-cover border rounded\\" alt=\\"Product image\\"/>\\n                                    </a>\\n                                    <button t-att-data-product-product-id=\\"product.id\\" class=\\"o_comparelist_remove btn position-absolute top-0 end-0 mx-3 my-2 p-2 rounded-circle bg-white-75 lh-1\\" aria-label=\\"Remove product from comparison\\">\\n                                        <i class=\\"oi oi-close\\"/>\\n                                    </button>\\n                                </li>\\n                            </ul>\\n                            <ul class=\\"list-unstyled d-flex mb-0 pt-3 pb-5\\">\\n                                <li t-foreach=\\"products\\" t-as=\\"product\\" class=\\"o_wsale_compare_table_column position-relative d-flex flex-column flex-shrink-0\\">\\n                                    <t t-set=\\"combination_info\\" t-value=\\"product._get_combination_info_variant()\\"/>\\n                                    <div id=\\"o_comparelist_product_name\\" class=\\"product_summary d-flex flex-column h-100\\">\\n                                        <a t-att-href=\\"product.website_url\\">\\n                                            <h6 t-out=\\"product.display_name\\"/>\\n                                        </a>\\n                                        <span t-if=\\"not combination_info['p