mage"/>\n                                    </a>\n                                    <button t-att-data-product-product-id="product.id" class="o_comparelist_remove btn position-absolute top-0 end-0 mx-3 my-2 p-2 rounded-circle bg-white-75 lh-1" aria-label="Remove product from comparison">\n                                        <i class="oi oi-close"/>\n                                    </button>\n                                </li>\n                            </ul>\n                            <ul class="list-unstyled d-flex mb-0 pt-3 pb-5">\n                                <li t-foreach="products" t-as="product" class="o_wsale_compare_table_column position-relative d-flex flex-column flex-shrink-0">\n                                    <t t-set="combination_info" t-value="product._get_combination_info_variant()"/>\n                                    <div id="o_comparelist_product_name" class="product_summary d-flex flex-column h-100">\n                                        <a t-att-href="product.website_url">\n                                            <h6 t-out="product.display_name"/>\n                                        </a>\n                                        <span t-if="not combination_info['prevent_zero_price_sale']">\n                                            <span t-out="combination_info['price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                            <del t-if="combination_info.get('compare_list_price') and (combination_info['compare_list_price'] &gt; combination_info['price'])" class="me-2 text-muted text-nowrap" t-out="combination_info['compare_list_price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                            <del t-else="" t-attf-class="text-muted me-2 text-nowrap {{'' if combination_info['has_discounted_price'] else 'd-none'}}" t-out="combination_info['list_price']" t-options="{'widget': 'monetary', 'display_currency': website.currency_id}"/>\n                                            <small t-if="combination_info.get('base_unit_price')" class="d-block text-muted">\n                                                <t t-call="website_sale.base_unit_price">\n                                                    <t t-set="base_unit_price" t-value="combination_info['base_unit_price']"/>\n                                                </t>\n                                            </small>\n                                        </span>\n                                        <div class="mt-auto pt-3">\n                                            <a t-if="combination_info['prevent_zero_price_sale']" t-att-href="website.contact_us_button_url + '?subject=' + combination_info['display_name']" class="btn btn-primary btn_cta">\n                                               Contact Us\n                                            </a>\n                                            <button t-else="" name="comparison_add_to_cart" class="btn btn-primary" t-att-data-product-product-id="product.id" t-att-data-product-template-id="product.product_tmpl_id.id" t-att-data-show-quantity="is_view_active('website_sale.product_quantity')">\n                                                <i class="fa fa-shopping-cart me-2" aria-hidden="true"/>Add to Cart\n                                            </button>\n                                        </div>\n                                    </div>\n                                </li>\n                            </ul>\n                            <div t-foreach="attrib_categories" t-as="category">\n                                <div class="w-100 py-3 bg-light bg-opacity-50">\n                                    <h6 class="d-table position-sticky start-0 mb-0 ps-2">\n                                        <span t-if="category" t-field="category.name"/>\n                                        <t t-else="">Uncategorized