\\"/>\\n                        <field name=\\"header_spacing\\"/>\\n                        <field name=\\"disable_shrinking\\"/>\\n                        <field name=\\"dpi\\"/>\\n                        <field name=\\"report_ids\\" widget=\\"many2many_tags\\" options=\\"{'not_delete': True}\\"/>\\n                    </group>\\n                </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Paper format configuration">\n                <sheet>\n                    <group>\n                        <field name="name"/>\n                        <field name="format"/>\n                        <field name="page_height" invisible="format != 'custom'"/>\n                        <field name="page_width" invisible="format != 'custom'"/>\n                        <field name="orientation"/>\n                        <field name="margin_top"/>\n                        <field name="margin_bottom"/>\n                        <field name="margin_left"/>\n                        <field name="margin_right"/>\n                        <field name="header_line"/>\n                        <field name="header_spacing"/>\n                        <field name="disable_shrinking"/>\n                        <field name="dpi"/>\n                        <field name="report_ids" widget="many2many_tags" options="{'not_delete': True}"/>\n                    </group>\n                </sheet>\n                </form>\n            	f	t	2026-11-13 12:56:38.973301	2026-11-24 18:48:00.717396	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
268	16	\N	1	1	Barcode Nomenclatures	barcode.nomenclature	\N	form	barcodes/views/barcodes_view.xml	primary	{"en_US": "<form string=\\"Barcode Nomenclature\\">\\n                    <sheet>\\n                        <group name=\\"general_attributes\\" col=\\"4\\">\\n                            <field name=\\"name\\"/>\\n                            <field name=\\"upc_ean_conv\\"/>\\n                        </group>\\n                        <div>\\n                            <p>\\n                                <i>Barcodes Nomenclatures</i> define how barcodes are recognized and categorized.\\n                                When a barcode is scanned it is associated to the <i>first</i> rule with a matching\\n                                pattern. The pattern syntax is that of regular expression, and a barcode is matched\\n                                if the regular expression matches a prefix of the barcode.\\n                            </p><p>\\n                                Patterns can also define how numerical values, such as weight or price, can be\\n                                encoded into the barcode. They are indicated by <code>{NNN}</code> where the N's\\n                                define where the number's digits are encoded. Floats are also supported with the\\n                                decimals indicated with D's, such as <code>{NNNDD}</code>. In these cases,\\n                                the barcode field on the associated records <i>must</i> show these digits as\\n                                zeroes.\\n                            </p>\\n                        </div>\\n                        <field name=\\"rule_ids\\">\\n                            <list string=\\"Tables\\">\\n                                <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"type\\"/>\\n                                <field name=\\"encoding\\"/>\\n                                <field name=\\"pattern\\"/>\\n                            </list>\\n                        </field>\\n                    </sheet>\\n                </form>", "es_ES": "<form string=\\"Nomenclatura de código de barras\\">\\n                    <sheet>\\n                        <group name=\\"general_attributes\\" col=\\"4\\">\\n                            <field name=\\"name\\"/>\\n                            <field name=\\"upc_ean_conv\\"/>\\n                        </group>\\n                        <div>\\n                            <p>\\n                                Las <i>nomenclaturas de códigos de barras</i> definen cómo se reconocen y categorizan\\nlos códigos de barras. Cuando se escanea un código de barras se asocia a la <i>primera</i>\\nregla con un patrón coincidente. La sintaxis de los patrones es la de una expresión\\nregular, y un código de barras se reconoce si la expresión regular coincide con un\\nprefijo del código de barras.\\n                            </p><p>\\n                                Los patrones también pueden definir el modo en que los valores numéricos, como el peso o el precio, pueden\\n                                codificarse en el código de barras. Estos se indican con el parámetro <code>{NNN}</code> donde las N\\n                                definen dónde se codifican los dígitos del número. También se admiten valores flotantes con los\\n                                decimales indicados con D, como <code>{NNNDD}</code>. En estos casos,\\n                                el campo de código de barras de los registros asociados <i>debe</i> mostrar estos dígitos como\\n                                ceros.\\n                            </p>\\n                        </div>\\n                        <field name=\\"rule_ids\\">\\n                            <list string=\\"Tablas\\">\\n                                <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"type\\"/>\\n                                <field name=\\"encoding\\"/>\\n                                <field name=\\"pattern\\"/>\\n                            </list>\\n                        </field>\\n                    </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Barcode Nomenclature">\n                    <sheet>\n                        <group name="general_attributes" col="4">\n                            <field name="name"/>\n                            <field name="upc_ean_conv"/>\n                        </group>\n                        <div>\n                            <p>\n                                <i>Barcodes Nomenclatures</i> define how barcodes are recognized and categorized.\n                                When a barcode is scanned it is associated to the <i>first</i> rule with a matching\n                                pattern. The pattern syntax is that of regular expression, and a barcode is matched\n                                if the regular expression matches a prefix of the barcode.\n                            </p><p>\n                                Patterns can also define how numerical values, such as weight or price, can be\n                                encoded into the barcode. They are indicated by <code>{NNN}</code> where the N's\n                                define where the number's digits are encoded. Floats are also supported with the\n                                decimals indicated with D's, such as <code>{NNNDD}</code>. In these cases,\n                                the barcode field on the associated records <i>must</i> show these digits as\n                                zeroes.\n                            </p>\n                        </div>\n                        <field name="rule_ids">\n                            <list string="Tables">\n                                <field name="sequence" widget="handle"/>\n                                <field name="name"/>\n                                <field name="type"/>\n                                <field name="encoding"/>\n                                <field name="pattern"/>\n                            </list>\n                        </field>\n                    </sheet>\n                </form>\n            	f	t	2026-11-17 08:29:55.579962	2026-11-24 18:48:00.717396	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
