 los gastos de envío y envíe con Shiprocket\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_shiprocket\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_starshipit\\" help=\\"Calcule los gastos de envío y envíe con Starshipit\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_starshipit\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_envia\\" help=\\"Calcule los costes de envío y envíe con Envia.com\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_envia\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Productos\\" name=\\"product_setting_container\\">\\n                            <setting id=\\"product_attributes\\" help=\\"Establezca los atributos del producto (por ejemplo, color, tamaño) para administrar las variantes\\" documentation=\\"/applications/sales/sales/products_prices/products/variants.html\\">\\n                                <field name=\\"group_product_variant\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_product_variant\\">\\n                                        <button name=\\"179\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Atributos\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"sell_purchase_uom\\" help=\\"Venda y compre productos en diferentes unidades de medida o embalajes\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/products/uom.html\\">\\n                                <field name=\\"group_uom\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_uom\\">\\n                                        <button name=\\"100\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Unidades y embalajes\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Trazabilidad\\" id=\\"production_lot_info\\">\\n                            <setting id=\\"full_traceability\\" help=\\"Obtenga una trazabilidad completa de proveedores a clientes\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/lots_serial_numbers/differences.html\\">\\n                                <field name=\\"group_stock_production_lot\\"/>\\n                                <div class=\\"row mt-2\\" invisible=\\"not group_stock_production_lot\\">\\n                                    <field name=\\"group_stock_lot_print_gs1\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    <div class=\\"col ps-0\\">\\n                                        <label for=\\"group_stock_lot_print_gs1\\"/>\\n                                        <div class=\\"text-muted\\">Utilice la matriz de datos de nomenclatura GS1 siempre que se impriman los códigos de barras de números de lote y de serie.</div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"row mt-2\\" invisible=\\"not group_stock_production_lot or not group_stock_tracking_lot\\">\\n                                    <span class=\\"o_form_label\\">Contenido del paquete escaneable</span>\\n                                    <div class=\\"col-12\\">\\n                                        <div class=\\"text-muted\\">Al definir un separador se generará un código QR que contenga todos los números de serie incluidos en el paquete y utilizará el carácter definido para separar los números.</div>\\n                                    </div>\\n                                    <div class=\\"col\\">\\n                                        <label for=\\"barcode_separator\\"/>\\n                                        <field name=\\"barcode_separator\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"expiration_dates_serial_numbers\\" help=\\"Establezca fechas de caducidad en los lotes y números de serie\\" invisible=\\"not group_stock_production_lot\\" title=\\"Haga un seguimiento de las fechas de seguimiento de los lotes y números de serie: mejor antes, eliminación, fin de vida, alerta. Dichas fechas se establecen automáticamente en la creación del lote/número de serie en función de los valores establecidos en el producto (en días).\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/lots_serial_numbers/expiration_dates.html\\">\\n                                <field name=\\"module_product_expiry\\"/>\\n                            </setting>\\n                            <setting help=\\"Los números de lote y serie aparecerán en el albarán de entrega\\" invisible=\\"not group_stock_production_lot\\" id=\\"group_lot_on_delivery_slip\\">\\n                                <field name=\\"group_lot_on_delivery_slip\\"/>\\n                            </setting>\\n                            <setting id=\\"owner_stored_products\\" help=\\"Establezca el propietario en productos almacenados\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/misc/owned_stock.html\\">\\n                                <field name=\\"group_stock_tracking_owner\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Almacén\\" name=\\"warehouse_setting_container\\">\\n                            <setting id=\\"track_product_location\\" help=\\"Monitoree la ubicación del producto en su almacén\\" documentation=\\"/applications/inventory_and_mrp/inventory/warehouses_storage/inventory_management/use_locations.html\\" title=\\"Almacene productos en ubicaciones específicas de su almacén (por ejemplo, contenedores, bastidores) y haga un seguimiento del inventario en consecuencia.\\">\\n                                <field name=\\"group_stock_multi_locations\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_multi_locations\\">\\n                                        <button name=\\"296\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Ubicaciones\\" class=\\"btn-link\\"/><br/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"use_own_routes\\" help=\\"Use sus propias rutas\\" documentation=\\"/applications/inventory_and_mrp/inventory/routes/concepts/use_routes.html\\" title=\\"Añada y personalice las operaciones de ruta para procesar movimientos de productos en su(s) almacén(es): por ejemplo, descargar &gt; control de calidad &gt; stock para productos entrantes, elegir &gt; empaquetar &gt; enviar para productos salientes. También puede establecer estrategias de almacenamiento en ubicaciones de almacenamiento para enviar productos entrantes a ubicaciones hijas específicas de inmediato (por ejemplo, contenedores específicos, bastidores).\\">\\n                                <field name=\\"group_stock_adv_location\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_adv_location\\">\\n                                        <button name=\\"256\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Establecer rutas de almacén\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Planificación avanzada\\" id=\\"schedule_info\\">\\n                            <setting company_dependent=\\"1\\" help=\\"Configura el horizonte para activar las reglas de reabastecimiento con antelación y adelantarse a la reposición evitando retrasos, o actívalo justo a tiempo ('0 días') para evitar el exceso de stock.\\">\\n                                <field name=\\"horizon_days\\" class=\\"oe_inline\\"/><span> días</span>\\n                            </setting>\\n                            <div id=\\"sale_security_lead\\"/>\\n                            <div id=\\"purchase_po_lead\\"/>\\n                        </block>\\n                        <block title=\\"Logística\\" name=\\"request_vendor_setting_container\\">\\n                            <setting title=\\"Esto añade una ruta de dropshipping aplicable a productos con el fin de solicitar a sus proveedores que entreguen directamente a sus clientes. Un producto para dropship generará una solicitud de presupuesto de compra una vez que se confirme el pedido de venta. Este es un flujo bajo demanda. La dirección de entrega solicitada será la dirección de entrega del cliente y no su almacén.\\" help=\\"Solicite a sus proveedores que entreguen a sus clientes\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/delivery/dropshipping.html\\">\\n                                <field name=\\"module_stock_dropshipping\\"/>\\n                            </setting>\\n                            <setting title=\\"Esto añade una ruta de reposición bajo pedido (fabricación sobre pedido) que se aplica a los productos para generar reposiciones bajo demanda vinculadas a sus pedidos de venta (por ejemplo) tan pronto como se confirman, con un enlace directo. Los pedidos de compra, las órdenes de fabricación, etc. se activan en función de la forma de reposición establecida en el producto (ruta de compra o fabricación).\\" help=\\"Permita la fabricación sobre pedido o automatice los pedidos de compra cuando se venda un producto y obtenga enlaces directos entre documentos.\\" documentation=\\"/applications/inventory_and_mrp/inventory/warehouses_storage/replenishment/mto.html\\">\\n                                <field name=\\"replenish_on_order\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                    <app data-string="Inventory" string="Inventory" name="stock" groups="stock.group_stock_manager">\n                        <block title="Operations" name="operations_setting_container">\n                            <setting id="product_packs_tracking" documentation="/applications/inventory_and_mrp/inventory/product_management/product_tracking/package.html" title="Put your products in packs (e.g. parcels, boxes) and track them" help="Put your products in packs (e.g. parcels, boxes) and track them">\n                                <field name="group_stock_tracking_lot"/>\n                            </setting>\n                            <setting id="process_transfers" help="Optimize your transfers by grouping operations together and assigning jobs to workers" documentation="/applications/inventory_and_mrp/inventory/management/misc/batch_transfers.html">\n                                <field name="module_stock_picking_batch"/>\n                            </setting>\n                            <setting id="warning_info" string="Partner-Specific Instructions" help="Display instructions tailored to the customer or vendor on stock operations.">\n                                <field name="group_warning_stock"/>\n                            </setting>\n                            <setting id="quality_control" help="Add quality checks to your transfer operations" documentation="/applications/inventory_and_mrp/manufacturing/management/quality_control.html">\n                                <field name="module_quality_control" widget="upgrade_boolean"/>\n                                <div class="row mt-2" invisible="not module_quality_control">\n                                    <field name="module_quality_control_worksheet" widget="upgrade_boolean" class="col flex-grow-0 ml16 mr0 pe-2"/>\n                                    <div class="col ps-0">\n                                        <label for="module_quality_control_worksheet"/>\n                                        <div class="text-muted">\n                                            Create customizable worksheets for your quality checks\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="annual_inventory_date" groups="stock.group_stock_manager" string="Annual Inventory Day and Month" help="Day and month that annual inventory counts should occur.">\n                                <div class="content-group">\n                                    <field name="annual_inventory_day" class="o_light_label" style="width: 30px;"/>\n                                    <field name="annual_inventory_month" class="o_light_label"/>\n                                </div>\n                            </setting>\n                            <setting id="reception_report" help="View and allocate received quantities.">\n                                <field name="group_stock_reception_report"/>\n                            </setting>\n                        </block>\n                        <block title="Barcode" name="barcode_setting_container">\n                            <setting id="process_operations_barcodes" help="Process operations faster with barcodes" company_dependent="1" documentation="/applications/inventory_and_mrp/inventory/barcode/setup/software.html">\n                                <field name="module_stock_barcode" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="process_stock_barcodelookup" string="Stock Barcode Database" help="" documentation="https://www.barcodelookup.com/api-documentation">\n                                <field name="module_stock_barcode_barcodelookup" placeholder="e.g. d7vctmiv2rwgenebha8bxq7irooudn"/>\n                                <span class="text-muted">\n                                    Create products easily by scanning using <a href="https://www.barcodelookup.com" target="_blank">barcodelookup.com</a> in barcode.\n                                </span>\n                            </setting>\n                        </block>\n                        <block title="Shipping" name="shipping_setting_container">\n                            <setting id="delivery" help="Compute shipping costs" title="Shipping connectors allow to compute accurate shipping costs, print shipping labels and request carrier picking at your warehouse to ship to the customer. Apply shipping connector from delivery methods.">\n                                <field name="module_delivery"/>\n                            </setting>\n                            <setting id="stock_fleet" help="Transport management: organize packs in your fleet, or carriers.">\n                                <field name="module_stock_fleet"/>\n                            </setting>\n                            <setting id="stock_move_email" company_dependent="1" string="Email Confirmation" help="Send an automatic confirmation email when Delivery Orders are done">\n                                <field name="stock_move_email_validation"/>\n                            </setting>\n                            <setting id="stock_text_confirmation" company_dependent="1" help="Send an automatic confirmation Text Message when Delivery Orders are done" string="Text Confirmation">\n                                <field name="stock_text_confirmation"/>\n                                <field name="module_stock_sms" invisible="1"/>\n                                <div class="content-group" id="module_install_warning" invisible="not stock_text_confirmation">\n                                    <field name="stock_confirmation_type" required="stock_text_confirmation"/>\n                                    <div class="mt16 text-warning" id="module_install_warning_sms" invisible="stock_confirmation_type != 'sms'">\n                                        <strong>Save</strong> this page and come back here to set up the feature.\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="signature_delivery_orders" help="Require a signature on your delivery orders">\n                                <field name="group_stock_sign_delivery"/>\n                            </setting>\n                        </block>\n                        <block title="Shipping Connectors" name="shipping_connectors_setting_container">\n                            <setting id="compute_shipping_costs_ups" help="Compute shipping costs and ship with UPS">\n                                <div class="o_form_label">UPS Connector</div>\n                                <a href="https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html" title="Documentation" class="o_doc_link" target="_blank"/>\n                                <div class="text-muted">\n                                    Compute shipping costs and ship with UPS<br/>\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\n                                </div>\n                            </setting>\n                            <setting id="compute_shipping_costs_dhl" help=" Compute shipping costs and ship with DHL">\n                                <div class="o_form_label">DHL Connector</div>\n                                <a href="https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html" title="Documentation" class="o_doc_link" target="_blank"/>\n                                <div class="text-muted">\n                                    Compute shipping costs and ship with DHL<br/>\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\n                                </div>\n                            </setting>\n                            <setting id="compute_shipping_costs_fedex" help="Compute shipping costs and ship with FedEx">\n                                <div class="o_form_label">FedEx Connector</div>\n                                <a href="https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html" title="Documentation" class="o_doc_link" target="_blank"/>\n                                <div class="text-muted">\n                                    Compute shipping costs and ship with FedEx<br/>\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\n                                </div>\n                            </setting>\n                            <setting id="compute_shipping_costs_usps" help="Compute shipping costs and ship with USPS">\n                                <div class="o_form_label">USPS Connector</div>\n                                <a href="https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html" title="Documentation" class="o_doc_link" target="_blank"/>\n                                <div class="text-muted">\n                                    Compute shipping costs and ship with USPS<br/>\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\n                                </div>\n                            </setting>\n                            <setting id="compute_shipping_costs_bpost" help="Compute shipping costs and ship with bpost" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">\n                                <field name="module_delivery_bpost" widget="upgrade_boolean"/>\n                            </setting>\n\n                            <setting id="compute_shipping_costs_easypost" help="Compute shipping costs and ship with Easypost" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">\n                                <field name="module_delivery_easypost" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="compute_shipping_costs_sendcloud" help="Compute shipping costs and ship with Sendcloud" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">\n                                <field name="module_delivery_sendcloud" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="compute_shipping_costs_shiprocket" help="Compute shipping costs and ship with Shiprocket" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">\n                                <field name="module_delivery_shiprocket" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="compute_shipping_costs_starshipit" help="Compute shipping costs and ship with Starshipit" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">\n                                <field name="module_delivery_starshipit" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="compute_shipping_costs_envia" help="Compute shipping costs and ship with Envia.com" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">\n                                <field name="module_delivery_envia" widget="upgrade_boolean"/>\n                            </setting>\n                        </block>\n                        <block title="Products" name="product_setting_container">\n                            <setting id="product_attributes" help="Set product attributes (e.g. color, size) to manage variants" documentation="/applications/sales/sales/products_prices/products/variants.html">\n                                <field name="group_product_variant"/>\n                                <div class="content-group">\n                                    <div class="mt8" invisible="not group_product_variant">\n                                        <button name="179" icon="oi-arrow-right" type="action" string="Attributes" class="btn-link"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="sell_purchase_uom" help="Sell and purchase products in different units of measure or packagings" documentation="/applications/inventory_and_mrp/inventory/management/products/uom.html">\n                                <field name="group_uom"/>\n                                <div class="content-group">\n                                    <div class="mt8" invisible="not group_uom">\n                                        <button name="100" icon="oi-arrow-right" type="action" string="Units &amp; Packagings" class="btn-link"/>\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="Traceability" id="production_lot_info">\n                            <setting id="full_traceability" help="Get a full traceability from vendors to customers" documentation="/applications/inventory_and_mrp/inventory/management/lots_serial_numbers/differences.html">\n                                <field name="group_stock_production_lot"/>\n                                <div class="row mt-2" invisible="not group_stock_production_lot">\n                                    <field name="group_stock_lot_print_gs1" class="col flex-grow-0 ml16 mr0 pe-2"/>\n                                    <div class="col ps-0">\n                                        <label for="group_stock_lot_print_gs1"/>\n                                        <div class="text-muted">Use GS1 nomenclature datamatrix whenever barcodes are printed for lots and serial numbers.</div>\n                                    </div>\n                                </div>\n                                <div class="row mt-2" invisible="not group_stock_production_lot or not group_stock_tracking_lot">\n                                    <span class="o_form_label">Scannable Package Contents</span>\n                                    <div class="col-12">\n                                        <div class="text-muted">If a separator is defined, a QR code containing all serial numbers contained in package will be generated, using the defined character(s) to separate each numbers</div>\n                                    </div>\n                                    <div class="col">\n                                        <label for="barcode_separator"/>\n                                        <field name="barcode_separator" class="col flex-grow-0 ml16 mr0 pe-2"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="expiration_dates_serial_numbers" help="Set expiration dates on lots &amp; serial numbers" invisible="not group_stock_production_lot" title="Track following dates on lots &amp; serial numbers: best before, removal, end of life, alert. Such dates are set automatically at lot/serial number creation based on values set on the product (in days)." documentation="/applications/inventory_and_mrp/inventory/management/lots_serial_numbers/expiration_dates.html">\n                                <field name="module_product_expiry"/>\n                            </setting>\n                            <setting help="Lots &amp; Serial numbers will appear on the delivery slip" invisible="not group_stock_production_lot" id="group_lot_on_delivery_slip">\n                                <field name="group_lot_on_delivery_slip"/>\n                            </setting>\n                            <setting id="owner_stored_products" help="Set owner on stored products" documentation="/applications/inventory_and_mrp/inventory/management/misc/owned_stock.html">\n                                <field name="group_stock_tracking_owner"/>\n                            </setting>\n                        </block>\n                        <block title="Warehouse" name="warehouse_setting_container">\n                            <setting id="track_product_location" help="Track product location in your warehouse" documentation="/applications/inventory_and_mrp/inventory/warehouses_storage/inventory_management/use_locations.html" title="Store products in specific locations of your warehouse (e.g. bins, racks) and to track inventory accordingly.">\n                                <field name="group_stock_multi_locations"/>\n                                <div class="content-group">\n                                    <div class="mt8" invisible="not group_stock_multi_locations">\n                                        <button name="296" icon="oi-arrow-right" type="action" string="Locations" class="btn-link"/><br/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="use_own_routes" help="Use your own routes" documentation="/applications/inventory_and_mrp/inventory/routes/concepts/use_routes.html" title="Add and customize route operations to process product moves in your warehouse(s): e.g. unload &gt; quality control &gt; stock for incoming products, pick &gt; pack &gt; ship for outgoing products. You can also set putaway strategies on warehouse locations in order to send incoming products into specific child locations straight away (e.g. specific bins, racks).">\n                                <field name="group_stock_adv_location"/>\n                                <div class="content-group">\n                                    <div class="mt8" invisible="not group_stock_adv_location">\n                                        <button name="256" icon="oi-arrow-right" type="action" string="Set Warehouse Routes" class="btn-link"/>\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="Advanced Scheduling" id="schedule_info">\n                            <setting company_dependent="1" help="Configure your horizon to trigger reordering rules earlier to get a head start on replenishment and avoid delays, or trigger it just-in-time ('0 days') to avoid overstocking.">\n                                <field name="horizon_days" class=