\\" column_invisible=\\"True\\"/>\\n                            <button string=\\"Grant Access\\" name=\\"action_grant_access\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"is_portal or is_internal or email_state != 'ok'\\"/>\\n                            <button string=\\"Revoke Access\\" name=\\"action_revoke_access\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"not is_portal or is_internal\\"/>\\n                            <button string=\\"Re-Invite\\" name=\\"action_invite_again\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"not is_portal or is_internal or email_state != 'ok'\\"/>\\n                            <button string=\\"Internal User\\" invisible=\\"not is_internal\\" disabled=\\"True\\" title=\\"This partner is linked to an internal User and already has access to the Portal.\\"/>\\n                        </list>\\n                    </field>\\n                    <footer>\\n                        <button string=\\"Close\\" class=\\"btn-primary\\" special=\\"save\\" data-hotkey=\\"v\\"/>\\n                    </footer>\\n                </form>", "es_ES": "<form string=\\"Administración de acceso al portal\\">\\n                    <div class=\\"mb-3\\">\\n                        Seleccione que contactos deben pertenecer al portal en la siguiente lista.\\nLa dirección de correo electrónico de cada contacto seleccionado debe ser válida y única.\\nSi es necesario, puede corregir una dirección de correo de un contacto directamente en la lista.\\n                    </div>\\n                    <field name=\\"welcome_message\\" placeholder=\\"Este texto aparece al final del correo electrónico que reciben los nuevos usuarios del portal.\\" class=\\"mb-3\\"/>\\n                    <field name=\\"user_ids\\" class=\\"o_portal_wizard_user_one2many\\" widget=\\"portal_wizard_user_one2many\\">\\n                        <list string=\\"Contactos\\" editable=\\"bottom\\" create=\\"false\\" delete=\\"false\\">\\n                            <field name=\\"partner_id\\" force_save=\\"1\\"/>\\n                            <field name=\\"email\\" readonly=\\"is_internal\\"/>\\n                            <field name=\\"email_state\\" column_invisible=\\"True\\"/>\\n                            <button name=\\"action_refresh_modal\\" type=\\"object\\" icon=\\"fa-check text-success\\" invisible=\\"email_state != 'ok'\\" title=\\"Dirección de correo electrónico válida\\"/>\\n                            <button name=\\"action_refresh_modal\\" type=\\"object\\" icon=\\"fa-times text-danger\\" invisible=\\"email_state != 'ko'\\" title=\\"Dirección de correo electrónico no válida\\"/>\\n                            <button name=\\"action_refresh_modal\\" type=\\"object\\" icon=\\"fa-user-times text-danger\\" invisible=\\"email_state != 'exist'\\" title=\\"Otro usuario ya usa esta dirección de correo electrónico\\"/>\\n                            <field name=\\"login_date\\"/>\\n                            <field name=\\"is_portal\\" column_invisible=\\"True\\"/>\\n                            <field name=\\"is_internal\\" column_invisible=\\"True\\"/>\\n                            <button string=\\"Otorgar acceso\\" name=\\"action_grant_access\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"is_portal or is_internal or email_state != 'ok'\\"/>\\n                            <button string=\\"Revocar el acceso\\" name=\\"action_revoke_access\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"not is_portal or is_internal\\"/>\\n                            <button string=\\"Volver a invitar\\" name=\\"action_invite_again\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"not is_portal or is_internal or email_state != 'ok'\\"/>\\n                            <button string=\\"Usuario interno\\" invisible=\\"not is_internal\\" disabled=\\"True\\" title=\\"Este contacto está vinculado a un usuario interno que ya tiene acceso al portal.\\"/>\\n                        </list>\\n  