                <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"pending,sent,canceled\\"/>\\n                </header>\\n                <sheet>\\n                    <div class=\\"oe_title\\">\\n                        <h1><field name=\\"display_name\\"/></h1>\\n                    </div>\\n                    <group>\\n                        <field name=\\"reference\\" widget=\\"reference\\"/>\\n                        <field name=\\"attachment_datas\\" filename=\\"attachment_fname\\"/>\\n                        <field name=\\"attachment_fname\\" invisible=\\"1\\"/>\\n                        <field name=\\"partner_id\\"/>\\n                        <field name=\\"user_id\\"/>\\n                        <field name=\\"info_msg\\" widget=\\"html\\"/>\\n                    </group>\\n                    <group groups=\\"base.group_no_one\\">\\n                        <field name=\\"model\\"/>\\n                        <field name=\\"res_id\\"/>\\n                        <field name=\\"color\\"/>\\n                        <field name=\\"duplex\\"/>\\n                    </group>\\n                </sheet>\\n            </form>"}	<?xml version="1.0"?>\n<form>\n                <header>\n                    <button name="snailmail_print" string="Send Now" type="object" invisible="state not in ('pending', 'error')" class="oe_highlight"/>\n                    <button name="cancel" string="Cancel" type="object" invisible="state not in ('pending', 'error')"/>\n                    <field name="state" widget="statusbar" statusbar_visible="pending,sent,canceled"/>\n                </header>\n                <sheet>\n                    <div class="oe_title">\n                        <h1><field name="display_name"/></h1>\n                    </div>\n                    <group>\n                        <field name="reference" widget="reference"/>\n                        <field name="attachment_datas" filename="attachment_fname"/>\n                        <field name="attachment_fname" invisible="1"/>\n                        <field name="partner_id"/>\n                        <field name="user_id"/>\n                        <field name="info_msg" widget="html"/>\n                    </group>\n                    <group groups="base.group_no_one">\n                        <field name="model"/>\n                        <field name="res_id"/>\n                        <field name="color"/>\n                        <field name="duplex"/>\n                    </group>\n                </sheet>\n            </form>\n        	f	t	2026-11-17 08:30:06.904006	2026-11-24 18:48:00.717396	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
