673	16	\N	1	1	stock_backorder_confirmation	stock.backorder.confirmation	\N	form	stock/wizard/stock_backorder_confirmation_views.xml	primary	{"en_US": "<form string=\\"Backorder creation\\">\\n                <p name=\\"explanation-text\\">\\n                    You have processed less products than the initial demand.\\n                </p>\\n                <p class=\\"text-muted\\">\\n                    Create a backorder if you expect to process the remaining\\n                    products later. Do not create a backorder if you will not\\n                    process the remaining products.\\n                </p>\\n                <!-- Added to ensure a correct default_get behavior\\n\\n                The wizard is always opened with default_pick_ids values in context,\\n                which are used to generate the backorder_confirmation_line_ids.\\n\\n                To ensure default_pick_ids is correctly converted from the context\\n                by default_get, the field has to be present in the view.\\n                -->\\n                <field name=\\"pick_ids\\" invisible=\\"1\\"/>\\n\\n                <field name=\\"show_transfers\\" invisible=\\"1\\"/>\\n                <field name=\\"backorder_confirmation_line_ids\\" nolabel=\\"1\\" invisible=\\"not show_transfers\\">\\n                    <list create=\\"0\\" delete=\\"0\\" editable=\\"top\\">\\n                        <field name=\\"picking_id\\" force_save=\\"1\\" readonly=\\"1\\"/>\\n                        <field name=\\"to_backorder\\" widget=\\"boolean_toggle\\"/>\\n                    </list>\\n                </field>\\n\\n                <footer>\\n                    <button name=\\"process\\" string=\\"Create Backorder\\" type=\\"object\\" class=\\"oe_highlight\\" data-hotkey=\\"q\\"/>\\n                    <button name=\\"process_cancel_backorder\\" string=\\"No Backorder\\" type=\\"object\\" class=\\"btn-danger\\" invisible=\\"show_transfers\\" data-hotkey=\\"w\\"/>\\n                    <button string=\\"Discard\\" class=\\"btn-secondary\\" special=\\"cancel\\" data-hotkey=\\"x\\"/>\\n                </footer>\\n            </form>", "es_ES": "<form string=\\"Creación de entrega parcial\\">\\n                <p name=\\"explanation-text\\">\\n                    Ha procesado menos productos que la demanda inicial.\\n                </p>\\n                <p class=\\"text-muted\\">\\n                    Cree un pedido en espera si espera procesar los productos restantes\\n                   más adelante. No cree un pedido pendiente si no\\n                   procesará los productos restantes.\\n                </p>\\n                <!-- Added to ensure a correct default_get behavior\\n\\n                The wizard is always opened with default_pick_ids values in context,\\n                which are used to generate the backorder_confirmation_line_ids.\\n\\n                To ensure default_pick_ids is correctly converted from the context\\n                by default_get, the field has to be present in the view.\\n                -->\\n                <field name=\\"pick_ids\\" invisible=\\"1\\"/>\\n\\n                <field name=\\"show_transfers\\" invisible=\\"1\\"/>\\n                <field name=\\"backorder_confirmation_line_ids\\" nolabel=\\"1\\" invisible=\\"not show_transfers\\">\\n                    <list create=\\"0\\" delete=\\"0\\" editable=\\"top\\">\\n                        <field name=\\"picking_id\\" force_save=\\"1\\" readonly=\\"1\\"/>\\n                        <field name=\\"to_backorder\\" widget=\\"boolean_toggle\\"/>\\n                    </list>\\n                </field>\\n\\n                <footer>\\n                    <button name=\\"process\\" string=\\"Crear entrega parcial\\" type=\\"object\\" class=\\"oe_highlight\\" data-hotkey=\\"q\\"/>\\n                    <button name=\\"process_cancel_backorder\\" string=\\"Sin entrega parcial\\" type=\\"object\\" class=\\"btn-danger\\" invisible=\\"show_transfers\\" da