o de compra\\" type=\\"object\\" context=\\"{'send_rfq':False}\\" data-hotkey=\\"g\\"/>\\n                    <button name=\\"action_acknowledge\\" string=\\"Acusar recibo\\" type=\\"object\\" invisible=\\"acknowledged or state != 'purchase'\\"/>\\n                    <button name=\\"button_draft\\" invisible=\\"state != 'cancel'\\" string=\\"Establecer como borrador\\" type=\\"object\\" data-hotkey=\\"o\\"/>\\n                    <button name=\\"print_quotation\\" string=\\"Imprimir\\" type=\\"object\\" groups=\\"base.group_user\\" data-hotkey=\\"k\\" invisible=\\"state == 'purchase'\\"/>\\n                    <button name=\\"418\\" string=\\"Imprimir\\" type=\\"action\\" groups=\\"base.group_user\\" data-hotkey=\\"k\\" invisible=\\"state != 'purchase'\\"/>\\n                    <button name=\\"button_cancel\\" invisible=\\"state not in ('draft', 'to approve', 'sent', 'purchase') or locked\\" string=\\"Cancelar\\" type=\\"object\\" data-hotkey=\\"x\\"/>\\n                    <button name=\\"button_lock\\" type=\\"object\\" string=\\"Bloquear\\" invisible=\\"locked or state != 'purchase' or not lock_confirmed_po == 'lock'\\" data-hotkey=\\"l\\"/>\\n                    <button name=\\"button_unlock\\" type=\\"object\\" string=\\"Desbloquear\\" invisible=\\"not locked\\" groups=\\"purchase.group_purchase_manager\\" data-hotkey=\\"l\\"/>\\n                    <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,sent,purchase\\" readonly=\\"1\\"/>\\n                </header>\\n                <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not purchase_warning_text\\">\\n                    <field name=\\"purchase_warning_text\\" class=\\"fw-bold\\"/>\\n                </div>\\n                <div class=\\"alert alert-warning w-100 d-flex align-items-center gap-1\\" invisible=\\"state != 'draft' or not duplicated_order_ids\\" role=\\"alert\\">\\n                    <span>Advertencia: este pedido podría ser un duplicado de</span>\\n                    <field name=\\"duplicated_order_ids\\" widget=\\"x2many_buttons\\" string=\\"Documentos duplicados\\"/>\\n                </div>\\n                <sheet>\\n                    <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                        <button class=\\"oe_stat_button\\" name=\\"action_bill_matching\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" icon=\\"fa-bullseye\\" invisible=\\"not partner_id or state != 'purchase' or not partner_bill_count or invoice_status == 'invoiced'\\">\\n                            <div class=\\"o_field_statinfo\\">\\n                                <span class=\\"o_stat_text\\">Conciliación de factura</span>\\n                            </div>\\n                        </button>\\n                        <button type=\\"object\\" name=\\"action_view_invoice\\" class=\\"oe_stat_button\\" icon=\\"fa-pencil-square-o\\" invisible=\\"invoice_count == 0 or state in ('draft', 'sent', 'to approve')\\">\\n                            <field name=\\"invoice_count\\" widget=\\"statinfo\\" string=\\"Facturas de proveedores\\"/>\\n                            <field name=\\"invoice_ids\\" invisible=\\"1\\"/>\\n                        </button>\\n                        <button type=\\"object\\" name=\\"action_purchase_comparison\\" class=\\"oe_stat_button\\" invisible=\\"not show_comparison\\" icon=\\"fa-dollar\\">\\n                            <div class=\\"o_field_statinfo\\">\\n                                <span class=\\"o_stat_text\\">Comparación de precios</span>\\n                            </div>\\n                            <field name=\\"show_comparison\\" invisible=\\"1\\"/>\\n                        </button>\\n                    </div>\\n                    <div class=\\"badge rounded-pill text-bg-secondary float-end fs-6 border-0\\" invisible=\\"not locked\\">\\n                        <i class=\\"fa fa-lock\\"/>\\n                        Bloqueado\\n                    </div>\\n                    <div class=\\"oe_title\\">\\n                        <span class=\\"o_form_label\\" invisible=\\"state not in ('draft', 'sent')\\">Solicitud de presupuesto </span>\\n                        <span class=\\"o_form_label\\" invisible=\\"state in ('draft', 'sent')\\">Pedido de compra </span>\\n                        <h1 class=\\"d-flex\\">\\n                            <field name=\\"priority\\" widget=\\"priority\\" class=\\"me-3\\"/>\\n                            <field name=\\"name\\" readonly=\\"1\\"/>\\n                        </h1>\\n                    </div>\\n                    <group>\\n                        <group>\\n                            <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" context=\\"{'res_partner_search_mode': 'supplier', 'show_vat': True}\\" placeholder=\\"Nombre, NIF, correo electrónico o referencia\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                            <field name=\\"partner_ref\\"/>\\n                            <field name=\\"currency_id\\" groups=\\"base.group_multi_currency\\" force_save=\\"1\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <field name=\\"company_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                            <field name=\\"currency_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'purchase']\\" groups=\\"!base.group_multi_currency\\"/>\\n                            <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                        </group>\\n                        <group>\\n                            <field name=\\"date_order\\" invisible=\\"state  == 'purchase'\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                            <label for=\\"date_approve\\" invisible=\\"state != 'purchase'\\"/>\\n                            <div name=\\"date_approve\\" invisible=\\"state != 'purchase'\\" class=\\"o_row\\">\\n                                <field name=\\"date_approve\\"/>\\n                            </div>\\n                            <label for=\\"date_planned\\"/>\\n                            <div name=\\"date_planned_div\\" class=\\"o_row\\">\\n                                <field name=\\"date_planned\\" readonly=\\"state not in ('draft', 'sent', 'to approve', 'purchase')\\"/>\\n                            </div>\\n                            <label for=\\"receipt_reminder_email\\" class=\\"d-none\\" groups=\\"purchase.group_send_reminder\\"/>\\n                            <div name=\\"reminder\\" class=\\"o_row\\" groups=\\"purchase.group_send_reminder\\" title=\\"Envíe automáticamente un correo electrónico de confirmación al proveedor X días antes de la fecha de recepción prevista, pidiéndole que confirme la fecha exacta.\\">\\n                                <field name=\\"receipt_reminder_email\\"/>\\n                                <span>Pedir confirmación</span>\\n                                <div class=\\"o_row oe_inline\\" invisible=\\"not receipt_reminder_email\\">\\n                                    <field name=\\"reminder_date_before_receipt\\" class=\\"oe_inline\\" style=\\"max-width: 30px;\\"/>\\n                                    día(s) antes\\n                                    <widget name=\\"toaster_button\\" button_name=\\"send_reminder_preview\\" title=\\"Obtenga una vista previa del correo electrónico de recordatorio enviándolo a usted mismo.\\" invisible=\\"not id\\"/>\\n                                </div>\\n                            </div>\\n                        </group>\\n                    </group>\\n                    <notebook>\\n                        <page string=\\"Productos\\" name=\\"products\\">\\n                            <field name=\\"tax_country_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"order_line\\" widget=\\"product_label_section_and_note_field_o2m\\" mode=\\"list,kanban\\" context=\\"{'default_state': 'draft'}\\" readonly=\\"state == 'cancel' or locked\\" options=\\"{ 'subsections': True }\\">\\n                                <list string=\\"Líneas de pedido de compra\\" editable=\\"bottom\\" decoration-warning=\\"purchase_line_warn_msg\\">\\n                                    <control>\\n                                        <create name=\\"add_product_control\\" string=\\"Añadir un producto\\"/>\\n                                        <create name=\\"add_section_control\\" string=\\"Añadir una sección\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                        <create name=\\"add_note_control\\" string=\\"Añadir una nota\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                        <button name=\\"action_add_from_catalog\\" string=\\"Catálogo\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                    </control>\\n                                    <field name=\\"tax_calculation_rounding_method\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"display_type\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"currency_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_type\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"invoice_lines\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"technical_price_unit\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                    <!-- optional=\\"show\\" allows name (description) to be editable -->\\n                                    <field name=\\"product_id\\" widget=\\"product_label_section_and_note_field\\" readonly=\\"state in ('purchase', 'to approve', 'cancel') or is_downpayment\\" required=\\"not display_type and not is_downpayment\\" optional=\\"show\\" context=\\"{'partner_id':partner_id, 'quantity':product_qty, 'company_id': parent.company_id}\\" options=\\"{'show_label_warning': True}\\" force_save=\\"1\\" domain=\\"[('purchase_ok', '=', True), '|', ('company_id', '=', False), ('company_id', 'parent_of', parent.company_id)]\\"/>\\n                                    <field name=\\"name\\" widget=\\"section_and_note_text\\" optional=\\"show\\"/>\\n                                    <field name=\\"date_planned\\" optional=\\"hide\\" required=\\"not display_type and not is_downpayment\\" force_save=\\"1\\" readonly=\\"is_downpayment\\"/>\\n                                    <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" optional=\\"hide\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'purchase_order', 'amount_field': 'price_subtotal'}\\"/>\\n                                    <field name=\\"product_qty\\" readonly=\\"is_downpayment\\"/>\\n                                    <field name=\\"qty_received_manual\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"qty_received_method\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"qty_received\\" string=\\"Recibido\\" column_invisible=\\"parent.state != 'purchase'\\" readonly=\\"qty_received_method != 'manual' or is_downpayment\\" optional=\\"show\\"/>\\n                                    <field name=\\"qty_invoiced\\" string=\\"Facturado\\" column_invisible=\\"parent.state != 'purchase'\\" optional=\\"show\\"/>\\n                                    <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" readonly=\\"state in ('purchase', 'cancel') or is_downpayment\\" required=\\"not display_type and not is_downpayment\\" options=\\"{'no_create': True, 'no_open': True, 'quantity_field': 'product_qty'}\\" widget=\\"many2one_uom\\" force_save=\\"1\\" optional=\\"show\\"/>\\n                                    <field name=\\"price_unit\\" readonly=\\"qty_invoiced != 0\\"/>\\n                                    <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" domain=\\"[('type_tax_use', '=', 'purchase'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id), ('active', '=', True)]\\" context=\\"{'default_type_tax_use': 'purchase', 'search_view_ref': 'account.account_tax_view_search'}\\" options=\\"{'no_create': True}\\" optional=\\"show\\" readonly=\\"is_downpayment\\"/>\\n                                    <field name=\\"discount\\" string=\\"% de dto.\\" width=\\"50px\\" readonly=\\"qty_invoiced != 0\\" optional=\\"hide\\"/>\\n                                    <field name=\\"price_subtotal\\" string=\\"Importe\\"/>\\n                                </list>\\n                                <form string=\\"Línea de pedido de compra\\">\\n                                        <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                                        <field name=\\"state\\" invisible=\\"1\\"/>\\n                                        <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                        <group invisible=\\"display_type\\">\\n                                            <group>\\n                                                <field name=\\"product_id\\" context=\\"{'partner_id': parent.partner_id}\\" widget=\\"many2one_barcode\\" domain=\\"[('purchase_ok', '=', True), '|', ('company_id', '=', False), ('company_id', '=', parent.company_id)]\\" readonly=\\"state in ('purchase', 'to approve', 'cancel')\\"/>\\n                                                <label for=\\"product_qty\\"/>\\n                                                <div class=\\"o_row\\">\\n                                                    <field name=\\"product_qty\\"/>\\n                                                    <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" required=\\"not display_type and not is_downpayment\\" widget=\\"many2one_uom\\"/>\\n                                                </div>\\n                                                <field name=\\"qty_received_method\\" invisible=\\"1\\"/>\\n                                                <field name=\\"qty_received\\" string=\\"Cantidad recibida\\" invisible=\\"parent.state != 'purchase'\\" readonly=\\"qty_received_method != 'manual'\\"/>\\n                                                <field name=\\"qty_invoiced\\" string=\\"Cantidad facturada\\" invisible=\\"parent.state != 'purchase'\\"/>\\n                                                <field name=\\"price_unit\\"/>\\n                                                <field name=\\"discount\\"/>\\n                                                <field name=\\"tax_ids\\" widget=\\"many2many_tax_tags\\" domain=\\"[('type_tax_use', '=', 'purchase'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" options=\\"{'no_create': True}\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"date_planned\\" required=\\"not display_type and not is_downpayment\\"/>\\n                                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'purchase_order'}\\"/>\\n                                            </group>\\n                                            <group>\\n                                            <notebook colspan=\\"4\\">\\n                                                <page string=\\"Notas\\" name=\\"notes\\">\\n                                                    <field name=\\"name\\"/>\\n                                                </page>\\n                                                <page string=\\"Facturas y recepciones\\" name=\\"invoices_incoming_shiptments\\">\\n                                                    <field name=\\"invoice_lines\\"/>\\n                                                </page>\\n                                            </notebook>\\n                                            </group>\\n                                        </group>\\n                                        <label for=\\"name\\" string=\\"Nombre de la sección (p. ej., productos, servicios)\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                        <label for=\\"name\\" string=\\"Nombre de la subsección\\" invisible=\\"display_type != 'line_subsection'\\"/>\\n                                        <label for=\\"name\\" string=\\"Nota\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                        <field name=\\"name\\" nolabel=\\"1\\" invisible=\\"not display_type\\"/>\\n                                </form>\\n                                <kanban class=\\"o_kanban_mobile\\">\\n                                     <field name=\\"display_type\\"/>\\n                                     <field name=\\"tax_calculation_rounding_method\\"/>\\n                                     <templates>\\n                                         <t t-name=\\"card\\">\\n                                            <t t-if=\\"!record.display_type.raw_value\\">\\n                                                <div class=\\"row\\">\\n                                                    <field name=\\"product_id\\" class=\\"fw-bold col-8\\"/>\\n                                                    <span class=\\"fw-bold col-4\\">\\n                                                        Impuestos excl.: <field name=\\"price_subtotal\\" class=\\"float-end\\"/>\\n                                                    </span>\\n                                                </div>\\n                                                <div class=\\"row\\">\\n                                                    <span class=\\"col-8 text-muted\\">\\n                                                        Cantidad:\\n                                                        <field name=\\"product_qty\\"/>\\n                                                        <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" class=\\"small\\"/>\\n                                                    </span>\\n                                                    <span class=\\"fw-bold col-4\\" t-if=\\"record.tax_calculation_rounding_method.raw_value === 'round_per_line'\\">\\n                                                        Impuestos incl.: <field name=\\"price_total\\"/>\\n                                                    </span>\\n                                                </div>\\n                                                <span class=\\"text-muted\\">\\n                                                    Precio unitario:\\n                                                    <field name=\\"price_unit\\"/>\\n                                                </span>\\n                                                <span class=\\"text-muted\\" t-if=\\"record.discount.raw_value\\">\\n                                                    Descuento: <field name=\\"discount\\"/>%\\n                                                </span>\\n                                            </t>\\n                                            <div t-elif=\\"['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)\\">\\n                                                <div t-att-class=\\"{                                                     'fw-bolder': record.display_type.raw_value === 'line_section',                                                     'fw-bold': record.display_type.raw_value === 'line_subsection',                                                     'fst-italic': record.display_type.raw_value === 'line_note',                                                 }\\">\\n                                                    <field name=\\"name\\"/>\\n                                                </div>\\n                                            </div>\\n                                         </t>\\n                                     </templates>\\n                                 </kanban>\\n                            </field>\\n                            <group>\\n                                <group>\\n                                    <field colspan=\\"2\\" name=\\"note\\" nolabel=\\"1\\" placeholder=\\"Defina sus términos y condiciones ...\\"/>\\n                                </group>\\n                                <group class=\\"oe_subtotal_footer\\">\\n                                    <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" readonly=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                            <div class=\\"clearfix\\"/>\\n                        </page>\\n                        <page string=\\"Otra información\\" name=\\"purchase_delivery_invoice\\">\\n                            <group>\\n                                <group name=\\"other_info\\">\\n                                    <field name=\\"user_id\\" domain=\\"[('share', '=', False)]\\" widget=\\"many2one_avatar_user\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" readonly=\\"state in ['cancel', 'purchase']\\"/>\\n                                    <field name=\\"origin\\"/>\\n                                </group>\\n                                <group name=\\"invoice_info\\">\\n                                    <field name=\\"invoice_status\\" invisible=\\"state in ('draft', 'sent', 'to approve', 'cancel')\\"/>\\n                                    <field name=\\"payment_term_id\\" readonly=\\"invoice_status == 'invoiced' or locked\\" options=\\"{'no_create': True}\\"/>\\n                                    <field name=\\"fiscal_position_id\\" options=\\"{'no_create': True}\\" readonly=\\"invoice_status == 'invoiced' or locked\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Purchase Order" class="o_purchase_order">\n                <header>\n                    <field name="locked" invisible="1"/>\n                    <field name="lock_confirmed_po" invisible="1"/>\n                    <button name="action_rfq_send" invisible="state != 'draft'" string="Send RFQ" type="object" context="{'send_rfq':True}" class="oe_highlight" data-hotkey="g"/>\n                    <button name="button_confirm" type="object" invisible="state != 'sent'" string="Confirm Order" context="{'validate_analytic': True}" class="oe_highlight" id="bid_confirm" data-hotkey="q"/>\n                    <button name="button_approve" type="object" invisible="state != 'to approve'" string="Approve Order" class="oe_highlight" groups="purchase.group_purchase_manager" data-hotkey="z"/>\n                    <button name="action_rfq_send" invisible="state != 'sent'" string="Send RFQ" type="object" context="{'send_rfq':True}" data-hotkey="g"/>\n                    <button name="button_confirm" type="object" invisible="state != 'draft'" context="{'validate_analytic': True}" string="Confirm Order" id="draft_confirm" data-hotkey="q"/>\n                    <widget name="purchase_file_uploader" invisible="state != 'purchase'"/>\n                    <button name="action_rfq_send" invisible="state != 'purchase'" string="Send PO" type="object" context="{'send_rfq':False}" data-hotkey="g"/>\n                    <button name="action_acknowledge" string="Acknowledge" type="object" invisible="acknowledged or state != 'purchase'"/>\n                    <button name="button_draft" invisible="state != 'cancel'" string="Set to Draft" type="object" data-hotkey="o"/>\n                    <button name="print_quotation" string="Print" type="object" groups="base.group_user" data-hotkey="k" invisible="state == 'purchase'"/>\n                    <button name="418" string="Print" type="action" groups="base.group_user" data-hotkey="k" invisible="state != 'purchase'"/>\n                    <button name="button_cancel" invisible="state not in ('draft', 'to approve', 'sent', 'purchase') or locked" string="Cancel" type="object" data-hotkey="x"/>\n                    <button name="button_lock" type="object" string="Lock" invisible="locked or state != 'purchase' or not lock_confirmed_po == 'lock'" data-hotkey="l"/>\n                    <button name="button_unlock" type="object" string="Unlock" invisible="not locked" groups="purchase.group_purchase_manager" data-hotkey="l"/>\n                    <field name="state" widget="statusbar" statusbar_visible="draft,sent,purchase" readonly="1"/>\n                </header>\n                <div class="alert alert-warning" role="alert" invisible="not purchase_warning_text">\n                    <field name="purchase_warning_text" class="fw-bold"/>\n                </div>\n                <div class="alert alert-warning w-100 d-flex align-items-center gap-1" invisible="state != 'draft' or not duplicated_order_ids" role="alert">\n                    <span>Warning: this order might be a duplicate of</span>\n                    <field name="duplicated_order_ids" widget="x2many_buttons" string="Duplicated Documents"/>\n                </div>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <button class="oe_stat_button" name="action_bill_matching" type="object" groups="account.group_account_invoice" icon="fa-bullseye" invisible="not partner_id or state != 'purchase' or not partner_bill_count or invoice_status == 'invoiced'">\n                            <div class="o_field_statinfo">\n                                <span class="o_stat_text">Bill Matching</span>\n                            </div>\n                        </button>\n                        <button type="object" name="action_view_invoice" class="oe_stat_button" icon="fa-pencil-square-o" invisible="invoice_count == 0 or state in ('draft', 'sent', 'to approve')">\n                            <field name="invoice_count" widget="statinfo" string="Vendor Bills"/>\n                            <field name="invoice_ids" invisible="1"/>\n                        </button>\n                        <button type="object" name="action_purchase_comparison" class="oe_stat_button" invisible="not show_comparison" icon="fa-dollar">\n                            <div class="o_field_statinfo">\n                                <span class="o_stat_text">Price Comparison</span>\n                            </div>\n                            <field name="show_comparison" invisible="1"/>\n                        </button>\n                    </div>\n                    <div class="badge rounded-pill text-bg-secondary float-end fs-6 border-0" invisible="not locked">\n                        <i class="fa fa-lock"/>\n                        Locked\n                    </div>\n                    <div class="oe_title">\n                        <span class="o_form_label" invisible="state not in ('draft', 'sent')">Request for Quotation </span>\n                        <span class="o_form_label" invisible="state in ('draft', 'sent')">Purchase Order </span>\n                        <h1 class="d-flex">\n                            <field name="priority" widget="priority" class="me-3"/>\n                            <field name="name" readonly="1"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name="partner_id" widget="res_partner_many2one" context="{'res_partner_search_mode': 'supplier', 'show_vat': True}" placeholder="Name, TIN, Email, or Reference" readonly="state in ['cancel', 'purchase']"/>\n                            <field name="partner_ref"/>\n                            <field name="currency_id" groups="base.group_multi_currency" force_save="1" readonly="state in ['cancel', 'purchase']"/>\n                            <field name="id" invisible="1"/>\n                            <field name="company_id" invisible="1" readonly="state in ['cancel', 'purchase']"/>\n                            <field name="currency_id" invisible="1" readonly="state in ['cancel', 'purchase']" groups="!base.group_multi_currency"/>\n                            <field name="tax_calculation_rounding_method" invisible="1"/>\n                        </group>\n                        <group>\n                            <field name="date_order" invisible="state  == 'purchase'" readonly="state in ['cancel', 'purchase']"/>\n                            <label for="date_approve" invisible="state != 'purchase'"/>\n                            <div name="date_approve" invisible="state != 'purchase'" class="o_row">\n                                <field name="date_approve"/>\n                            </div>\n                            <label for="date_planned"/>\n                            <div name="date_planned_div" class="o_r