\\"order.amount_total\\"/></td>\\n                  </tr>\\n              </t>\\n          </t>\\n      </t>\\n  </t>"}	<?xml version="1.0"?>\n<t name="My Purchase Orders" t-name="purchase.portal_my_purchase_orders">\n      <t t-call="portal.portal_layout">\n          <t t-set="breadcrumbs_searchbar" t-value="True"/>\n\n          <t t-call="portal.portal_searchbar">\n              <t t-set="title">Purchase Orders</t>\n          </t>\n          <t t-if="not orders">\n              <p class="alert alert-warning">There are currently no purchase orders for your account.</p>\n          </t>\n          <t t-if="orders" t-call="portal.portal_table">\n              <thead>\n                  <tr class="active">\n                      <th id="order_name_header">\n                          <span class="d-none d-md-inline">Purchase Order #</span>\n                          <span class="d-block d-md-none">Ref.</span>\n                      </th>\n                      <th id="order_confirmation_header" class="text-end">\n                          <span class="d-none d-md-inline">Confirmation Date</span>\n                          <span class="d-block d-md-none">Confirmation</span>\n                      </th>\n                      <th id="order_badge_header" class="text-center"/>\n                      <th id="order_total_header" class="text-end">Total</th>\n                  </tr>\n              </thead>\n              <t t-foreach="orders" t-as="order">\n                  <tr>\n                      <td id="order_name"><a t-att-href="order.get_portal_url()"><t t-esc="order.name"/></a></td>\n                      <td id="order_confirmation" class="text-end">\n                          <span t-field="order.date_approve" t-options="{'widget': 'date'}"/>&amp;nbsp;\n                          <span class="d-none d-md-inline" t-field="order.date_approve" t-options="{'time_only': True}"/>\n                      </td>\n                      <td id="order_badge" class="text-center">\n                          <span t-if="order.invoice_status == 'to invoice'" class="badge rounded-pill text-bg-info">\n                              <i class="fa fa-fw fa-file-text" role="img" aria-label="Waiting for Bill" title="Waiting for Bill"/><span class="d-none d-md-inline"> Waiting for Bill</span>\n                          </span>\n                          <span t-if="order.state == 'cancel'" class="badge rounded-pill text-bg-secondary">\n                              <i class="fa fa-fw fa-remove" role="img" aria-label="Cancelled" title="Cancelled"/><span class="d-none d-md-inline"> Cancelled</span>\n                          </span>\n                      </td>\n                      <td id="order_total" class="text-end"><span t-field="order.amount_total"/></td>\n                  </tr>\n              </t>\n          </t>\n      </t>\n  </t>\n\n  	f	t	2026-11-24 08:08:48.040076	2026-11-24 18:48:00.717396	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
1142	16	\N	1	1	Purchase Order Portal Content	\N	purchase.purchase_order_portal_content	qweb	purchase/views/portal_templates.xml	primary	{"en_US": "<t name=\\"Purchase Order Portal Content\\" t-name=\\"purchase.purchase_order_portal_content\\">\\n      <!-- Intro -->\\n      <div id=\\"introduction\\" class=\\"mt-5 mt-lg-0 pb-2 pt-0\\">\\n        <h2 class=\\"my-0\\">\\n          <t t-if=\\"order.state in ['draft', 'sent']\\">Request for Quotation</t>\\n          <t t-else=\\"1\\">\\n            Purchase Order\\n          </t>\\n          <em t-esc=\\"order.name\\"/>\\n        </h2>\\n      </div>\\n\\n      <div>\\n          <!-- Informations -->\\n          <div id=\\"informations\\">\\n              <div class=\\"row\\" id=\\"po_date\\">\\n                  <div class=\\"mb-3 col-6\\">\\n                    <t t-if=\\"order.state in ['draft', 'sent']\\">\\n                      <strong>Request For Quotation Date:</strong>\\n                    </t>\\n                    <t t-if=\\"order.state in ['purchase', 'cancel']\\">\\n                      <strong>Order Date:</strong>\\n                    </t>\\n                    <span t-field=\\"order.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                  </div>\\n              </div>\\n              <div class=\\"row\\">\\n                  <div class=\\"col-lg-6\\">\\n                    <strong class=\\"d-block mb-1\\">From:</strong>\\n                    <address t-field=\\"order.company_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                    <t t-if=\\"order.date_approve\\">\\n                      <strong>Confirmation Date:</strong> <span t-field=\\"order.date_approve\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/><br/>\\n                    </t>\\n                    <div t-att-class=\\"'d-inline' if order.date_planned else 'd-none'\\">\\n                      <strong>Receipt Date:</strong><span class=\\"ms-1\\" t-field=\\"order.date_planned\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                    </div>\\n                  </div>\\n              </div>\\n\\n              <t t-set=\\"invoices\\" t-value=\\"[i for i in order.invoice_ids if i.state not in ['draft', 'cancel']]\\"/>\\n              <div t-if=\\"invoices\\" class=\\"row\\">\\n                  <div class=\\"col\\">\\n                      <strong class=\\"d-block mb-1\\">Invoices</strong>\\n                      <ul class=\\"list-group mb-4\\">\\n                          <t t-foreach=\\"invoices\\" t-as=\\"i\\">\\n                              <t t-set=\\"report_url\\" t-value=\\"i.get_portal_url(report_type='pdf', download=True)\\"/>\\n                              <div class=\\"d-flex flex-wrap align-items-center justify-content-between\\">\\n                                  <div>\\n                                      <a t-att-href=\\"report_url\\">\\n                                          <span t-esc=\\"i.name\\"/>\\n                                      </a>\\n                                      <div class=\\"small d-lg-inline-block\\">Date: <span class=\\"text-muted\\" t-field=\\"i.invoice_date\\"/></div>\\n                                  </div>\\n                                  <span t-if=\\"i.payment_state in ('paid', 'in_payment')\\" class=\\"badge rounded-pill text-bg-success small\\"><i class=\\"fa fa-fw fa-check\\"/>Paid</span>\\n                                  <span t-elif=\\"i.payment_state == 'reversed'\\" class=\\"badge rounded-pill text-bg-success small\\"><i class=\\"fa fa-fw fa-check\\"/>Reversed</span>\\n                                  <span t-else=\\"\\" class=\\"small badge rounded-pill text-bg-primary\\"><i class=\\"fa fa-fw fa-clock-o\\"/>Waiting Payment</span>\\n                              </div>\\n                          </t>\\n                      </ul>\\n                  </div>\\n              </div>\\n          </div>\\n\\n          <section id=\\"details\\" style=\\"page-break-inside: auto;\\" class=\\"mt32\\">\\n              <h3 id=\\"details\\">Pricing</h3>\\n\\n              <div class=\\"table-responsive\\">\\n                <table t-att-data-order-id=\\"order.id\\" t-att-data-token=\\"order.access_token\\" class=\\"table table-sm\\" id=\\"purchase_order_table\\">\\n                    <t t-set=\\"display_price_and_taxes\\" t-value=\\"not update_dates and order.state == 'purchase'\\"/>\\n                    <thead class=\\"bg-100\\">\\n                        <tr>\\n                            <th class=\\"text-start\\">Products</th>\\n                            <th class=\\"text-end\\">Quantity</th>\\n                            <th t-if=\\"update_dates\\" class=\\"text-end\\">Scheduled Date</th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">Unit Price</th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                <span>Taxes</span>\\n                            </th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">Disc.%</th>\\n                            <th class=\\"text-end\\" t-if=\\"display_price_and_taxes\\">\\n                                <span>Amount</span>\\n                            </th>\\n                        </tr>\\n                    </thead>\\n                    <tbody class=\\"purchase_tbody\\">\\n\\n                          <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                          <t t-set=\\"filtered_lines\\" t-value=\\"order.order_line.filtered(lambda l: l.display_type or l.product_qty != 0)\\"/>\\n\\n                          <t t-foreach=\\"filtered_lines\\" t-as=\\"line\\">\\n\\n                              <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n\\n                            <tr t-att-class=\\"'fw-bolder o_line_section' if line.display_type == 'line_section' else 'fw-bold o_line_subsection' if line.display_type == 'line_subsection' else 'fst-italic text-break o_line_note' if line.display_type == 'line_note' else ''\\">\\n                                <t t-if=\\"not line.display_type\\">\\n                                    <td id=\\"product_name\\" class=\\"d-flex\\">\\n                                        <img t-att-src=\\"line.product_id.image_128 and image_data_uri(line.product_id.image_128) or '/web/static/img/placeholder.png'\\" alt=\\"Product\\" class=\\"d-none d-lg-inline o_purchase_portal_product_image\\"/>\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <div id=\\"quote_qty\\">\\n                                            <span t-field=\\"line.product_qty\\"/>\\n                                            <span t-field=\\"line.product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                        </div>\\n                                    </td>\\n                                    <td t-if=\\"update_dates\\" class=\\"text-end\\">\\n                                        <div class=\\"container\\">\\n                                          <div class=\\"mb-3\\">\\n                                            <div class=\\"input-group date\\">\\n                                                <input type=\\"text\\" class=\\"form-control datetimepicker-input o-purchase-datetimepicker text-end\\" t-att-data-access-token=\\"order.access_token\\" t-att-data-order-id=\\"order.id\\" t-att-data-line-id=\\"line.id\\" t-att-data-value=\\"line.date_planned.isoformat()\\"/>\\n                                            </div>\\n                                          </div>\\n                                        </div>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <div t-field=\\"line.price_unit\\" class=\\"text-end\\"/>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <span t-out=\\"', '.join(map(lambda x: (x.name), line.tax_ids))\\"/>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <div t-field=\\"line.discount\\" class=\\"text-end\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\" t-if=\\"not update_dates and order.state == 'purchase'\\">\\n                                        <span class=\\"oe_order_line_price_subtotal\\" t-field=\\"line.price_subtotal\\"/>\\n                                    </td>\\n                                </t>\\n                                <t t-if=\\"line.display_type in ('line_section', 'line_subsection')\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                    <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                </t>\\n                                <t t-if=\\"line.display_type == 'line_note'\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                </t>\\n                            </tr>\\n                            <t t-if=\\"current_section and (line_last or filtered_lines[line_index+1].display_type in ('line_section', 'line_subsection')) and order.state == 'purchase'\\">\\n                                <tr class=\\"is-subtotal text-end\\">\\n                                    <td colspan=\\"99\\">\\n                                        <strong class=\\"mr16\\">Subtotal</strong>\\n                                        <span t-esc=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}\\"/>\\n                                    </td>\\n                                </tr>\\n                            </t>\\n                        </t>\\n                    </tbody>\\n                </table>\\n              </div>\\n\\n              <div id=\\"total\\" t-if=\\"order.state == 'purchase'\\" class=\\"row\\" name=\\"total\\" style=\\"page-break-inside: avoid;\\">\\n                  <div t-attf-class=\\"#{'col-4' if report_type != 'html' else 'col-sm-7 col-md-5'} ms-auto\\">\\n                      <t t-call=\\"purchase.purchase_order_portal_content_totals_table\\"/>\\n                  </div>\\n              </div>\\n          </section>\\n\\n          <section id=\\"terms\\" class=\\"mt-5\\" t-if=\\"order.note\\">\\n              <h3 class=\\"\\">Terms &amp; Conditions</h3>\\n              <hr class=\\"mt-0 mb-1\\"/>\\n              <em t-field=\\"order.note\\"/>\\n          </section>\\n\\n          <section class=\\"mt-5\\" t-if=\\"order.payment_term_id\\">\\n              <h3 class=\\"\\">Payment terms</h3>\\n              <hr class=\\"mt-0 mb-1\\"/>\\n              <span t-field=\\"order.payment_term_id\\"/>\\n          </section>\\n      </div>\\n  </t>", "es_ES": "<t name=\\"Purchase Order Portal Content\\" t-name=\\"purchase.purchase_order_portal_content\\">\\n      <!-- Intro -->\\n      <div id=\\"introduction\\" class=\\"mt-5 mt-lg-0 pb-2 pt-0\\">\\n        <h2 class=\\"my-0\\">\\n          <t t-if=\\"order.state in ['draft', 'sent']\\">Solicitud de presupuesto</t>\\n          <t t-else=\\"1\\">\\n            Pedido de compra\\n          </t>\\n          <em t-esc=\\"order.name\\"/>\\n        </h2>\\n      </div>\\n\\n      <div>\\n          <!-- Informations -->\\n          <div id=\\"informations\\">\\n              <div class=\\"row\\" id=\\"po_date\\">\\n                  <div class=\\"mb-3 col-6\\">\\n                    <t t-if=\\"order.state in ['draft', 'sent']\\">\\n                      <strong>Fecha de la solicitud de presupuesto:</strong>\\n                    </t>\\n                    <t t-if=\\"order.state in ['purchase', 'cancel']\\">\\n                      <strong>Fecha del pedido:</strong>\\n                    </t>\\n                    <span t-field=\\"order.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                  </div>\\n              </div>\\n              <div class=\\"row\\">\\n                  <div class=\\"col-lg-6\\">\\n                    <strong class=\\"d-block mb-1\\">Desde:</strong>\\n                    <address t-field=\\"order.company_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                    <t t-if=\\"order.date_approve\\">\\n                      <strong>Fecha de confirmación:</strong> <span t-field=\\"order.date_approve\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/><br/>\\n                    </t>\\n                    <div t-att-class=\\"'d-inline' if order.date_planned else 'd-none'\\">\\n                      <strong>Fecha de recepción:</strong><span class=\\"ms-1\\" t-field=\\"order.date_planned\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                    </div>\\n                  </div>\\n              </div>\\n\\n              <t t-set=\\"invoices\\" t-value=\\"[i for i in order.invoice_ids if i.state not in ['draft', 'cancel']]\\"/>\\n              <div t-if=\\"invoices\\" class=\\"row\\">\\n                  <div class=\\"col\\">\\n                      <strong class=\\"d-block mb-1\\">Facturas</strong>\\n                      <ul class=\\"list-group mb-4\\">\\n                          <t t-foreach=\\"invoices\\" t-as=\\"i\\">\\n                              <t t-set=\\"report_url\\" t-value=\\"i.get_portal_url(report_type='pdf', download=True)\\"/>\\n                              <div class=\\"d-flex flex-wrap align-items-center justify-content-between\\">\\n                                  <div>\\n                                      <a t-att-href=\\"report_url\\">\\n                                          <span t-esc=\\"i.name\\"/>\\n                                      </a>\\n                                      <div class=\\"small d-lg-inline-block\\">Fecha: <span class=\\"text-muted\\" t-field=\\"i.invoice_date\\"/></div>\\n                                  </div>\\n                                  <span t-if=\\"i.payment_state in ('paid', 'in_payment')\\" class=\\"badge rounded-pill text-bg-success small\\"><i class=\\"fa fa-fw fa-check\\"/>Pagado</span>\\n                                  <span t-elif=\\"i.payment_state == 'reversed'\\" class=\\"badge rounded-pill text-bg-success small\\"><i class=\\"fa fa-fw fa-check\\"/>Revertido</span>\\n                                  <span t-else=\\"\\" class=\\"small badge rounded-pill text-bg-primary\\"><i class=\\"fa fa-fw fa-clock-o\\"/>Esperando pago</span>\\n                              </div>\\n                          </t>\\n                      </ul>\\n                  </div>\\n              </div>\\n          </div>\\n\\n          <section id=\\"details\\" style=\\"page-break-inside: auto;\\" class=\\"mt32\\">\\n              <h3 id=\\"details\\">Precio</h3>\\n\\n              <div class=\\"table-responsive\\">\\n                <table t-att-data-order-id=\\"order.id\\" t-att-data-token=\\"order.access_token\\" class=\\"table table-sm\\" id=\\"purchase_order_table\\">\\n                    <t t-set=\\"display_price_and_taxes\\" t-value=\\"not update_dates and order.state == 'purchase'\\"/>\\n                    <thead class=\\"bg-100\\">\\n                        <tr>\\n                            <th class=\\"text-start\\">Productos</th>\\n                            <th class=\\"text-end\\">Cantidad</th>\\n                            <th t-if=\\"update_dates\\" class=\\"text-end\\">Fecha programada</th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">Precio unitario</th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                <span>Impuestos</span>\\n                            </th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">% de dto.</th>\\n                            <th class=\\"text-end\\" t-if=\\"display_price_and_taxes\\">\\n                                <span>Importe</span>\\n                            </th>\\n                        </tr>\\n                    </thead>\\n                    <tbody class=\\"purchase_tbody\\">\\n\\n                          <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                          <t t-set=\\"filtered_lines\\" t-value=\\"order.order_line.filtered(lambda l: l.display_type or l.product_qty != 0)\\"/>\\n\\n                          <t t-foreach=\\"filtered_lines\\" t-as=\\"line\\">\\n\\n                              <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n\\n                            <tr t-att-class=\\"'fw-bolder o_line_section' if line.display_type == 'line_section' else 'fw-bold o_line_subsection' if line.display_type == 'line_subsection' else 'fst-italic text-break o_line_note' if line.display_type == 'line_note' else ''\\">\\n                                <t t-if=\\"not line.display_type\\">\\n                                    <td id=\\"product_name\\" class=\\"d-flex\\">\\n                                        <img t-att-src=\\"line.product_id.image_128 and image_data_uri(line.product_id.image_128) or '/web/static/img/placeholder.png'\\" alt=\\"Producto\\" class=\\"d-none d-lg-inline o_purchase_portal_product_image\\"/>\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <div id=\\"quote_qty\\">\\n                                            <span t-field=\\"line.product_qty\\"/>\\n                                            <span t-field=\\"line.product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                        </div>\\n                                    </td>\\n                                    <td t-if=\\"update_dates\\" class=\\"text-end\\">\\n                                        <div class=\\"container\\">\\n                                          <div class=\\"mb-3\\">\\n                                            <div class=\\"input-group date\\">\\n                                                <input type=\\"text\\" class=\\"form-control datetimepicker-input o-purchase-datetimepicker text-end\\" t-att-data-access-token=\\"order.access_token\\" t-att-data-order-id=\\"order.id\\" t-att-data-line-id=\\"line.id\\" t-att-data-value=\\"line.date_planned.isoformat()\\"/>\\n                                            </div>\\n                                          </div>\\n                                        </div>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <div t-field=\\"line.price_unit\\" class=\\"text-end\\"/>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <span t-out=\\"', '.join(map(lambda x: (x.name), line.tax_ids))\\"/>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <div t-field=\\"line.discount\\" class=\\"text-end\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\" t-if=\\"not update_dates and order.state == 'purchase'\\">\\n                                        <span class=\\"oe_order_line_price_subtotal\\" t-field=\\"line.price_subtotal\\"/>\\n                                    </td>\\n                                </t>\\n                                <t t-if=\\"line.display_type in ('line_section', 'line_subsection')\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                    <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                </t>\\n                                <t t-if=\\"line.display_type == 'line_note'\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                </t>\\n                            </tr>\\n                            <t t-if=\\"current_section and (line_last or filtered_lines[line_index+1].display_type in ('line_section', 'line_subsection')) and order.state == 'purchase'\\">\\n                                <tr class=\\"is-subtotal text-end\\">\\n                                    <td colspan=\\"99\\">\\n                                        <strong class=\\"mr16\\">Subtotal</strong>\\n                                        <span t-esc=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}\\"/>\\n                                    </td>\\n                                </tr>\\n                            </t>\\n                        </t>\\n                    </tbody>\\n                </table>\\n              </div>\\n\\n              <div id=\\"total\\" t-if=\\"order.state == 'purchase'\\" class=\\"row\\" name=\\"total\\" style=\\"page-break-inside: avoid;\\">\\n                  <div t-attf-class=\\"#{'col-4' if report_type != 'html' else 'col-sm-7 col-md-5'} ms-auto\\">\\n                      <t t-call=\\"purchase.purchase_order_portal_content_totals_table\\"/>\\n                  </div>\\n              </div>\\n          </section>\\n\\n          <section id=\\"terms\\" class=\\"mt-5\\" t-if=\\"order.note\\">\\n              <h3 class=\\"\\">Términos y condiciones</h3>\\n              <hr class=\\"mt-0 mb-1\\"/>\\n              <em t-field=\\"order.note\\"/>\\n          </section>\\n\\n          <section class=\\"mt-5\\" t-if=\\"order.payment_term_id\\">\\n              <h3 class=\\"\\">Condiciones de pago</h3>\\n              <hr class=\\"mt-0 mb-1\\"/>\\n              <span t-field=\\"order.payment_term_id\\"/>\\n          </section>\\n      </div>\\n  </t>"}	<?xml version="1.0"?>\n<t name="Purchase Order Portal Content" t-name="purchase.purchase_order_portal_content">\n      <!-- Intro -->\n      <div id="introduction" class="mt-5 mt-lg-0 pb-2 pt-0">\n        <h2 class="my-0">\n          <t t-if="order.state in ['draft', 'sent']">Request for Quotation</t>\n          <t t-else="1">\n            Purchase Order\n          </t>\n          <em t-esc="order.name"/>\n        </h2>\n      </div>\n\n      <div>\n          <!-- Informations -->\n          <div id="informations">\n              <div class="row" id="po_date">\n                  <div class="mb-3 col-6">\n                    <t t-if="order.state in ['draft', 'sent']">\n                      <strong>Request For Quotation Date:</strong>\n                    </t>\n                    <t t-if="order.state in ['purchase', 'cancel']">\n                      <strong>Order Date:</strong>\n                    </t>\n                    <span t-field="order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n                  </div>\n              </div>\n              <div class="row">\n                  <div class="col-lg-6">\n                    <strong class="d-block mb-1">From:</strong>\n                    <address t-field="order.company_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                    <t t-if="order.date_approve">\n                      <strong>Confirmation Date:</strong> <span t-field="order.date_approve" t-options="{&quot;widget&quot;: &quot;date&quot;}"/><br/>\n                    </t>\n                    <div t-att-class="'d-inline' if order.date_planned else 'd-none'">\n                      <strong>Receipt Date:</strong><span class="ms-1" t-field="order.date_planned" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n                    </div>\n                  </div>\n              </div>\n\n              <t t-set="invoices" t-value="[i for i in order.invoice_ids if i.state not in ['draft', 'cancel']]"/>\n              <div t-if="invoices" class="row">\n                  <div class="col">\n                      <strong class="d-block mb-1">Invoices</strong>\n                      <ul class="list-group mb-4">\n                          <t t-foreach="invoices" t-as="i">\n                              <t t-set="report_url" t-value="i.get_portal_url(report_type='pdf', download=True)"/>\n                              <div class="d-flex flex-wrap align-items-center justify-content-between">\n                                  <div>\n                                      <a t-att-href="report_url">\n                                          <span t-esc="i.name"/>\n                                      </a>\n                                      <div class="small d-lg-inline-block">Date: <span class="text-muted" t-field="i.invoice_date"/></div>\n                                  </div>\n                                  <span t-if="i.payment_state in ('paid', 'in_payment')" class="badge rounded-pill text-bg-success small"><i class="fa fa-fw fa-check"/>Paid</span>\n                                  <span t-elif="i.payment_state == 'reversed'" class="badge rounded-pill text-bg-success small"><i class="fa fa-fw fa-check"/>Reversed</span>\n                                  <span t-else="" class="small badge rounded-pill text-bg-primary"><i class="fa fa-fw fa-clock-o"/>Waiting Payment</span>\n                              </div>\n                          </t>\n                      </ul>\n                  </div>\n              </div>\n          </div>\n\n          <section id="details" style="page-break-inside: auto;" class="mt32">\n              <h3 id="details">Pricing</h3>\n\n              <div class="table-responsive">\n                <table t-att-data-order-id="order.id" t-att-data-token="order.access_token" class="table table-sm" id="purchase_order_table">\n                    <t t-set="display_price_and_taxes" t-value="not update_dates and order.state == 'purchase'"/>\n                    <thead class="bg-100">\n                        <tr>\n                            <th class="text-start">Products</th>\n                            <th class="text-end">Quantity</th>\n                            <th t-if="update_dates" class="text-end">Scheduled Date</th>\n                            <th t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">Unit Price</th>\n                            <th t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                <span>Taxes</span>\n                            </th>\n                            <th t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">Disc.%</th>\n                            <th class="text-end" t-if="display_price_and_taxes">\n                                <span>Amount</span>\n                            </th>\n                        </tr>\n                    </thead>\n                    <tbody class="purchase_tbody">\n\n                          <t t-set="current_subtotal" t-value="0"/>\n                          <t t-set="filtered_lines" t-value="order.order_line.filtered(lambda l: l.display_type or l.product_qty != 0)"/>\n\n                          <t t-foreach="filtered_lines" t-as="line">\n\n                              <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>\n\n                            <tr t-att-class="'fw-bolder o_line_section' if line.display_type == 'line_section' else 'fw-bold o_line_subsection' if line.display_type == 'line_subsection' else 'fst-italic text-break o_line_note' if line.display_type == 'line_note' else ''">\n                                <t t-if="not line.display_type">\n                                    <td id="product_name" class="d-flex">\n                                        <img t-att-src="line.product_id.image_128 and image_data_uri(line.product_id.image_128) or '/web/static/img/placeholder.png'" alt="Product" class="d-none d-lg-inline o_purchase_portal_product_image"/>\n                                        <span t-field="line.name"/>\n                                    </td>\n                                    <td class="text-end">\n                                        <div id="quote_qty">\n                                            <span t-field="line.product_qty"/>\n                                            <span t-field="line.product_uom_id" groups="uom.group_uom"/>\n                                        </div>\n                                    </td>\n                                    <td t-if="update_dates" class="text-end">\n                                        <div class="container">\n                                          <div class="mb-3">\n                                            <div class="input-group date">\n                                                <input type="text" class="form-control datetimepicker-input o-purchase-datetimepicker text-end" t-att-data-access-token="order.access_token" t-att-data-order-id="order.id" t-att-data-line-id="line.id" t-att-data-value="line.date_planned.isoformat()"/>\n                                            </div>\n                                          </div>\n                                        </div>\n                                    </td>\n                                    <td t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                        <div t-field="line.price_unit" class="text-end"/>\n                                    </td>\n                                    <td t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                        <span t-out="', '.join(map(lambda x: (x.name), line.tax_ids))"/>\n                                    </td>\n                                    <td t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                        <div t-field="line.discount" class="text-end"/>\n                                    </td>\n                                    <td class="text-end" t-if="not update_dates and order.state == 'purchase'">\n                                        <span class="oe_order_line_price_subtotal" t-field="line.price_subtotal"/>\n                                    </td>\n                                </t>\n                                <t t-if="line.display_type in ('line_section', 'line_subsection')">\n                                    <td colspan="99">\n                                        <span t-field="line.name"/>\n                                    </td>\n                                    <t t-set="current_section" t-value="line"/>\n                                    <t t-set="current_subtotal" t-value="0"/>\n                                </t>\n                                <t t-if="line.display_type == 'line_note'">\n                                    <td colspan="99">\n                                        <span t-field="line.name"/>\n                                    </td>\n                                </t>\n                            </tr>\n                            <t t-if="current_section and (line_last or filtered_lines[line_index+1].display_type in ('line_section', 'line_subsection')) and order.state == 'purchase'">\n                                <tr class="is-subtotal text-end">\n                                    <td colspan="99">\n                                        <strong class="mr16">Subtotal</strong>\n                                        <span t-esc="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </t>\n                    </tbody>\n                </table>\n              </div>\n\n              <div id="total" t-if="order.state == 'purchase'" class="row" name="total" style="page-break-inside: avoid;">\n                  <div t-attf-class="#{'col-4' if report_type != 'html' else 'col-sm-7 col-md-5'} ms-auto">\n                      <t t-call="purchase.purchase_order_portal_content_totals_table"/>\n                  </div>\n              </div>\n          </section>\n\n          <section id="terms" class="mt-5" t-if="order.note">\n              <h3 class="">Terms &amp; Conditions</h3>\n              <hr class="mt-0 mb-1"/>\n              <em t-field="order.note"/>\n          </section>\n\n          <section class="mt-5" t-if="order.payment_term_id">\n              <h3 class="">Payment terms</h3>\n              <hr class="mt-0 mb-1"/>\n              <span t-field="order.payment_term_id"/>\n          </section>\n      </div>\n  </t>\n\n  	f	t	2026-11-24 08:08:48.040076	2026-11-24 18:48:00.717396	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
1143	16	\N	1	1	purchase_order_portal_content_totals_table	\N	purchase.purchase_order_portal_content_totals_table	qweb	purchase/views/portal_templates.xml	primary	{"en_US": "<t t-name=\\"purchase.purchase_order_portal_content_totals_table\\">\\n      <table class=\\"table table-sm\\">\\n          <t t-call=\\"purchase.document_tax_totals\\">\\n                <t t-set=\\"tax_totals\\" t-value=\\"order.tax_totals\\"/>\\n                <t t-set=\\"currency\\" t-value=\\"order.currency_id\\"/>\\n          </t>\\n      </table>\\n  </t>"}	<?xml version="1.0"?>\n<t t-name="purchase.purchase_order_portal_content_totals_table">\n      <table class="table table-sm">\n          <t t-call="purchase.document_tax_totals">\n                <t t-set="tax_totals" t-value="order.tax_totals"/>\n                <t t-set="currency" t-value="order.currency_id"/>\n          </t>\n      </table>\n  </t>\n\n  	f	t	2026-11-24 08:08:48.040076	2026-11-24 18:48:00.717396	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
1144	16	1141	1	1	Portal: My Purchase Order Update Dates	\N	purchase.portal_my_purchase_order_update_date	qweb	purchase/views/portal_templates.xml	primary	{"en_US": "<data name=\\"Portal: My Purchase Order Update Dates\\" inherit_id=\\"purchase.portal_my_purchase_order\\" primary=\\"True\\">\\n    <xpath expr=\\"////div[@id='portal_purchase_content']\\" position=\\"replace\\">\\n      <div id=\\"portal_purchase_content\\">\\n        <t t-set=\\"update_dates\\" t-value=\\"True\\"/>\\n        <div><t t-call=\\"purchase.purchase_order_portal_content\\"/></div>\\n      </div>\\n    </xpath>\\n  <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">purchase.portal_my_purchase_order_update_date</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data name="Portal: My Purchase Order Update Dates" inherit_id="purchase.portal_my_purchase_order" primary="True">\n    <xpath expr="////div[@id='portal_purchase_content']" position="replace">\n      <div id="portal_purchase_content">\n        <t t-set="update_dates" t-value="True"/>\n        <div><t t-call="purchase.purchase_order_portal_content"/></div>\n      </div>\n    </xpath>\n  <xpath expr="." position="attributes"><attribute name="t-name">purchase.portal_my_purchase_order_update_date</attribute></xpath></data>\n\n	f	t	2026-11-24 08:08:48.040076	2026-11-24 18:48:00.717396	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	\N
1145	16	\N	1	1	report_purchaseorder_document	\N	purchase.report_purchaseorder_document	qweb	purchase/report/purchase_order_templates.xml	primary	{"en_US": "<t t-name=\\"purchase.report_purchaseorder_document\\">\\n    <t t-call=\\"web.external_layout\\">\\n        <t t-set=\\"o\\" t-value=\\"o.with_context(lang=o.partner_id.lang)\\"/>\\n        <t t-set=\\"forced_vat\\" t-value=\\"o.fiscal_position_id.foreign_vat\\"/> <!-- So that it appears in the report instead of the company VAT if it's set -->\\n        <t t-set=\\"address\\">\\n            <div t-field=\\"o.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n        </t>\\n        <t t-if=\\"o.dest_address_id\\">\\n            <t t-set=\\"information_block\\">\\n                <strong class=\\"d-block mt-3\\">Shipping address</strong>\\n                <div t-if=\\"o.dest_address_id\\">\\n                    <div t-field=\\"o.dest_address_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\" name=\\"purchase_shipping_address\\"/>\\n                </div>\\n\\n            </t>\\n        </t>\\n        <div class=\\"page\\">\\n            <div class=\\"oe_structure\\"/>\\n\\n            <div class=\\"mt-4\\">\\n                <t t-set=\\"layout_document_title\\">\\n                    <t t-if=\\"o.state in ['draft', 'sent', 'to approve']\\">Request for Quotation #<span t-field=\\"o.name\\"/></t>\\n                    <t t-if=\\"o.state == 'purchase'\\">Purchase Order #<span t-field=\\"o.name\\"/></t>\\n                    <t t-if=\\"o.state == 'cancel'\\">Cancelled Purchase Order #<span t-field=\\"o.name\\"/></t>\\n                </t>\\n            </div>\\n\\n            <div id=\\"informations\\" class=\\"row mb-4\\">\\n                <div t-if=\\"o.user_id\\" class=\\"col\\">\\n                    <strong>Buyer</strong>\\n                    <div t-field=\\"o.user_id\\"/>\\n                </div>\\n                <div t-if=\\"o.partner_ref\\" class=\\"col\\">\\n                    <strong>Your Order Reference</strong>\\n                    <div t-field=\\"o.partner_ref\\"/>\\n                </div>\\n                <div t-if=\\"o.state == 'purchase' and o.date_approve\\" class=\\"col-3 bm-2\\">\\n                    <strong>Order Date:</strong>\\n                    <p t-field=\\"o.date_approve\\" t-options=\\"{'date_only': 'true'}\\" class=\\"m-0\\"/>\\n                </div>\\n                <div t-elif=\\"o.date_order\\" class=\\"col-2 bm-2\\">\\n                    <strong>Order Deadline:</strong>\\n                    <p t-field=\\"o.date_order\\" t-options=\\"{'date_only': 'true'}\\" class=\\"m-0\\"/>\\n                </div>\\n                <div t-if=\\"o.date_planned\\" class=\\"col-2 bm-2\\">\\n                    <strong>Expected Arrival:</strong>\\n                    <p t-field=\\"o.date_planned\\" t-options=\\"{'date_only': 'true'}\\" class=\\"m-0\\"/>\\n                </div>\\n            </div>\\n\\n            <table class=\\"o_has_total_table table o_main_table table-borderless\\">\\n                <thead style=\\"display: table-row-group\\">\\n                    <tr>\\n                        <th name=\\"th_description\\" class=\\"text-start\\"><strong>Description</strong></th>\\n                        <th name=\\"th_quantity\\" class=\\"text-end\\"><strong>Qty</strong></th>\\n                        <th name=\\"th_price_unit\\" class=\\"text-end\\"><strong>Unit Price</strong></th>\\n                        <th name=\\"th_discount\\" class=\\"text-end\\"><strong>Disc.</strong></th>\\n                        <th name=\\"th_taxes\\" class=\\"text-end\\"><strong>Taxes</strong></th>\\n                        <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                            <strong>Amount</strong>\\n                        </th>\\n                    </tr>\\n                </thead>\\n                <tbody>\\n                    <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                    <t t-set=\\"filtered_lines\\" t-value=\\"o.order_line.filtered(lambda l: l.display_type or l.product_qty != 0)\\"/>\\n                    <t t-foreach=\\"filtered_lines\\" t-as=\\"line\\">\\n                        <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n\\n                        <tr t-att-class=\\"'fw-bolder o_line_section' if line.display_type == 'line_section' else 'fw-bold o_line_subsection' if line.display_type == 'line_subsection' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''\\">\\n                            <t t-if=\\"not line.display_type\\">\\n                                <td id=\\"product\\" class=\\"text-start\\">\\n                                    <span t-field=\\"line.name\\"/>\\n                                </td>\\n                                <td class=\\"text-end\\">\\n                                    <span t-field=\\"line.product_qty\\"/>\\n                                    <span t-field=\\"line.product_uom_id.name\\" groups=\\"uom.group_uom\\"/>\\n                                    <span t-if=\\"line.product_uom_id != line.product_id.uom_id\\" class=\\"text-muted small\\">\\n                                        <br/>\\n                                        <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\"/> <span t-field=\\"line.product_id.uom_id\\"/>\\n                                    </span>\\n                                </td>\\n                                <td class=\\"text-end\\">\\n                                    <span t-field=\\"line.price_unit\\"/>\\n                                </td>\\n                                <td class=\\"text-end\\">\\n                                    <span class=\\"text-align-bottom\\"><span t-field=\\"line.discount\\"/>%</span>\\n                                </td>\\n                                <td class=\\"text-end\\">\\n                                    <span t-out=\\"', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label)\\"/>\\n                                </td>\\n                                <td class=\\"text-end\\">\\n                                    <span t-field=\\"line.price_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\"/>\\n                                </td>\\n                            </t>\\n                            <t t-if=\\"line.display_type in ('line_section', 'line_subsection')\\">\\n                                <td colspan=\\"99\\" id=\\"section\\">\\n                                    <span t-field=\\"line.name\\"/>\\n                                </td>\\n                                <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                            </t>\\n                            <t t-if=\\"line.display_type == 'line_note'\\">\\n                                <td colspan=\\"99\\" id=\\"note\\">\\n                                    <span t-field=\\"line.name\\"/>\\n                                </td>\\n                            </t>\\n                        </tr>\\n                        <t t-if=\\"current_section and (line_last or filtered_lines[line_index+1].display_type in ('line_section', 'line_subsection'))\\">\\n                            <tr class=\\"is-subtotal text-end\\">\\n                                <td colspan=\\"99\\" id=\\"subtotal\\">\\n                                    <strong class=\\"mr16\\">Subtotal</strong>\\n                                    <span t-out=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\"/>\\n                                </td>\\n                            </tr>\\n                        </t>\\n                    </t>\\n                </tbody>\\n            </table>\\n\\n            <div id=\\"total\\" class=\\"row justify-content-end mt-n3\\">\\n                <div class=\\"col-4\\">\\n                    <table class=\\"o_total_table table table-borderless\\">\\n                        <t t-call=\\"purchase.document_tax_totals\\">\\n                            <t t-set=\\"tax_totals\\" t-value=\\"o.tax_totals\\"/>\\n                            <t t-set=\\"currency\\" t-value=\\"o.currency_id\\"/>\\n                        </t>\\n                    </table>\\n                </div>\\n            </div>\\n\\n            <p t-field=\\"o.note\\" class=\\"mt-4\\"/>\\n            <div class=\\"oe_structure\\"/>\\n\\n            <strong>Payment Terms: </strong>\\n            <span t-field=\\"o.payment_term_id\\" class=\\"mt-4\\"/>\\n\\n            <t t-set=\\"base_address\\" t-value=\\"o.env['ir.config_parameter'].sudo().get_param('web.base.url')\\"/>\\n            <t t-set=\\"portal_url\\" t-value=\\"base_address + '/my/purchase/' + str(o.id) + '#portal_connect_software_modal'\\"/>\\n            <div t-if=\\"any(u._is_portal() for u in o.partner_id.user_ids) and o._get_edi_builders()\\" class=\\"text-center\\">\\n                <a t-att-href=\\"portal_url\\">Connect your software</a> with <t t-out=\\"o.company_id.name\\"/> to create quotes automatically.\\n            </div>\\n        </div>\\n    </t>\\n</t>", "es_ES": "<t t-name=\\"purchase.report_purchaseorder_document\\">\\n    <t t-call=\\"web.external_layout\\">\\n        <t t-set=\\"o\\" t-value=\\"o.with_context(lang=o.partner_id.lang)\\"/>\\n        <t t-set=\\"forced_vat\\" t-value=\\"o.fiscal_position_id.foreign_vat\\"/> <!-- So that it a