"o_notification_alert alert alert-warning\\" invisible=\\"not has_active_session\\" role=\\"alert\\">\\n                            Actualmente hay una sesión abierta para este TPV. Algunas configuraciones solo se pueden cambiar después de que se cierra la sesión.\\n                            <button class=\\"btn\\" style=\\"padding:0\\" name=\\"close_ui\\" type=\\"object\\">Haga clic aquí para cerrar la sesión</button>\\n                        </div>\\n                        <div class=\\"o_notification_alert alert alert-warning\\" invisible=\\"company_has_template\\" role=\\"alert\\">\\n                            No hay un plan contable configurado en la compañía. Vaya a la configuración de facturación para instalar un plan contable.\\n                        </div>\\n                    </div>\\n\\n                    <!-- SHOW this div in create_mode (when '+ New Shop' is clicked in the general settings.) -->\\n                    <div id=\\"restaurant_on_create\\" class=\\"row mt16 o_settings_container\\" invisible=\\"not context.get('pos_config_create_mode', False)\\">\\n                        <setting>\\n                                <field name=\\"module_pos_restaurant\\"/>\\n                        </setting>\\n                    </div>\\n\\n                    <!-- HIDE this div in create_mode (when '+ New Shop' is clicked in the general settings.) -->\\n                    <div invisible=\\"context.get('pos_config_create_mode', False)\\">\\n                        <notebook>\\n                            <page string=\\"Configuración\\" name=\\"configuration\\">\\n                                <div class=\\"row mt16 o_settings_container\\">\\n                                    <setting title=\\"Los empleados pueden escanear su credencial o ingresar un PIN para iniciar sesión en una sesión de TPV. Estas credenciales se pueden configurar en la pestaña *Configuración de recursos humanos* del formulario del empleado.\\" string=\\"Iniciar sesión como empleado\\" help=\\"Permita registrar y cambiar entre empleados seleccionados\\">\\n                                        <field name=\\"module_pos_hr\\" readonly=\\"has_active_session\\"/>\\n                                        <div class=\\"content-group mt16\\" invisible=\\"not module_pos_hr\\">\\n                                            <div class=\\"text-warning\\" id=\\"warning_text_employees\\">\\n                                                Guarde esta página y luego regrese para configurar la función.\\n                                            </div>\\n                                        </div>\\n                                    </setting>\\n                                    <setting id=\\"other_devices\\" string=\\"Impresora ePos\\" help=\\"Conecte el dispositivo a su TPV sin una Caja IoT\\">\\n                                        <field name=\\"other_devices\\"/>\\n                                        <div class=\\"content-group\\" invisible=\\"not other_devices\\">\\n                                            <div class=\\"row mb-2\\">\\n                                                <div class=\\"col-lg-6\\">\\n                                                    <field name=\\"epson_printer_ip\\" placeholder=\\"Dirección IP de la impresora de recibos Epson\\" class=\\"w-100 pt-1\\"/>\\n                                                </div>\\n                                                <div class=\\"col-lg-6\\">\\n                                                    <widget name=\\"point_of_sale_test_epos\\"/>\\n                                                </div>\\n                                            </div>\\n                                            <div class=\\"row\\" invisible=\\"epson_printer_ip in [False, '']\\">\\n                                                <div class=\\"col-lg-6 o_light_label\\">\\n                                                    <label string=\\"Vincular cajón de efectivo\\" for=\\"iface_cashdrawer\\"/>\\n                                                </div>\\n                                                <div class=\\"col-lg-6\\">\\n                                                    <field name=\\"iface_cashdrawer\\"/>\\n                                                </div>\\n                                            </div>\\n                                        </div>\\n                                        <div role=\\"alert\\" class=\\"alert alert-warning\\" invisible=\\"not iface_print_via_proxy or not other_devices or epson_printer_ip in [False, '']\\">\\n                                            Se utilizará la impresora de recibos Epson en lugar de la impresora de recibos conectada a la caja IoT.\\n                                        </div>\\n                                    </setting>\\n                                    <setting string=\\"Caja IoT\\" help=\\"Conecta dispositivos mediante una caja IoT\\">\\n                                            <field name=\\"is_posbox\\"/>\\n                                            <div class=\\"content-group pos_iot_config ms-3\\" invisible=\\"not is_posbox\\">\\n                                                <div class=\\"row\\">\\n                                                    <div class=\\"col-lg-4 o_light_label\\">\\n                                                        <label string=\\"Dirección IP de la caja IoT\\" for=\\"proxy_ip\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-lg-8\\">\\n                                                        <field name=\\"proxy_ip\\"/>\\n                                                    </div>\\n                                                </div>\\n                                                <div class=\\"row iot_barcode_scanner\\">\\n                                                    <div class=\\"col-lg-5 o_light_label\\">\\n                                                        <label string=\\"Lector\\" for=\\"iface_scan_via_proxy\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-lg-7\\">\\n                                                        <field name=\\"iface_scan_via_proxy\\"/>\\n                                                    </div>\\n                                                </div>\\n                                                <div class=\\"row\\">\\n                                                    <div class=\\"col-lg-5 o_light_label\\">\\n                                                        <label string=\\"Báscula electrónica\\" for=\\"iface_electronic_scale\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-lg-7\\">\\n                                                        <field name=\\"iface_electronic_scale\\"/>\\n                                                    </div>\\n                                                </div>\\n                                                <div class=\\"row\\">\\n                                                    <div class=\\"col-lg-5 o_light_label\\">\\n                                                        <label string=\\"Impresora de recibos\\" for=\\"iface_print_via_proxy\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-lg-7\\">\\n                                                        <field name=\\"iface_print_via_proxy\\"/>\\n                                                   </div>\\n                                                </div>\\n                                                <div class=\\"row\\" invisible=\\"not iface_print_via_proxy\\">\\n                                                    <div class=\\"col-lg-5 o_light_label ps-4\\">\\n                                                        <label string=\\"Cajón portamonedas\\" for=\\"iface_cashdrawer\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-lg-7\\">\\n                                                        <field name=\\"iface_cashdrawer\\"/>\\n                                                    </div>\\n                                                </div>\\n                                            </div>\\n                                    </setting>\\n                                </div>\\n                            </page>\\n                            <page name=\\"checklist\\" string=\\"Lista de verificación\\">\\n                                <widget name=\\"lna_checklist\\"/>\\n                            </page>\\n                        </notebook>\\n                        <div groups=\\"base.group_system\\">\\n                            <p>\\n                                Más ajustes: <a href=\\"#\\" name=\\"455\\" type=\\"action\\" class=\\"btn-link o_form_uri\\" role=\\"button\\">Configuración y ajustes</a>\\n                            </p>\\n                        </div>\\n                    </div>\\n                </sheet>\\n\\n                <!-- Replace the default save/discard buttons so that when any of the buttons is clicked, the modal immediately closes. -->\\n                <footer invisible=\\"not context.get('pos_config_open_modal', False)\\">\\n                    <button string=\\"Guardar\\" special=\\"save\\" class=\\"btn-primary\\"/>\\n                    <button string=\\"Descartar\\" class=\\"btn-secondary\\" special=\\"cancel\\"/>\\n                </footer>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Point of Sale Configuration">\n                <sheet>\n                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                    <field name="active" invisible="1"/>\n                    <field name="company_has_template" invisible="1"/>\n                    <field name="has_active_session" invisible="1"/>\n                    <field name="other_devices" invisible="1"/>\n                    <field name="is_posbox" invisible="1"/>\n                    <field name="module_pos_hr" invisible="1"/>\n\n                    <div class="oe_title" id="title">\n                        <label for="name"/>\n                        <h1><field name="name" placeholder="e.g. NYC Shop"/></h1>\n                    </div>\n                    <!-- HIDE this div in create_mode (when '+ New Shop' is clicked in the general settings.) -->\n                    <div invisible="context.get('pos_config_create_mode', False)">\n                        <div class="o_notification_alert alert alert-warning" invisible="not has_active_session" role="alert">\n                            A session is currently opened for this PoS. Some settings can only be changed after the session is closed.\n                            <button class="btn" style="padding:0" name="close_ui" type="object">Click here to close the session</button>\n                        </div>\n                        <div class="o_notification_alert alert alert-warning" invisible="company_has_template" role="alert">\n                            There is no Chart of Accounts configured on the company. Please go to the invoicing settings to install a Chart of Accounts.\n                        </div>\n                    </div>\n\n                    <!-- SHOW this div in create_mode (when '+ New Shop' is clicked in the general settings.) -->\n                    <div id="restaurant_on_create" class="row mt16 o_settings_container" invisible="not context.get('pos_config_create_mode', False)">\n                        <setting>\n                                <field name="module_pos_restaurant"/>\n                        </setting>\n  