classes}}\\">\\n                            <t t-foreach=\\"wishes\\" t-as=\\"wish\\">\\n                                <t t-set=\\"product_variant\\" t-value=\\"wish.product_id\\"/>\\n                                <t t-set=\\"product\\" t-value=\\"product_variant.product_tmpl_id\\"/>\\n                                <t t-set=\\"product_href\\" t-value=\\"product_variant.website_url\\"/>\\n                                <t t-set=\\"combination_info\\" t-value=\\"product_variant._get_combination_info_variant()\\"/>\\n                                <article class=\\"o_wishlist_item\\" t-att-data-wish-id=\\"wish.id\\" t-att-data-product-id=\\"product_variant.id\\">\\n                                    <t t-call=\\"website_sale.products_item\\">\\n                                        <t t-set=\\"show_variations\\" t-value=\\"False\\"/>\\n                                        <t t-set=\\"show_ribbons\\" t-value=\\"False\\"/>\\n                                        <t t-set=\\"product_price\\">\\n                                            <br t-if=\\"combination_info['prevent_zero_price_sale']\\"/>\\n                                            <div t-else=\\"\\" class=\\"align-middle o_wish_price\\">\\n                                                <span aria-label=\\"Sale price\\">\\n                                                    <t t-out=\\"combination_info['price']\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\"/>\\n                                                </span>\\n                                                <small t-if=\\"combination_info['has_discounted_price']\\" class=\\"cart_product_base_unit_price text-muted\\">\\n                                                    <del aria-label=\\"Original price\\" t-out=\\"combination_info['list_price']\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': website.currency_id}\\" name=\\"product_list_price\\"/>\\n                                                </small>\\n                                            </div>\\n                                        </t>\\n                                        <t t-set=\\"product_actions\\">\\n                                            <div class=\\"o_wsale_product_action_row\\">\\n                                                <a t-if=\\"combination_info['prevent_zero_price_sale']\\" t-att-href=\\"website.contact_us_button_url + '?subject=' + combination_info['display_name']\\" class=\\"o_wsale_product_btn_primary btn btn-primary btn_cta\\">\\n                                                   <span class=\\"d-inline-flex align-items-baseline\\">\\n                                                        <i class=\\"fa fa-fw fa-envelope o_not-animable\\" role=\\"presentation\\"/>\\n                                                        <span class=\\"o_label small ms-1\\">\\n                                                            Contact Us\\n                                                        </span>\\n                                                    </span>\\n                                                </a>\\n                                                <button t-else=\\"\\" id=\\"add_to_cart_button\\" type=\\"button\\" class=\\"o_wsale_product_btn_primary btn btn-primary o_wish_add\\" t-att-data-show-quantity=\\"is_view_active('website_sale.product_quantity')\\" t-att-data-product-template-id=\\"product.id\\" t-att-data-product-product-id=\\"product_variant.id\\" t-att-data-product-type=\\"product.type\\" t-att-data-ptav-ids=\\"json.dumps(product_variant.product_template_attribute_value_ids.ids)\\">\\n                                                    <span class=\\"d-inline-flex align-items-baseline\\">\\n                                                        <i class=\\"fa fa-fw fa-shopping-cart o_not-animable\\" role=\\"presentation\\"/>\\n                                                        <span class=\\"o_lab