1345	16	\N	1	1	Cookie Policy	\N	website.cookie_policy	qweb	website/data/website_data.xml	primary	{"en_US": "<t name=\\"Cookie Policy\\" t-name=\\"website.cookie_policy\\">\\n        <t t-call=\\"website.layout\\">\\n            <div id=\\"wrap\\" class=\\"oe_structure\\">\\n                <section class=\\"pt8 pb8\\">\\n                    <div class=\\"container\\">\\n                        <h1 class=\\"pt16 h2-fs\\">Cookie Policy</h1>\\n                        <p>\\n                            Cookies are small bits of text sent by our servers to your computer or device when you access our services.\\n                            They are stored in your browser and later sent back to our servers so that we can provide contextual content.\\n                            Without cookies, using the web would be a much more frustrating experience.\\n                            We use them to support your activities on our website. For example, your session (so you don't have to login again) or your shopping cart.\\n                            <br/>\\n                            Cookies are also used to help us understand your preferences based on previous or current activity on our website (the pages you have\\n                            visited), your language and country, which enables us to provide you with improved services.\\n                            We also use cookies to help us compile aggregate data about site traffic and site interaction so that we can offer\\n                            better site experiences and tools in the future.\\n                        </p>\\n                        <p>\\n                            Here is an overview of the cookies that may be stored on your device when you visit our website:\\n                        </p>\\n                        <div class=\\"table-responsive\\">\\n                            <table class=\\"small table table-bordered text-center\\">\\n                                <thead class=\\"table-light\\">\\n                                    <tr>\\n                                        <th scope=\\"col\\" style=\\"width: 20%\\">Category of Cookie</th>\\n                                        <th scope=\\"col\\" style=\\"width: 50%; min-width: 200px;\\">Purpose</th>\\n                                        <th scope=\\"col\\" style=\\"width: 30%\\">Examples</th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <tr>\\n                                        <td>\\n                                            <p>Session &amp; Security<br/>(essential)</p>\\n                                        </td>\\n                                        <td>\\n                                            <p>\\n                                                Authenticate users, protect user data and allow the website to deliver the services users expects,\\n                                                such as maintaining the content of their cart, or allowing file uploads.\\n                                            </p>\\n                                            <p>The website will not work properly if you reject or discard those cookies.</p>\\n                                        </td>\\n                                        <td>\\n                                            session_id (Odoo)<br/>\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td>\\n                                            <p>Preferences<br/>(essential)</p>\\n                                        </td>\\n                                        <td>\\n                                            <p>Remember information about the preferred look or behavior of the website, such as your preferred language or region.</p>\\n                                            <p>Your experience may be degraded if you discard those cookies, but the website will still work.</p>\\n                                        </td>\\n                                        <td>\\n                                            frontend_lang (Odoo)\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td>Interaction History<br/>(optional)</td>\\n                                        <td>\\n                                            <p>\\n                                                Used to collect information about your interactions with the website, the pages you've seen,\\n                                                and any specific marketing campaign that brought you to the website.\\n                                            </p>\\n                                            <p>We may not be able to provide the best service to you if you reject those cookies, but the website will work.</p>\\n                                        </td>\\n                                        <td>\\n                                            im_livechat_previous_operator (Odoo)<br/>\\n                                            utm_campaign (Odoo)<br/>\\n                                            utm_source (Odoo)<br/>\\n                                            utm_medium (Odoo)\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td>\\n                                            <p>Advertising &amp; Marketing<br/>(optional)</p>\\n                                        </td>\\n                                        <td>\\n                                            <p>\\n                                                Used to make advertising more engaging to users and more valuable to publishers and advertisers,\\n                                                such as providing more relevant ads when you visit other websites that display ads or to improve reporting on ad campaign performance.\\n                                            </p>\\n                                            <p>Note that some third-party services may install additional cookies on your browser in order to identify you.</p>\\n                                            <p>\\n                                                You may opt-out of a third-party's use of cookies by visiting the <a class=\\"o_translate_inline\\" href=\\"https://optout.networkadvertising.org/?c=1\\" rel=\\"nofollow\\">Network Advertising Initiative opt-out page</a>.\\n                                                The website will still work if you reject or discard those cookies.\\n                                            </p>\\n                                        </td>\\n                                        <td>\\n                                            __gads (Google)<br/>\\n                                            __gac (Google)\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td>\\n                                            <p>Analytics<br/>(optional)</p>\\n                                        </td>\\n                                        <td>\\n                                            <p>\\n                                                Understand how visitors engage with our website, via Google Analytics.\\n                                                Learn more about <a class=\\"o_translate_inline\\" href=\\"https://support.google.com/analytics/answer/11397207?hl=en\\">Analytics cookies and privacy information.</a>\\n                                            </p>\\n                                            <p>The website will still work if you reject or discard those cookies.</p>\\n                                        </td>\\n                                        <td>\\n                                            _ga (Google)<br/>\\n                                            _gat (Google)<br/>\\n                                            _gid (Google)<br/>\\n                                            _gac_* (Google)\\n                                        </td>\\n                                    </tr>\\n                                </tbody>\\n                            </table>\\n                        </div>\\n                        <p>\\n                            You can choose to have your computer warn you each time a cookie is being sent, or you can choose to turn off all cookies.\\n                            Each browser is a little different, so look at your browser's Help menu to learn the correct way to modify your cookies.\\n                        </p>\\n                        <p>We do not currently support Do Not Track signals, as there is no industry standard for compliance.</p>\\n                    </div>\\n                </section>\\n            </div>\\n        </t>\\n    </t>", "es_ES": "<t name=\\"Cookie Policy\\" t-name=\\"website.cookie_policy\\">\\n        <t t-call=\\"website.layout\\">\\n            <div id=\\"wrap\\" class=\\"oe_structure\\">\\n                <section class=\\"pt8 pb8\\">\\n                    <div class=\\"container\\">\\n                        <h1 class=\\"pt16 h2-fs\\">Política de cookies</h1>\\n                        <p>\\n                            Las cookies son pequeños fragmentos de texto que nuestros servidores envían a su ordenador o dispositivo cuando accede a nuestros servicios.\\n                            Se almacenan en su navegador y después se envían de vuelta a nuestros servidores para que podamos proporcionar contenido contextual.\\n                            Sin cookies, usar la web sería una experiencia mucho más frustrante.\\n                            Las utilizamos para apoyar sus actividades en nuestro sitio web. Por ejemplo, su sesión (para que no tenga que volver a iniciar sesión) o su cesta de compras.\\n                            <br/>\\n                            Las cookies también nos permiten entender sus preferencias según la actividad previa o actual en nuestro sitio web (las páginas que ha\\n                            visitado), su idioma y país, así podemos proporcionarle un mejor servicio.\\n                            También utilizamos las cookies para ayudarnos a recopilar datos agregados sobre el tráfico y las interacciones del sitio para que podamos ofrecer\\n                            mejores experiencias y herramientas en el futuro.\\n                        </p>\\n                        <p>\\n                            Aquí está una vista general de las cookies que se pueden almacenar en su dispositivo cuando visite nuestro sitio web:\\n                        </p>\\n                        <div class=\\"table-responsive\\">\\n                            <table class=\\"small table table-bordered text-center\\">\\n                                <thead class=\\"table-light\\">\\n                                    <tr>\\n                                        <th scope=\\"col\\" style=\\"width: 20%\\">Categoría de cookies</th>\\n                                        <th scope=\\"col\\" style=\\"width: 50%; min-width: 200px;\\">Propósito</th>\\n                                        <th scope=\\"col\\" style=\\"width: 30%\\">Ejemplos</th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <tr>\\n                                        <td>\\n                                            <p>Sesión y seguridad<br/>(esencial)</p>\\n                                        </td>\\n                                        <td>\\n                                            <p>\\n                                                Autentique usuarios, proteja los datos de los usuarios y permita que el sitio web proporcione los servicios que los usuarios esperan,\\n                                                como almacenar el contenido de sus cestas o permitir subir archivos.\\n                                            </p>\\n                                            <p>El sitio web no funcionará correctamente si rechaza o descarta esas cookies.</p>\\n                                        </td>\\n                                        <td>\\n                                            sesión_id (Odoo)<br/>\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td>\\n                                            <p>Preferencias<br/>(esencial)</p>\\n                                        </td>\\n                                        <td>\\n                                            <p>Recuerde información sobre el aspecto o comportamiento preferido del sitio web, como su idioma o región preferidos.</p>\\n                                            <p>Su experiencia puede degradarse si descarta esas cookies, pero el sitio web seguirá funcionando.</p>\\n                                        </td>\\n                                        <td>\\n                                            frontend_lang (Odoo)\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td>Historial de interacciones<br/>(opcional)</td>\\n                                        <td>\\n                                            <p>\\n                                                Utilizado para recopilar información sobre sus interacciones con el sitio web, las páginas que ha visto,\\n                                                y cualquier campaña de marketing específica que le llevó a la página web.\\n                                            </p>\\n                                            <p>Es posible que no podamos proporcionarle el mejor servicio si rechaza esas cookies, pero el sitio web funcionará.</p>\\n                                        </td>\\n                                        <td>\\n                                            im_livechat_previous_operator (Odoo)<br/>\\n                                            utm_campaign (Odoo)<br/>\\n                                            utm_source (Odoo)<br/>\\n                                            utm_medium (Odoo)\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td>\\n                                            <p>Anuncios &amp; marketing<br/>(opcional)</p>\\n                                        </td>\\n                                        <td>\\n                                            <p>\\n                                                Utilizado para hacer publicidad más atractivo para los usuarios y más valioso para los editores y anunciantes,\\n                                                tales como proporcionar anuncios más relevantes cuando usted visita otros sitios web que muestran anuncios o para mejorar la presentación de informes sobre el rendimiento de la campaña publicitaria.\\n                                            </p>\\n                                            <p>Tenga en cuenta que algunos servicios de terceros pueden instalar cookies adicionales en su navegador para identificarlo.</p>\\n                                            <p>\\n                                                Puede descartar el uso de cookies externas si visita la <a class=\\"o_translate_inline\\" href=\\"https://optout.networkadvertising.org/?c=1\\" rel=\\"nofollow\\">página de darse de baja de la Iniciativa de publicidad en red</a>.\\n                                                El sitio web seguirá funcionando si rechaza esas cookies.\\n                                            </p>\\n                                        </td>\\n                                        <td>\\n                                            __gads (Google)<br/>\\n                                            __gac (Google)\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td>\\n                                            <p>Análisis<br/>(opcional)</p>\\n                                        </td>\\n                                        <td>\\n                                            <p>\\n                                                Comprender cómo interactúan los visitantes con nuestro sitio web, a través de Google Analytics.\\n                                                Más información sobre <a class=\\"o_translate_inline\\" href=\\"https://support.google.com/analytics/answer/11397207?hl=en\\">cookies analíticas e información sobre privacidad.</a>\\n                                            </p>\\n                                            <p>El sitio web seguirá funcionando si rechazas o descartas esas cookies.</p>\\n                                        </td>\\n                                        <td>\\n                                            _ga (Google)<br/>\\n                                            _gat (Google)<br/>\\n                                            _gid (Google)<br/>\\n                                            _gac_* (Google)\\n                                        </td>\\n                                    </tr>\\n                                </tbody>\\n                            </table>\\n                        </div>\\n                        <p>\\n                            Puede elegir entre dos opciones: que su ordenador le advierta cada vez que se envía una cookie o desactivar todas las cookies.\\n                            Cada navegador es distinto, así que consulte el menú de Ayuda de su navegador para aprender la forma correcta de modificar sus cookies.\\n                        </p>\\n                        <p>Actualmente no somos compatibles con señales de Do Not Track, ya que no existe un estándar en el sector para el cumplimiento.</p>\\n                    </div>\\n                </section>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Cookie Policy" t-name="website.cookie_policy">\n        <t t-call="website.layout">\n            <div id="wrap" class="oe_structure">\n                <section class="pt8 pb8">\n                    <div class="container">\n                        <h1 class="pt16 h2-fs">Cookie Policy</h1>\n                        <p>\n                            Cookies are small bits of text sent by our servers to your computer or device when you access our services.\n                            They are stored in your browser and later sent back to our servers so that we can provide contextual content.\n                            Without cookies, using the web would be a much more frustrating experience.\n                            We use them to support your activities on our website. For example, your session (so you don't have to login again) or your shopping cart.\n                            <br/>\n                            Cookies are also used to help us understand your preferences based on previous or current activity on our website (the pages you have\n                            visited), your language and country, which enables us to provide you with improved services.\n                            We also use cookies to help us compile aggregate data about site traffic and site interaction so that we can offer\n                            better site experiences and tools in the future.\n                        </p>\n                        <p>\n                            Here is an overview of the cookies that may be stored on your device when you visit our website:\n                        </p>\n                        <div class="table-responsive">\n                            <table class="small table table-bordered text-center">\n                                <thead class="table-light">\n                                    <tr>\n                                        <th scope="col" style="width: 20%">Category of Cookie</th>\n                                        <th scope="col" style="width: 50%; min-width: 200px;">Purpose</th>\n                                        <th scope="col" style="width: 30%">Examples</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <tr>\n                                        <td>\n                                            <p>Session &amp; Security<br/>(essential)</p>\n                                        </td>\n                                        <td>\n                                            <p>\n                                                Authenticate users, protect user data and allow the website to deliver the services users expects,\n                                                such as maintaining the content of their cart, or allowing file uploads.\n                                            </p>\n                                            <p>The website will not work properly if you reject or discard those cookies.</p>\n                                        </td>\n                                        <td>\n                                            session_id (Odoo)<br/>\n                                        </td>\n                                    </tr>\n                                    <tr>\n                                        <td>\n                                            <p>Preferences<br/>(essential)</p>\n                                        </td>\n                                        <td>\n                                            <p>Remember information about the preferred look or behavior of the website, such as your preferred language or region.</p>\n                                            <p>Your experience may be degraded if you discard those cookies, but the website will still work.</p>\n                                        </td>\n                                        <td>\n                                            frontend_lang (Odoo)\n                                        </td>\n                                    </tr>\n                                    <tr>\n                                        <td>Interaction History<br/>(optional)</td>\n                                        <td>\n                                            <p>\n                                                Used to collect information about your interactions with the website, the pages you've seen,\n                                                and any specific marketing campaign that brought you to the website.\n                                            </p>\n                                            <p>We may not be able to provide the best service to you if you reject those cookies, but the website will work.</p>\n                                        </td>\n                                        <td>\n                                            im_livechat_previous_operator (Odoo)<br/>\n                                            utm_campaign (Odoo)<br/>\n                                            utm_source (Odoo)<br/>\n                                            utm_medium (Odoo)\n                                        </td>\n                                    </tr>\n                                    <tr>\n                                        <td>\n                                            <p>Advertising &amp; Marketing<br/>(optional)</p>\n                                        </td>\n                                        <td>\n                                            <p>\n                                                Used to make advertising more engaging to users and more valuable to publishers and advertisers,\n                                                such as providing more relevant ads when you visit other websites that display ads or to improve reporting on ad campaign performance.\n                                            </p>\n                                            <p>Note that some third-party services may install additional cookies on your browser in order to identify you.</p>\n                                            <p>\n                                                You may opt-out of a third-party's use of cookies by visiting the <a class="o_translate_inline" href="https://optout.networkadvertising.org/?c=1" rel="nofollow">Network Advertising Initiative opt-out page</a>.\n                                                The website will still work if you reject or discard those cookies.\n                                            </p>\n                                        </td>\n                                        <td>\n                                            __gads (Google)<br/>\n                                            __gac (Google)\n                                        </td>\n                                    </tr>\n                                    <tr>\n                                        <td>\n                                            <p>Analytics<br/>(optional)</p>\n                                        </td>\n                                        <td>\n                                            <p>\n                                                Understand how visitors engage with our website, via Google Analytics.\n                                                Learn more about <a class="o_translate_inline" href="https://support.google.com/analytics/answer/11397207?hl=en">Analytics cookies and privacy information.</a>\n                                            </p>\n                                            <p>The website will still work if you reject or discard those cookies.</p>\n                                        </td>\n                                        <td>\n                                            _ga (Google)<br/>\n                                            _gat (Google)<br/>\n                                            _gid (Google)<br/>\n                                            _gac_* (Google)\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n                        </div>\n                        <p>\n                            You can choose to have your computer warn you each time a cookie is being sent, or you can choose to turn off all cookies.\n                            Each browser is a little different, so look at your browser's Help menu to learn the correct way to modify your cookies.\n                        </p>\n                        <p>We do not currently support Do Not Track signals, as there is no industry standard for compliance.</p>\n                    </div>\n                </section>\n            </div>\n        </t>\n    </t>\n\n    	f	t	2026-11-24 18:48:00.717396	2026-11-24 18:48:00.717396	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
