1554	16	\N	1	1	Table of Content	\N	website.s_table_of_content	qweb	website/views/snippets/s_table_of_content.xml	primary	{"en_US": "<t name=\\"Table of Content\\" t-name=\\"website.s_table_of_content\\">\\n    <section class=\\"s_table_of_content pt24 pb24 o_cc o_cc1\\">\\n        <div class=\\"container\\">\\n            <div class=\\"row s_nb_column_fixed\\">\\n                <div class=\\"col-lg-3 s_table_of_content_navbar_wrap s_table_of_content_navbar_sticky s_table_of_content_vertical_navbar d-print-none d-none d-lg-block o_not_editable o_cc o_cc1\\" data-name=\\"Navbar\\">\\n                    <div class=\\"s_table_of_content_navbar list-group o_no_link_popover\\" style=\\"top: 76px; max-height: calc(100vh - 96px);\\">\\n                        <a href=\\"#table_of_content_heading_1_1\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0 active\\">Intuitive system</a>\\n                        <a href=\\"#table_of_content_heading_1_2\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0\\">Design features</a>\\n                    </div>\\n                </div>\\n                <div class=\\"col-lg-9 s_table_of_content_main oe_structure oe_empty\\" data-name=\\"Content\\">\\n                    <section class=\\"s_text_block pt0 pb64\\" data-snippet=\\"s_text_block\\" data-name=\\"Section\\">\\n                        <div class=\\"container s_allow_columns\\">\\n                            <h2 id=\\"table_of_content_heading_1_1\\" class=\\"h3-fs\\" data-anchor=\\"true\\">Intuitive system</h2>\\n                            <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                <hr class=\\"w-100 mx-auto\\"/>\\n                            </div>\\n                            <p class=\\"lead\\">\\n                                Our intuitive system ensures effortless navigation for users of all skill levels. Its clean interface and logical organization make tasks easy to complete. With tooltips and contextual help, users quickly become productive, enjoying a smooth and efficient experience.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">What you see is what you get</h3>\\n                            <p>\\n                                Insert text styles like headers, bold, italic, lists, and fonts with a simple WYSIWYG editor. Flexible and easy to use, it lets you design and format documents in real time. No coding knowledge is needed, making content creation straightforward and enjoyable for everyone.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Customization tool</h3>\\n                            <p>\\n                                Click and change content directly from the front-end, avoiding complex backend processes. This tool allows quick updates to text, images, and elements right on the page, streamlining your workflow and maintaining control over your content.\\n                            </p>\\n                        </div>\\n                    </section>\\n                    <section class=\\"s_text_block pt0 pb64\\" data-snippet=\\"s_text_block\\" data-name=\\"Section\\">\\n                        <div class=\\"container s_allow_columns\\">\\n                            <h2 id=\\"table_of_content_heading_1_2\\" class=\\"h3-fs\\" data-anchor=\\"true\\">Design features</h2>\\n                            <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                <hr class=\\"w-100 mx-auto\\"/>\\n                            </div>\\n                            <p class=\\"lead\\">\\n                                Our design features offer a range of tools to create visually stunning websites. Utilize WYSIWYG editors, drag-and-drop building blocks, and Bootstrap-based templates for effortless customization. With professional themes and an intuitive system, you can design with ease and precision, ensuring a polished, responsive result.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Building blocks system</h3>\\n                            <p>\\n                                Create pages from scratch by dragging and dropping customizable building blocks. This system simplifies web design, making it accessible to all skill levels. Combine headers, images, and text sections to build cohesive layouts quickly and efficiently.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Bootstrap-Based Templates</h3>\\n                            <p>\\n                                Design Odoo templates easily with clean HTML and Bootstrap CSS. These templates offer a responsive, mobile-first design, making them simple to customize and perfect for any web project, from corporate sites to personal blogs.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                        </div>\\n                    </section>\\n                </div>\\n            </div>\\n        </div>\\n    </section>\\n</t>", "es_ES": "<t name=\\"Table of Content\\" t-name=\\"website.s_table_of_content\\">\\n    <section class=\\"s_table_of_content pt24 pb24 o_cc o_cc1\\">\\n        <div class=\\"container\\">\\n            <div class=\\"row s_nb_column_fixed\\">\\n                <div class=\\"col-lg-3 s_table_of_content_navbar_wrap s_table_of_content_navbar_sticky s_table_of_content_vertical_navbar d-print-none d-none d-lg-block o_not_editable o_cc o_cc1\\" data-name=\\"Navbar\\">\\n                    <div class=\\"s_table_of_content_navbar list-group o_no_link_popover\\" style=\\"top: 76px; max-height: calc(100vh - 96px);\\">\\n                        <a href=\\"#table_of_content_heading_1_1\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0 active\\">Sistema intuitivo</a>\\n                        <a href=\\"#table_of_content_heading_1_2\\" class=\\"table_of_content_link list-group-item list-group-item-action py-2 border-0 rounded-0\\">Características del diseño</a>\\n                    </div>\\n                </div>\\n                <div class=\\"col-lg-9 s_table_of_content_main oe_structure oe_empty\\" data-name=\\"Content\\">\\n                    <section class=\\"s_text_block pt0 pb64\\" data-snippet=\\"s_text_block\\" data-name=\\"Section\\">\\n                        <div class=\\"container s_allow_columns\\">\\n                            <h2 id=\\"table_of_content_heading_1_1\\" class=\\"h3-fs\\" data-anchor=\\"true\\">Sistema intuitivo</h2>\\n                            <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                <hr class=\\"w-100 mx-auto\\"/>\\n                            </div>\\n                            <p class=\\"lead\\">\\n                                Nuestro sistema es intuitivo para que los usuarios de todos los niveles pueden navegar en él sin dificultad. Su interfaz limpia y organización lógica permiten completar las tareas con facilidad. Además, los usuarios se vuelven productivos con mucha rapidez gracias a la información sobre las herramientas y la ayuda contextual mientras disfrutan de una experiencia fluida y eficiente.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Lo que ve es lo que hay</h3>\\n                            <p>\\n                                Inserte estilos de texto como encabezados, negrita, cursiva, listas y fuentes con un editor WYSIWYG sencillo. Es flexible y fácil de usar, le permite diseñar y darle formato a sus documentos en tiempo real. No es necesario saber programar, así que la creación de contenido es fácil y agradable para todos.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Herramienta de personalización</h3>\\n                            <p>\\n                                Haga clic y cambie el contenido desde el frontend sin tener que lidiar con el backend. Esta herramienta permite editar texto, imágenes y elementos directamente en la página con rapidez para agilizar su flujo de trabajo y mantener el control sobre su contenido.\\n                            </p>\\n                        </div>\\n                    </section>\\n                    <section class=\\"s_text_block pt0 pb64\\" data-snippet=\\"s_text_block\\" data-name=\\"Section\\">\\n                        <div class=\\"container s_allow_columns\\">\\n                            <h2 id=\\"table_of_content_heading_1_2\\" class=\\"h3-fs\\" data-anchor=\\"true\\">Características del diseño</h2>\\n                            <div class=\\"s_hr pt8 pb24\\" data-snippet=\\"s_hr\\" data-name=\\"Separator\\">\\n                                <hr class=\\"w-100 mx-auto\\"/>\\n                            </div>\\n                            <p class=\\"lead\\">\\n                                Nuestras funciones de diseño ofrecen varias herramientas para crear sitios web impresionantes. Use editores WYSIWYG, bloques de creación para arrastrar y soltar y plantillas basadas en Bootstrap para personalizar sus páginas sin complicaciones. Nuestros temas profesionales y sistema intuitivo le permitirán diseñar un sitio web responsivo con facilidad y precisión.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Sistema de bloques de creación</h3>\\n                            <p>\\n                                Arrastre y suelte bloques de creación personalizables para crear páginas desde cero. Este sistema simplifica el diseño web y lo hace accesible para todos. Combine encabezados, imágenes y secciones de texto para elaborar diseños unificados de manera rápida y eficiente.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                            <h3 class=\\"h5-fs\\">Plantillas basadas en Bootstrap</h3>\\n                            <p>\\n                                Diseñe plantillas de Odoo con facilidad gracias a un formato HTML limpio y CSS de Bootstrap. Estas plantillas ofrecen un diseño responsivo y compatible con móviles, lo que facilita su personalización y hace que sean perfectas para cualquier proyecto web, desde sitios corporativos hasta blogs personales.\\n                            </p>\\n                            <br/>\\n                            <br/>\\n                        </div>\\n                    </section>\\n                </div>\\n            </div>\\n        </div>\\n    </section>\\n</t>"}	<?xml version="1.0"?>\n<t name="Table of Content" t-name="website.s_table_of_content">\n    <section class="s_table_of_content pt24 pb24 o_cc o_cc1">\n        <div class="container">\n            <div class="row s_nb_column_fixed">\n                <div class="col-lg-3 s_table_of_content_navbar_wrap s_table_of_content_navbar_sticky s_table_of_content_vertical_navbar d-print-none d-none d-lg-block o_not_editable o_cc o_cc1" data-name="Navbar">\n                    <div class="s_table_of_content_navbar list-group o_no_link_popover" style="top: 76px; max-height: calc(100vh - 96px);">\n                        <a href="#table_of_content_heading_1_1" class="table_of_content_link list-group-item list-group-item-action py-2 border-0 rou