1701	16	1700	1	1	new_page_template_about_full_s_image_text	\N	website.new_page_template_about_full_s_image_text	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_about_s_image_text\\" primary=\\"True\\">\\n    <xpath expr=\\"//section\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" add=\\"o_colored_level pt48 pb56\\" remove=\\"pt80 pb80\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//h2\\" position=\\"replace\\">\\n        <h2>Our Story</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p>Embark on a journey through time as we share the story of our humble beginnings. What started as a simple idea in a garage has evolved into an innovative force in the industry.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_full_s_image_text</attribute></xpath></data>", "es_ES": "<data inherit_id=\\"website.new_page_template_about_s_image_text\\" primary=\\"True\\">\\n    <xpath expr=\\"//section\\" position=\\"attributes\\">\\n        <attribute name=\\"class\\" add=\\"o_colored_level pt48 pb56\\" remove=\\"pt80 pb80\\" separator=\\" \\"/>\\n    </xpath>\\n    <xpath expr=\\"//h2\\" position=\\"replace\\">\\n        <h2>Nuestra historia</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p>Emprenda un viaje a través del tiempo mientras le contamos la historia de nuestro inicio. Lo que empezó como una simple idea en un garaje se ha convertido en un sector innovador.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_full_s_image_text</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_about_s_image_text" primary="True">\n    <xpath expr="//section" position="attributes">\n        <attribute name="class" add="o_colored_level 