ace\\">\\n        <h3 class=\\"h5-fs\\">Backend</h3>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('row')]/div[2]/div/h3\\" position=\\"replace\\">\\n        <h3 class=\\"h5-fs\\">Frontend</h3>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('row')]/div[3]/div/h3\\" position=\\"replace\\">\\n        <h3 class=\\"h5-fs\\">Administración</h3>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('row')]/div[1]/div/p\\" position=\\"replace\\">\\n        <p>Dominio en el desarrollo del backend con especialidad en Python, Django y gestión de bases de datos para crear soluciones eficientes y escalables.</p>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('row')]/div[2]/div/p\\" position=\\"replace\\">\\n        <p>Dominar el frontend con experiencia en HTML, CSS y JavaScript para crear experiencias de usuario cautivadoras y con capacidad de respuesta.</p>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('row')]/div[3]/div/p\\" position=\\"replace\\">\\n        <p>Experiencia en la gestión eficaz de proyectos, capacidad para gestionar equipos multifuncionales y obtener resultados satisfactorios con un enfoque estratégico.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_s_features</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_s_features" primary="True">\n    <xpath expr="//h3" position="replace">\n        <h3 class="h5-fs">My Skills</h3>\n    </xpath>\n    <xpath expr="//div[hasclass('row')]/div[1]/div/h3" position="replace">\n        <h3 class="h5-fs">Backend</h3>\n    </xpath>\n    <xpath expr="//div[hasclass('row')]/div[2]/div/h3" position="replace">\n        <h3 class="h5-fs">Frontend</h3>\n    </xpath>\n    <xpath expr="//div[hasclass('row')]/div[3]/div/h3" position="replace">\n        <h3 class="h5-fs">Management</h3>\n    </xpath>\n    <xpath expr="//div[hasclass('row')]/div[1]/div/p" position="replace">\n        <p>Proficient in backend development, specializing in Python, Django, and database management to create efficient and scalable solutions.</p>\n    </xpath>\n    <xpath expr="//div[hasclass('row')]/div[2]/div/p" position="replace">\n        <p>Mastering frontend craftsmanship with expertise in HTML, CSS, and JavaScript to craft captivating and responsive user experiences.</p>\n    </xpath>\n    <xpath expr="//div[hasclass('row')]/div[3]/div/p" position="replace">\n        <p>Experienced in effective project management, adept at leading cross-functional teams and delivering successful outcomes with a strategic approach.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_about_s_features</attribute></xpath></data>\n\n	f	t	2026-11-24 18:48:00.717396	2026-11-24 18:48:00.717396	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f	f
