n    <xpath expr=\\"(//h2|//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h2 class=\\"card-title h5-fs\\">Seguimiento del progreso</h2>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Nuestros entrenadores expertos diseñan entrenamientos que se adaptan a cada objetivo, nivel de forma física y preferencias.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Consiga un estado de salud integral con consejos nutricionales personalizados que complementen sus entrenamientos, lo que le proporcionará un bienestar general.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Llevamos un seguimiento meticuloso de su progreso, ajustando su plan según sea necesario para garantizar una mejora y unos resultados constantes.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_landing_2_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_landing_s_three_columns" primary="True">\n    <xpath expr="//h2|//h3|//h4|//h5" position="replace">\n        <h2 class="card-title h5-fs">Personalized Workouts</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[2]" position="replace">\n        <h2 class="card-title h5-fs">Nutritional Guidance</h2>\n    </xpath>\n    <xpath expr="(//h2|//h3|//h4|//h5)[3]" position="replace">\n        <h2 class="card-title h5-fs">Progress Tracking</h2>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Our experienced fitness coaches design workouts that align with your goals, fitness level, and preferences.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">Achieve holistic health with personalized nutritional advice that complements your workouts, promoting overall well-bei