lass="figure-img img-fluid rounded" alt="" style="width: 100%;" loading="lazy"/>\n                        <figcaption class="figure-caption text-muted mt-2">\n        Edición especial, tapa dura\n    </figcaption>\n                    </figure>\n                </div>\n            </div>\n        </div>\n    </section><section class="s_title o_cc pt72 pb0 o_colored_level o_cc2" data-vcss="001" data-snippet="s_title" data-name="Título" style="background-color: rgb(236, 198, 236);">\n        <div class="s_allow_columns container">\n            <h2 class="text-align: left;">Los mejores libros</h2>\n    </div>\n    </section><section class="s_masonry_block o_cc o_cc1 pt24 pb104 o_colored_level" data-vcss="001" data-vxml="001" data-oe-shape-data="{'shape':'html_builder/Connections/20','colors':{'c5':'o-color-3'},'flip':['y'],'showOnMobile':true}" data-snippet="s_masonry_block_default_template">\n        <div class="o_we_shape o_html_builder_Connections_20 o_shape_show_mobile" style="background-image: url(&quot;/html_editor/shape/html_builder/Connections/20.svg?c5=o-color-3&amp;flip=y&quot;); background-position: 50% 0%;"/>\n        <div class="container">\n            \n        <div class="row o_grid_mode" data-row-count="8" style="gap: 16px;">\n            <div class="o_grid_item o_grid_item_image g-height-8 g-col-lg-5 col-lg-5 text-center order-lg-0 oe_img_bg o_bg_img_center o_cc o_cc5 overflow-hidden justify-content-end rounded o_colored_level" data-name="Block" style="order: 0;z-index: 1;grid-area: 1 / 1 / 9 / 6;--grid-item-padding-y: 0px;--grid-item-padding-x: 20px;background-image: url('/web/image/website.s_key_images_default_image_1')">\n        <div class="o_we_bg_filter bg-black-50"/>\n        <h2 class="h3-fs" style="text-align: left;">Novela</h2>\n        <p style="text-align: left;">Desde 9 €</p>\n                </div>\n            <div class="o_grid_item g-height-4 g-col-lg-3 col-lg-3 justify-content-end order-lg-0 oe_img_bg o_bg_img_center o_cc o_cc5 overflow-hidden rounded o_colored_level" data-name="Block" style="order: 2;--grid-item-padding-x: 20px;z-index: 2;grid-area: 1 / 6 / 5 / 9;--grid-item-padding-y: 0px;background-image: url('/web/image/website.s_carousel_default_image_1')">\n        <div class="o_we_bg_filter bg-black-50"/>\n                <h2 class="h3-fs">\n        Chile\n    </h2>\n                <p>\n        Desde 18 €\n    </p>\n            </div>\n            <div class="o_grid_item g-height-4 g-col-lg-4 col-lg-4 justify-content-end order-lg-0 oe_img_bg o_bg_img_center o_cc o_cc5 overflow-hidden rounded o_colored_level" data-name="Block" style="order: 1;--grid-item-padding-x: 20px;z-index: 3;grid-area: 1 / 9 / 5 / 13;--grid-item-padding-y: 0px;background-image: url('/web/image/website.s_quotes_carousel_demo_image_2')">\n        <div class="o_we_bg_filter bg-black-50"/>\n                <h2 class="h3-fs">\n        Novela\n    </h2>\n                <p>\n        Desde 15 €\n    </p>\n            </div>\n            <div class="o_grid_item g-height-4 g-col-lg-4 col-lg-4 justify-content-end order-lg-0 oe_img_bg o_bg_img_center o_cc o_cc5 overflow-hidden rounded o_colored_level" data-name="Block" style="order: 3;--grid-item-padding-x: 20px;z-index: 4;grid-area: 5 / 6 / 9 / 10;--grid-item-padding-y: 0px;background-image: url('/web/image/website.s_key_images_default_image_4')">\n        <div class="o_we_bg_filter bg-black-50"/>\n                <h2 class="h3-fs">\n        México\n    </h2>\n                <p>\n        Desde 9 €\n    </p>\n            </div>\n            <div class="o_grid_item g-height-4 g-col-lg-3 col-lg-3 justify-content-end order-lg-0 oe_img_bg o_bg_img_center o_cc o_cc5 overflow-hidden rounded o_colored_level" data-name="Block" style="order: 4;--grid-item-padding-x: 20px;z-index: 5;grid-area: 5 / 10 / 9 / 13;--grid-item-padding-y: 0px;background-image: url('/web/image/website.s_three_columns_default_image_1')">\n        <div class="o_we_bg_filter bg-black-50"/>\n                <h2 class="h3-fs">\n        España\n    </h2>\n                <p>\n        Desde 14 €\n    </p>\n            </div>\n        </div>\n    \n        </div>\n    </section><section class="s_company_team pt72 pb0 o_colored_level" data-snippet="s_company_team" data-name="Equipo">\n        <div class="container">\n            <h2 class="h3-fs">\n        Conozca a nuestros libreros expertos\n    </h2>\n            <p class="lead">Asesores especializados que impulsan nuestro éxito</p>\n            <div class="row">\n                <div class="col-lg-6 pt32 pb32 o_colored_level" data-name="Team Member">\n                    <div class="row s_col_no_resize s_col_no_bgcolor">\n                        <div class="col-lg-3 pb24 o_not_editable">\n                            <img alt="" src="/web/image/website.s_company_team_image_1" class="img-fluid o_editable_media w-lg-100 mx-lg-auto rounded" loading="lazy"/>\n                        </div>\n                        <div class="col-lg-9">\n                            <h3 class="h5-fs">Tony Fred</h3>\n                            <p>\n        Tony se encarga de crear recomendaciones personalizadas y se asegura de que cada libro esté elegido según los gustos de sus clientes.\n    </p>\n                        </div>\n                    </div>\n                </div>\n                <div class="col-lg-6 pt32 pb32 o_colored_level" data-name="Team Member">\n                    <div class="row s_col_no_resize s_col_no_bgcolor">\n                        <div class="col-lg-3 pb24 o_not_editable">\n                            <img alt="" src="/web/image/website.s_company_team_image_2" class="img-fluid o_editable_media w-lg-100 mx-lg-auto rounded" loading="lazy"/>\n                        </div>\n                        <div class="col-lg-9">\n                            <h3 class="h5-fs">Mich Stark</h3>\n                            <p>\n        Mich se asegura de que cada recomendación sea acertada. Su experiencia en libros le ayuda a que los clientes encuentren lecturas que les encanten.\n    </p>\n                        </div>\n                    </div>\n                </div>\n                <div class="col-lg-6 pt32 pb32 o_colored_level" data-name="Team Member">\n                    <div class="row s_col_no_resize s_col_no_bgcolor">\n                        <div class="col-lg-3 pb24 o_not_editable">\n                            <img alt="" src="/web/image/website.s_company_team_image_3" class="img-fluid o_editable_media w-lg-100 mx-lg-auto rounded" loading="lazy"/>\n                        </div>\n                        <div class="col-lg-9">\n                            <h3 class="h5-fs">Aline Turner</h3>\n                            <p>\n        Aline diseña selecciones de lectura personalizadas y colabora con editoriales de todo el mundo para que sus clientes vivan experiencias únicas adaptadas a sus gustos.\n    </p>\n                        </div>\n                    </div>\n                </div>\n                <div class="col-lg-6 pt32 pb32 o_colored_level" data-name="Team Member">\n                    <div class="row s_col_no_resize s_col_no_bgcolor">\n                        <div class="col-lg-3 pb24 o_not_editable">\n                            <img alt="" src="/web/image/website.s_company_team_image_4" class="img-fluid o_editable_media w-lg-100 mx-lg-auto rounded" loading="lazy"/>\n                        </div>\n                        <div class="col-lg-9">\n                            <h3 class="h5-fs">Iris Joe</h3>\n                            <p>\n        Iris selecciona libros a buen precio y garantiza que los lectores disfruten de grandes historias sin renunciar a la calidad de su compra.\n    </p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section><section class="s_showcase pt48 pb104 o_colored_level" data-vcss="003" data-snippet="s_showcase" data-name="Exhibición">\n        <div class="container">\n            <div class="row align-items-center">\n                <div class="col-lg-6 o_colored_level">\n                    <div class="row">\n                        <div class="col-12 pb32 o_colored_level">\n                            <h2 class="h3-fs">\n        ¿Por qué elegir nuestra librería?\n    </h2>\n                            <p class="lead">La sección de novedades destaca los principales títulos de tu librería, atrae a los visitantes y mejora la tasa de conversión.</p>\n                        </div>\n                        <div class="col-12 pt8 pb8 o-float-start-parent o_colored_level" data-name="Feature">\n                            <i class="s_showcase_icon fa fa-star-o me-auto rounded float-start bg-o-color-3" role="img"/>\n                            <div class="d-flex flex-column">\n                                <h3 class="s_showcase_title h5-fs">\n        Recomendaciones literarias de expertos\n    </h3>\n                                <p>\n        Solo elegimos títulos destacados para que su experiencia de lectura sea extraordinaria.\n    </p>\n                            </div>\n                        </div>\n                        <div class="col-12 pt8 pb8 o-float-start-parent o_colored_level" data-name="Feature">\n                            <i class="s_showcase_icon fa fa-user-o me-auto rounded float-start bg-o-color-3" role="img"/>\n                            <div class="d-flex flex-column">\n                                <h3 class="s_showcase_title h5-fs">\n        Novedades literarias\n    </h3>\n                                <p>\n        Su pedido se prepara según sus preferencias para que sea exclusivamente suyo.\n    </p>\n                            </div>\n                        </div>\n                        <div class="col-12 pt8 pb8 o-float-start-parent o_colored_level" data-name="Feature">\n                            <i class="s_showcase_icon fa fa-heart-o me-auto rounded float-start bg-o-color-3" role="img"/>\n                            <div class="d-flex flex-column">\n                                <h3 class="s_showcase_title h5-fs">\n        Una experiencia de lectura perfecta\n    </h3>\n                                <p>\n        Nos encargamos de todos los detalles, desde la selección hasta el envío, para que pueda concentrarse en disfrutar de su lectura.\n    </p>\n                            </div>\n                        </div>\n                        </div>\n                </div>\n                <div class="o_snippet_mobile_invisible d-lg-block d-none col-lg-5 offset-lg-1 o-float-end-parent o_colored_level" data-invisible="1">\n                    <img src="/html_editor/shape/theme_aviato/s_accordion_image.svg?c1=o-color-1" class="img img-fluid ms-auto rounded float-end" alt="" loading="lazy"/>\n                </div>\n            </div>\n        </div>\n    </section><section class="s_quotes_carousel_wrapper" data-vxml="001" data-vcss="002" data-snippet="s_quotes_carousel" data-name="Citas">\n        <div class="s_quotes_carousel s_carousel_boxed carousel slide o_cc o_cc2 o_colored_level" data-bs-ride="true" data-bs-interval="10000" id="myQuoteCarousel868540">\n            \n            <div class="carousel-inner">\n                \n                <div class="carousel-item oe_img_bg o_bg_img_center pt80 pb80 o_colored_level o_bg_img_origin_border_box active" style="background-image: url(&quot;/web/image/website.s_quotes_carousel_demo_image_0&quot;); background-position: 50% 50%;" data-name="Slide">\n                    <blockquote data-name="Blockquote" data-snippet="s_blockquote" class="s_blockquote s_blockquote_with_icon o_cc o_cc1 o_animable position-relative d-flex flex-column gap-4 mx-auto p-5 fst-normal w-75 o_colored_level" data-vcss="001">\n                        <div class="s_blockquote_line_elt position-absolute top-0 start-0 bottom-0 bg-o-color-1"/>\n                        <div class="s_blockquote_wrap_icon position-absolute top-0 start-50 translate-middle w-100">\n                            <i class="s_blockquote_icon fa fa-quote-right d-block mx-auto rounded bg-o-color-1" role="img"/>\n                        </div>\n                        <p class="s_blockquote_quote my-auto h4-fs" style="text-align:center;">\n        Me tomaría mucho tiempo describir los mundos, voces y personajes que encontramos. Nuestra visita a Irlanda fue fantástica.\n    </p>\n                        <div class="s_blockquote_infos d-flex gap-2 flex-column align-items-center w-100 text-center">\n                            <img src="/web/image/website.s_quotes_carousel_demo_image_3" class="s_blockquote_avatar img rounded-circle" alt="" loading="lazy"/>\n                            <div class="s_blockquote_author">\n                                <span class="o_small"><strong> Ana y Sergio </strong><br/> <span class="text-muted"> De Argentina </span></span>\n                            </div>\n                        </div>\n                    </blockquote>\n                </div>\n                \n                <div class="carousel-item oe_img_bg o_bg_img_center pt80 pb80 o_colored_level o_bg_img_origin_border_box" style="background-image: url(&quot;/web/image/website.s_quotes_carousel_demo_image_1&quot;); background-position: 50% 50%;" data-name="Slide">\n                    <blockquote data-name="Blockquote" data-snippet="s_blockquote" class="s_blockquote s_blockquote_with_icon o_cc o_cc1 o_animable position-relative d-flex flex-column gap-4 w-50 mx-auto p-5 fst-normal o_colored_level" data-vcss="001">\n                        <div class="s_blockquote_line_elt position-absolute top-0 start-0 bottom-0 bg-o-color-1"/>\n                        <div class="s_blockquote_wrap_icon position-absolute top-0 start-50 translate-middle w-100">\n                            <i class="s_blockquote_icon fa fa-quote-right d-block mx-auto rounded bg-o-color-1" role="img"/>\n                        </div>\n                        <p class="s_blockquote_quote my-auto h4-fs" style="text-align:center;">\n        Los libros que compramos eran hermosos, el trato fue amable, las recomendaciones excelentes y había mucho por descubrir.\n    </p>\n                        <div class="s_blockquote_infos d-flex gap-2 flex-column align-items-center w-100 text-center">\n                            <img src="/web/image/website.s_quotes_carousel_demo_image_4" class="s_blockquote_avatar img rounded-circle" alt="" loading="lazy"/>\n                            <div class="s_blockquote_author">\n                                <span class="o_small"><strong> Clara y Diego </strong><br/> <span class="text-muted"> De México </span></span>\n                            </div>\n                        </div>\n                    </blockquote>\n                </div>\n                \n                <div class="carousel-item oe_img_bg o_bg_img_center pt80 pb80 o_colored_level o_bg_img_origin_border_box" style="background-image: url(&quot;/web/image/website.s_quotes_carousel_demo_image_2&quot;); background-position: 50% 50%;" data-name="Slide">\n                    <blockquote data-name="Blockquote" data-snippet="s_blockquote" class="s_blockquote s_blockquote_with_icon o_cc o_cc1 o_animable position-relative d-flex flex-column gap-4 w-50 mx-auto p-5 fst-normal o_colored_level" data-vcss="001">\n                        <div class="s_blockquote_line_elt position-absolute top-0 start-0 bottom-0 bg-o-color-1"/>\n                        <div class="s_blockquote_wrap_icon position-absolute top-0 start-50 translate-middle w-100">\n                            <i class="s_blockquote_icon fa fa-quote-right d-block mx-auto rounded bg-o-color-1" role="img"/>\n                        </div>\n                        <p class="s_blockquote_quote my-auto h4-fs" style="text-align:center;">\n        Todo estaba muy bien organizado. ¡Muchas gracias por todo!\n    </p>\n                        <div class="s_blockquote_infos d-flex gap-2 flex-column align-items-center w-100 text-center">\n                            <img src="/web/image/website.s_quotes_carousel_demo_image_5" class="s_blockquote_avatar img rounded-circle" alt="" loading="lazy"/>\n                            <div class="s_blockquote_author">\n                                <span class="o_small"><strong> Marta y Luis </strong><br/> <span class="text-muted"> De España </span></span>\n                            </div>\n                        </div>\n                    </blockquote>\n                </div>\n            </div>\n            \n            <button class="carousel-control-prev o_not_editable" aria-label="Anterior" title="Anterior" data-bs-target="#myQuoteCarousel868540" data-bs-slide="prev">\n                <span class="carousel-control-prev-icon" aria-hidden="true"/> <span class="visually-hidden">Anterior</span>\n            </button>\n            <button class="carousel-control-next o_not_editable" aria-label="Ver más" title="Ver más" data-bs-target="#myQuoteCarousel868540" data-bs-slide="next">\n                <span class="carousel-control-next-icon" aria-hidden="true"/> <span class="visually-hidden">Siguiente</span>\n            </button>\n            \n            <div class="carousel-indicators s_carousel_indicators_dots o_not_editable">\n                <button type="button" class="active" aria-label="Indicador de carrusel" data-bs-target="#myQuoteCarousel868540" data-bs-slide-to="0" aria-current="true"/>\n                <button type="button" aria-label="Indicador de carrusel" data-bs-target="#myQuoteCarousel868540" data-bs-slide-to="1"/>\n                <button type="button" aria-label="Indicador de carrusel" data-bs-target="#myQuoteCarousel868540" data-bs-slide-to="2"/>\n            </div>\n        </div>\n    </section></div>\n        </t>\n    </t>	t	t	2026-11-24 18:48:00.717396	2026-11-25 09:26:12.118476	f	1	\N	\N	\N	\N	\N	{"en_US": "This is the homepage of the website"}	\N	\N	f	t
