ve=\\"pt96 pb96\\" separator=\\" \\"/>\\n        <attribute name=\\"data-oe-shape-data\\">{\\"shape\\": \\"html_builder/Connections/06\\", \\"colors\\": {\\"c5\\": \\"o-color-4\\"}, \\"flip\\": [], \\"showOnMobile\\": false, \\"shapeAnimationSpeed\\": \\"0\\"}</attribute>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('container')]\\" position=\\"before\\">\\n        <div class=\\"o_we_shape o_html_builder_Connections_06\\" style=\\"background-image: url('/html_editor/shape/html_builder/Connections/06.svg?c5=o-color-4');\\"/>\\n    </xpath>\\n    <!-- Title -->\\n    <xpath expr=\\"//h1\\" position=\\"replace\\">\\n        <h1 class=\\"display-3\\">Viajemos<br/>por el mundo</h1>\\n    </xpath>\\n    <!-- Paragraphs -->\\n    <xpath expr=\\"//p[hasclass('lead')]\\" position=\\"replace\\" mode=\\"inner\\">\\n        <br/>Disfrute de las vistas espectaculares de la naturaleza. Relájese y cumpla sus sueños.<br/><br/>\\n    </xpath>\\n    <!-- Button -->\\n    <xpath expr=\\"//a\\" position=\\"replace\\" mode=\\"inner\\">\\n        Explorar ahora\\n    </xpath>\\n    <!-- Card -->\\n    <xpath expr=\\"//p[hasclass('s_blockquote_quote')]\\" position=\\"replace\\" mode=\\"inner\\">\\n        ¡Una experiencia inolvidable! Todos los destinos fueron impresionantes y el servicio fue excelente.\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('s_blockquote_author')]//span//span\\" position=\\"replace\\" mode=\\"inner\\">\\n        Exploró Perú en 2024\\n    </xpath>\\n\\n</data>"}	t	\N	2026-11-24 18:58:53.127734	2026-11-24 18:58:53.127734
64	16	1	1	s_cards_grid	theme_aviato.s_cards_grid	qweb	\N	theme_aviato/views/snippets/s_cards_grid.xml	ir.ui.view,1521	{"en_US": "<data inherit_id=\\"website.s_cards_grid\\">\\n    <!-- Main Title -->\\n    <xpath expr=\\"//h2\\" position=\\"replace\\" mode=\\"inner\\">\\n        Unravel your next adventure\\n    </xpath>\\n    <!-- Card 1 -->\\n    <xpath expr=\\"(//h3)[1]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Relax in Marbella\\n    </xpath>\\n    <xpath expr=\\"(//p)[1]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Marbella is a city on the southern coast of Spain known for its luxurious lifestyle, beautiful beaches, and vibrant nightlife.\\n    </xpath>\\n    <!-- Card 2 -->\\n    <xpath expr=\\"(//h3)[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Rest in Finland\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Enjoy the peace and quiet of Finland's forests and lakes. Rest and relax in one of our best partnered resorts.\\n    </xpath>\\n    <!-- Card 3 -->\\n    <xpath expr=\\"(//h3)[3]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Tan in Thailand\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Known for its stunning beaches Thailand is a Southeast Asian country, enjoy its lush forests and vibrant culture.\\n    </xpath>\\n    <!-- Card 4 -->\\n    <xpath expr=\\"(//h3)[4]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Hike in Switzerland\\n    </xpath>\\n    <xpath expr=\\"(//p)[4]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Switzerland is a mountainous country known its hiking trails. Feel the fresh air and enjoy the beautiful scenery of the Swiss Alps.\\n    </xpath>\\n</data>", "es_ES": "<data inherit_id=\\"website.s_cards_grid\\">\\n    <!-- Main Title -->\\n    <xpath expr=\\"//h2\\" position=\\"replace\\" mode=\\"inner\\">\\n        Descubra su próxima aventura\\n    </xpath>\\n    <!-- Card 1 -->\\n    <xpath expr=\\"(//h3)[1]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Relajación en Marbella\\n    </xpath>\\n    <xpath expr=\\"(//p)[1]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Marbella es una ciudad situada en la costa sur de España conocida por su lujoso estilo de vida, hermosas playas y su animada vida nocturna.\\n    </xpath>\\n    <!-- Card 2 -->\\n    <xpath expr=\\"(//h3)[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Descanso en Finlandia\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Disfrute de la paz y la tranquilidad de los bosques y lagos de Finlandia. Descanse y relájese en uno de los mejores centros turísticos.\\n    </xpath>\\n    <!-- Card 3 -->\\n    <xpath expr=\\"(//h3)[3]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Broncearse en Tailandia\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Tailandia es un país del sudeste asiático que es conocido por sus impresionantes playas, majestuosos bosques y su gran cultura.\\n    </xpath>\\n    <!-- Card 4 -->\\n    <xpath expr=\\"(//h3)[4]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Senderismo en Suiza\\n    </xpath>\\n    <xpath expr=\\"(//p)[4]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Suiza es un país montañoso conocido por sus rutas de senderismo. Sienta el aire fresco y disfrute de la hermosa vista de los Alpes suizos.\\n    </xpath>\\n</data>"}	t	\N	2026-11-24 18:58:53.127734	2026-11-24 18:58:53.127734
