103	16	1	1	s_wavy_grid	theme_aviato.s_wavy_grid	qweb	\N	theme_aviato/views/snippets/s_wavy_grid.xml	ir.ui.view,1600	{"en_US": "<data inherit_id=\\"website.s_wavy_grid\\">\\n    <!-- Layout -->\\n    <xpath expr=\\"//section\\" position=\\"attributes\\">\\n        <attribute name=\\"data-oe-shape-data\\"/>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('o_we_shape')]\\" position=\\"replace\\"/>\\n\\n    <!-- Texts -->\\n    <xpath expr=\\"//h2\\" position=\\"replace\\" mode=\\"inner\\">\\n        What we deliver to our travelers\\n    </xpath>\\n    <xpath expr=\\"//h3\\" position=\\"replace\\" mode=\\"inner\\">\\n        Tailored Journeys\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        We craft personalized itineraries to match your travel dreams. Our team works with you to ensure a seamless adventure from start to finish.\\n    </xpath>\\n    <xpath expr=\\"(//h3)[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Sustainable Travel\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Your satisfaction is our priority. Our support team is always ready to assist, ensuring you have a smooth and memorable journey.\\n    </xpath>\\n    <xpath expr=\\"(//h3)[3]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Quality and Experience\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\" mode=\\"inner\\">\\n        With vast experience and deep travel knowledge, we offer insights and destinations that keep you ahead of the curve.\\n    </xpath>\\n    <xpath expr=\\"(//h3)[4]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Expertise and Adventure\\n    </xpath>\\n    <xpath expr=\\"(//p)[4]\\" position=\\"replace\\" mode=\\"inner\\">\\n        We provide cutting-edge travel solutions to explore the world. Leveraging the latest trends, we help you achieve your travel goals.\\n    </xpath>\\n</data>", "es_ES": "<data inherit_id=\\"website.s_wavy_grid\\">\\n    <!-- Layout -->\\n    <xpath expr=\\"//section\\" position=\\"attributes\\">\\n        <attribute name=\\"data-oe-shape-data\\"/>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('o_we_shape')]\\" position=\\"replace\\"/>\\n\\n    <!-- Texts -->\\n    <xpath expr=\\"//h2\\" position=\\"replace\\" mode=\\"inner\\">\\n        Lo que ofrecemos a nuestros viajeros\\n    </xpath>\\n    <xpath expr=\\"//h3\\" position=\\"replace\\" mode=\\"inner\\">\\n        Viajes personalizados\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        Diseñamos itinerarios personalizados para que haga el viaje de sus sueños. Nuestro equipo trabaja con usted para garantizar que la aventura no tenga interrupciones.\\n    </xpath>\\n    <xpath expr=\\"(//h3)[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Turismo sostenible\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Su satisfacción es nuestra prioridad. Nuestro equipo de soporte siempre está listo para ayudarle para que tenga un viaje memorable sin complicaciones.\\n    </xpath>\\n    <xpath expr=\\"(//h3)[3]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Calidad y experiencia\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Gracias a nuestra amplia experiencia y profundo conocimiento del sector turístico, ofrecemos información y destinos que marcan tendencia.\\n    </xpath>\\n    <xpath expr=\\"(//h3)[4]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Experiencia y aventura\\n    </xpath>\\n    <xpath expr=\\"(//p)[4]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Ofrecemos soluciones de viaje modernas para que explore el mundo. Las últimas tendencias nos permiten ayudarle a realizar su viaje soñado.\\n    </xpath>\\n</data>"}	t	\N	2026-11-24 18:58:53.127734	2026-11-24 18:58:53.127734
104	16	1	1	s_shape_image	theme_aviato.s_shape_image	qweb	\N	theme_aviato/views/snippets/s_shape_image.xml	ir.ui.view,1602	{"en_US": "<data inherit_id=\\"website.s_shape_image\\">\\n    <!-- Title -->\\n    <xpath expr=\\"//h2\\" position=\\"replace\\" mode=\\"inner\\">\\n        Travel services\\n    </xpath>\\n    <!-- Paragraphs -->\\n    <xpath expr=\\"//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        We offer customized travel packages tailored to your preferences. From booking flights and accommodations to organizing tours, our goal is to provide a seamless and enjoyable travel experience.\\n    </xpath>\\n    <xpath expr=\\"//p[2]\\" position=\\"replace\\"/>\\n    <!-- Button -->\\n    <xpath expr=\\"//a[hasclass('btn')]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Join the Experience\\n    </xpath>\\n</data>", "es_ES": "<data inherit_id=\\"website.s_shape_image\\">\\n    <!-- Title -->\\n    <xpath expr=\\"//h2\\" position=\\"replace\\" mode=\\"inner\\">\\n        Servicios turísticos\\n    </xpath>\\n    <!-- Paragraphs -->\\n    <xpath expr=\\"//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        Ofrecemos paquetes de viaje personalizados que se adaptan a sus preferencias, le ayudaremos a reservar vuelos, encontrar alojamiento y organizar recorridos. Nuestro objetivo es proporcionarle una experiencia agradable.\\n    </xpath>\\n    <xpath expr=\\"//p[2]\\" position=\\"replace\\"/>\\n    <!-- Button -->\\n    <xpath expr=\\"//a[hasclass('btn')]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Únase a la experiencia\\n    </xpath>\\n</data>"}	t	\N	2026-11-24 18:58:53.127734	2026-11-24 18:58:53.127734
106	16	1	1	s_text_cover	theme_aviato.s_text_cover	qweb	\N	theme_aviato/views/snippets/s_text_cover.xml	ir.ui.view,1496	{"en_US": "<data inherit_id=\\"website.s_text_cover\\">\\n    <xpath expr=\\"//h1\\" position=\\"replace\\" mode=\\"inner\\">\\n        Plan Trips. <br/>Effortlessly.\\n    </xpath>\\n    <!-- Paragraph -->\\n    <xpath expr=\\"//p[hasclass('lead')]\\" position=\\"replace\\" mode=\\"inner\\">\\n        <br/>Create and manage travel itineraries online with a user-friendly platform that simplifies all the steps, from setup to itinerary management, making it easy to offer seamless travel experiences to your clients.<br/>\\n    </xpath>\\n    <!-- Button -->\\n    <xpath expr=\\"//a[hasclass('btn')]/t\\" position=\\"replace\\" mode=\\"inner\\">\\n        Get started\\n    </xpath>\\n</data>", "es_ES": "<data inherit_id=\\"website.s_text_cover\\">\\n    <xpath expr=\\"//h1\\" position=\\"replace\\" mode=\\"inner\\">\\n        Planifique viajes <br/>con facilidad\\n    </xpath>\\n    <!-- Paragraph -->\\n    <xpath expr=\\"//p[hasclass('lead')]\\" position=\\"replace\\" mode=\\"inner\\">\\n        <br/>Cree y gestione itinerarios de viaje en línea desde una plataforma fácil de usar que simplifica todos los pasos incluyendo su configuración y gestión, además de que le permite ofrecer increíbles experiencias de viaje a sus clientes.<br/>\\n    </xpath>\\n    <!-- Button -->\\n    <xpath expr=\\"//a[hasclass('btn')]/t\\" position=\\"replace\\" mode=\\"inner\\">\\n        Empezar\\n    </xpath>\\n</data>"}	t	\N	2026-11-24 18:58:53.127734	2026-11-24 18:58:53.127734
107	16	1	1	s_empowerment	theme_aviato.s_empowerment	qweb	\N	theme_aviato/views/snippets/s_empowerment.xml	ir.ui.view,1603	{"en_US": "<data inherit_id=\\"website.s_empowerment\\">\\n    <!-- Badge content -->\\n    <xpath expr=\\"//span[hasclass('s_cta_badge')]\\" position=\\"replace\\" mode=\\"inner\\">\\n        <i class=\\"fa fa-fw fa-info-circle o_not-animable\\" role=\\"img\\"/>  Exclusive Travel Deals     \\n        <a href=\\"#\\">View Our Offers   <i class=\\"fa fa-long-arrow-right\\" role=\\"img\\"/></a>\\n    </xpath>\\n    <!-- Title -->\\n    <xpath expr=\\"//h1\\" position=\\"replace\\" mode=\\"inner\\">\\n       Explore with<br/>GlobeTrek Travel\\n    </xpath>\\n    <!-- Paragraphs -->\\n    <xpath expr=\\"//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        <br/>Your gateway to unforgettable adventures and dream destinations.<br/><br/>\\n    </xpath>\\n    <!-- Button -->\\n    <xpath expr=\\"//a[hasclass('btn')][1]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Explore Destinations\\n    </xpath>\\n    <!-- Second Button -->\\n    <xpath expr=\\"//a[hasclass('btn')][2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Plan Your Trip\\n    </xpath>\\n</data>", "es_ES": "<data inherit_id=\\"website.s_empowerment\\">\\n    <!-- Badge content -->\\n    <xpath expr=\\"//span[hasclass('s_cta_badge')]\\" position=\\"replace\\" mode=\\"inner\\">\\n        <i class=\\"fa fa-fw fa-info-circle o_not-animable\\" role=\\"img\\"/>  Ofertas exclusivas de viaje     \\n        <a href=\\"#\\">Ver nuestras ofertas   <i class=\\"fa fa-long-arrow-right\\" role=\\"img\\"/></a>\\n    </xpath>\\n    <!-- Title -->\\n    <xpath expr=\\"//h1\\" position=\\"replace\\" mode=\\"inner\\">\\n       Explore con <br/>GlobeTrek Travel\\n    </xpath>\\n    <!-- Paragraphs -->\\n    <xpath expr=\\"//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        <br/>Su puerta de entrada a aventuras inolvidables y destinos de ensueño.<br/><br/>\\n    </xpath>\\n    <!-- Button -->\\n    <xpath expr=\\"//a[hasclass('btn')][1]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Explorar los destinos\\n    </xpath>\\n    <!-- Second Button -->\\n    <xpath expr=\\"//a[hasclass('btn')][2]\\" position=\\"replace\\" mode=\\"inner\\">\\n        Planifique su viaje\\n    </xpath>\\n</data>"}	t	\N	2026-11-24 18:58:53.127734	2026-11-24 18:58:53.127734
110	16	1	1	s_split_intro	theme_aviato.s_split_intro	qweb	\N	theme_aviato/views/snippets/s_split_intro.xml	ir.ui.view,1604	{"en_US": "<data inherit_id=\\"website.s_split_intro\\">\\n    <!-- Title -->\\n    <xpath expr=\\"//h1\\" position=\\"replace\\" mode=\\"inner\\">\\n        Transform your<br/>travel experience\\n    </xpath>\\n    <!-- Paragraph -->\\n    <xpath expr=\\"//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        <br/>Experience a new way to travel with our agency. We combine advanced technology and personalized service to revolutionize your journey. Whether you're after adventure or relaxation, we create custom trips that turn your travel dreams into reality.<br/><br/>\\n    </xpath>\\n</data>", "es_ES": "<data inherit_id=\\"website.s_split_intro\\">\\n    <!-- Title -->\\n    <xpath expr=\\"//h1\\" position=\\"replace\\" mode=\\"inner\\">\\n        Transforme su<br/>experiencia de viaje\\n    </xpath>\\n    <!-- Paragraph -->\\n    <xpath expr=\\"//p\\" position=\\"replace\\" mode=\\"inner\\">\\n        <br/>Viva una nueva forma de viajar con nuestra agencia. Revolucionaremos sus viajes con tecnología avanzada y servicio personalizado. No importa si busca vivir la aventura o relajarse, creamos viajes personalizados que harán que sus sueños de viaje se vuelvan realidad.<br/><br/>\\n    </xpath>\\n</data>"}	t	\N	2026-11-24 18:58:53.127734	2026-11-24 18:58:53.127734
